module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wrstn,
    input winc,
    input [WIDTH-1:0] wdata,
    input rclk,
    input rrstn,
    input rinc,
    output wfull,
    output rempty,
    output [WIDTH-1:0] rdata
);


reg [3:0] waddr_bin;
wire [3:0] wptr;
assign wptr = (waddr_bin >> 1) ^ waddr_bin;


reg [3:0] raddr_bin;
wire [3:0] rptr;
assign rptr = (raddr_bin >> 1) ^ raddr_bin;


reg [3:0] rptr_wclk_sync1, rptr_wclk_sync;
always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rptr_wclk_sync1 <= 4'b0;
        rptr_wclk_sync <= 4'b0;
    end else begin
        rptr_wclk_sync1 <= rptr;
        rptr_wclk_sync <= rptr_wclk_sync1;
    end
end


reg [3:0] wptr_rclk_sync1, wptr_rclk_sync;
always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        wptr_rclk_sync1 <= 4'b0;
        wptr_rclk_sync <= 4'b0;
    end else begin
        wptr_rclk_sync1 <= wptr;
        wptr_rclk_sync <= wptr_rclk_sync1;
    end
end


assign rempty = (rptr == wptr_rclk_sync);
assign wfull = (wptr[3] != wptr_rclk_sync[3]) && 
               (wptr[2] != wptr_rclk_sync[2]) && 
               (wptr[1:0] == wptr_rclk_sync[1:0]);


wire wen, ren;
assign wen = winc && !wfull;
assign ren = rinc && !rempty;


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn)
        waddr_bin <= 4'b0;
    else if (wen)
        waddr_bin <= waddr_bin + 1;
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn)
        raddr_bin <= 4'b0;
    else if (ren)
        raddr_bin <= raddr_bin + 1;
end


dual_port_RAM ram (
    .wclk(wclk),
    .wenc(wen),
    .waddr(waddr_bin),
    .wdata(wdata),
    .rclk(rclk),
    .renc(ren),
    .raddr(raddr_bin),
    .rdata(rdata)
);

endmodule

module dual_port_RAM #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wenc,
    input [$clog2(DEPTH)-1:0] waddr,
    input [WIDTH-1:0] wdata,
    input rclk,
    input renc,
    input [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

always @(posedge wclk) begin
    if (wenc)
        RAM_MEM[waddr] <= wdata;
end

always @(posedge rclk) begin
    if (renc)
        rdata <= RAM_MEM[raddr];
end

endmodule

