module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];

reg [2:0] SP;

integer i;

always @(posedge Clk) begin
    if (Rst) begin
        SP <= 3'b100;

        EMPTY <= 1'b1;
        FULL <= 1'b0;
        dataOut <= 4'b0;
        for (i = 0;
 i < 4;
 i = i + 1) begin
            stack_mem[i] <= 4'b0;
        end
    end else if (EN) begin
        reg [2:0] next_SP;
        reg [3:0] next_dataOut;
        reg next_EMPTY;
        reg next_FULL;


        next_SP = SP;
        next_dataOut = dataOut;
        next_EMPTY = EMPTY;
        next_FULL = FULL;


        if (!RW) begin
            if (!FULL) begin
                stack_mem[SP - 1] <= dataIn;
                next_SP = SP - 1;
            end
        end 

        else begin
            if (!EMPTY) begin
                next_dataOut = stack_mem[SP];
                next_SP = SP + 1;
            end
        end


        next_EMPTY = (next_SP == 3'b100);

        next_FULL = (next_SP == 3'b000);



        SP <= next_SP;
        dataOut <= next_dataOut;
        EMPTY <= next_EMPTY;
        FULL <= next_FULL;
    end
end

endmodule

