module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    localparam S0 = 2'b00;
    localparam S1 = 2'b01;
    localparam S2 = 2'b10;

    reg [1:0] state, next_state;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= S0;
            data_out <= 1'b0;
        end else begin
            state <= next_state;
            data_out <= (state == S2) && (~data_in);
        end
    end

    always @(*) begin
        case (state)
            S0: next_state = data_in ? S1 : S0;
            S1: next_state = (data_in == 1'b0) ? S2 : S0;
            S2: next_state = (data_in == 1'b0) ? S0 : S0;
            default: next_state = S0;
        endcase
    end

endmodule

