            ADDU: begin
                res_33 = {1'b0, a} + {1'b0, b};
                r = res_33[31:0];
                carry = res_33[32];
                overflow = 1'b0;
            end
            SUB: begin
                res_33 = {1'b0, a} - {1'b0, b};
                r = res_33[31:0];
                carry = ~res_33[32];

