module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [15:0] SR_reg;
    reg [3:0] cnt_reg;
    reg start_cnt_reg;
    reg [7:0] abs_dividend_reg;
    reg [7:0] abs_divisor_reg;
    reg [7:0] NEG_DIVISOR_reg;
    reg sign_reg;
    reg dividend_sign_reg;
    reg divisor_sign_reg;
    reg [15:0] result_reg;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 1'b0;
            SR_reg <= 16'b0;
            cnt_reg <= 4'b0;
            start_cnt_reg <= 1'b0;
            abs_dividend_reg <= 8'b0;
            abs_divisor_reg <= 8'b0;
            NEG_DIVISOR_reg <= 8'b0;
            sign_reg <= 1'b0;
            dividend_sign_reg <= 1'b0;
            divisor_sign_reg <= 1'b0;
            result_reg <= 16'b0;
        end else begin
            if (opn_valid && !res_valid) begin
                sign_reg <= sign;
                dividend_sign_reg <= sign ? dividend[7] : 1'b0;
                divisor_sign_reg <= sign ? divisor[7] : 1'b0;
                abs_dividend_reg <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                abs_divisor_reg <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
                NEG_DIVISOR_reg <= -abs_divisor_reg;
                SR_reg <= {abs_dividend_reg, 8'b0} << 1;
                cnt_reg <= 4'd1;
                start_cnt_reg <= 1'b1;
                res_valid <= 1'b0;
            end else if (start_cnt_reg) begin
                if (cnt_reg == 4'd8) begin
                    start_cnt_reg <= 1'b0;
                    cnt_reg <= 4'd0;
                    res_valid <= 1'b1;
                    if (sign_reg) begin
                        reg [7:0] quotient = (dividend_sign_reg ^ divisor_sign_reg) ? -SR_reg[7:0] : SR_reg[7:0];
                        reg [7:0] remainder = (dividend_sign_reg) ? -SR_reg[15:8] : SR_reg[15:8];
                        result_reg <= {remainder, quotient};
                    end else begin
                        result_reg <= SR_reg;
                    end
                end else begin
                    reg [7:0] remainder = SR_reg[15:8];
                    reg [7:0] sub_result = remainder - NEG_DIVISOR_reg;
                    reg borrow = (remainder < NEG_DIVISOR_reg);
                    if (borrow) begin
                        SR_reg <= {sub_result, 1'b0, SR_reg[7:1]};
                    end else begin
                        SR_reg <= {sub_result, 1'b1, SR_reg[7:1]};
                    end
                    cnt_reg <= cnt_reg + 4'd1;
                end
            end
            if (res_valid && opn_valid) begin
                result <= result_reg;
                res_valid <= 1'b0;
            end
        end
    end

endmodule

