module comparator_4bit (
    input [3:0] A,
    input [3:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

    wire [4:0] sub_result;
    wire carry_out, borrow;
    wire [3:0] diff;

    assign sub_result = A + (~B) + 1;
    assign carry_out = sub_result[4];
    assign borrow = ~carry_out;

    assign diff = sub_result[3:0];

    assign A_less = borrow;
    assign A_greater = carry_out && (diff != 4'b0);
    assign A_equal = (diff == 4'b0) && carry_out;

endmodule

