module fixed_point_adder #(
    parameter Q = 2,    
    parameter N = 4     
) (
    input  [N-1:0] a,
    input  [N-1:0] b,
    output [N-1:0] c
);

reg [N-1:0] res;

always @(*) begin
    reg a_sign, b_sign;
    reg [N-1:0] a_abs, b_abs;

    a_sign = a[N-1];
    b_sign = b[N-1];

    if (a_sign == b_sign) begin
        res = a + b;
    end else begin
        a_abs = a_sign ? (~a + 1) : a;
        b_abs = b_sign ? (~b + 1) : b;

        if (a_abs > b_abs) begin
            res = a_abs - b_abs;
        end else begin
            res = b_abs - a_abs;
        end
    end
end

assign c = res;

endmodule

