module fixed_point_subtractor #(
    parameter Q = 8,
    parameter N = 16
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;
reg a_sign, b_sign;

always @(*) begin
    a_sign = a[N-1];
    b_sign = b[N-1];
    if (a_sign == b_sign) begin
        res = a - b;
    end else begin

        reg [N-1:0] abs_a = a_sign ? (-a) : a;
        reg [N-1:0] abs_b = b_sign ? (-b) : b;
        reg [N:0] sum_magnitude = abs_a + abs_b;


        reg sum_sign;
        if (sum_magnitude == 0) begin
            sum_sign = 1'b0;

        end else if (a_sign == 1'b0) begin 
            sum_sign = (abs_a > abs_b) ? 1'b0 : 1'b1;
        end else begin 
            sum_sign = 1'b1;
        end


        res = {sum_sign, sum_magnitude[N-2:0]};
    end
end

assign c = res;

endmodule

