module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [8:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa;
    reg [23:0] z_mantissa;
    reg [47:0] product;
    reg guard, round, sticky;
    reg overflow, underflow;
    reg special_case;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 0;
            a_sign <= 0;
            b_sign <= 0;
            z_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            z_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            product <= 0;
            guard <= 0;
            round <= 0;
            sticky <= 0;
            z_mantissa <= 0;
            overflow <= 0;
            underflow <= 0;
            special_case <= 0;
            z <= 0;
        end else begin
            case (counter)
                3'd0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= {1'b0, a[30:23]};
                    b_exponent <= {1'b0, b[30:23]};
                    a_mantissa <= {1'b1, a[22:0]};
                    b_mantissa <= {1'b1, b[22:0]};
                    counter <= 1;
                end

                3'd1: begin

                    if (a_exponent == 9'h0ff || b_exponent == 9'h0ff) begin
                        special_case <= 1;
                        z_sign <= a_sign ^ b_sign;
                        if (a_exponent == 9'h0ff) begin
                            if (a_mantissa != 0) begin
                                z_exponent <= 9'h0ff;
                                z_mantissa <= 23'h000001;
                            end else begin
                                z_exponent <= 9'h0ff;
                                z_mantissa <= 0;
                            end
                        end else begin
                            if (b_mantissa != 0) begin
                                z_exponent <= 9'h0ff;
                                z_mantissa <= 23'h000001;
                            end else begin
                                z_exponent <= 9'h0ff;
                                z_mantissa <= 0;
                            end
                        end
                    end else if (a_exponent == 0 || b_exponent == 0) begin
                        special_case <= 1;
                        z_sign <= a_sign ^ b_sign;
                        if (a_exponent == 0) begin
                            if (a_mantissa == 0) begin
                                z_exponent <= 0;
                                z_mantissa <= 0;
                            end else begin
                                z_exponent <= b_exponent;
                                z_mantissa <= b_mantissa;
                            end
                        end else begin
                            if (b_mantissa == 0) begin
                                z_exponent <= 0;
                                z_mantissa <= 0;
                            end else begin
                                z_exponent <= a_exponent;
                                z_mantissa <= a_mantissa;
                            end
                        end
                    end else begin
                        special_case <= 0;
                        product <= a_mantissa * b_mantissa;
                        if (product[47]) begin
                            product <= product >> 1;
                            z_exponent <= a_exponent + b_exponent - 9'd127 + 1;
                        end else begin
                            z_exponent <= a_exponent + b_exponent - 9'd127;
                        end
                        guard <= product[22];
                        round <= product[21];
                        sticky <= |product[20:0];
                    end
                    counter <= 2;
                end

                3'd2: begin

                    if (special_case) begin
                        z <= {z_sign, z_exponent[7:0], z_mantissa};
                        counter <= 0;
                    end else begin

                        if (guard && (round || sticky || z_mantissa[0])) begin
                            z_mantissa <= z_mantissa + 1;
                            if (z_mantissa == 24'h1000000) begin
                                z_exponent <= z_exponent + 1;
                                z_mantissa <= 0;
                            end
                        end

                        if (z_exponent >= 9'h1fe) begin
                            overflow <= 1;
                            z_exponent <= 9'h0ff;
                            z_mantissa <= 0;
                        end else if (z_exponent == 0 && z_mantissa != 0) begin
                            underflow <= 1;
                            z_exponent <= 0;
                            z_mantissa <= 0;
                        end

                        z <= {z_sign, z_exponent[7:0], z_mantissa[22:0]};
                        counter <= 0;
                    end
                end

                default: counter <= 0;
            endcase
        end
    end

endmodule

