module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

reg [1:0] state_reg;

localparam IDLE    = 2'd0;
localparam GOT_HIGH = 2'd1;
localparam GOT_LOW = 2'd2;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state_reg <= IDLE;
        data_out <= 1'b0;
    end else begin
        case (state_reg)
            IDLE: begin
                if (data_in) begin
                    state_reg <= GOT_HIGH;
                end else begin
                    state_reg <= IDLE;
                end
                data_out <= 1'b0;
            end
            GOT_HIGH: begin
                if (!data_in) begin
                    state_reg <= GOT_LOW;
                end else begin
                    state_reg <= GOT_HIGH;
                end
                data_out <= 1'b0;
            end
            GOT_LOW: begin
                state_reg <= IDLE;
                data_out <= 1'b1;
            end
            default: begin
                state_reg <= IDLE;
                data_out <= 1'b0;
            end
        endcase
    end
end

endmodule

