module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] dividend_reg, divisor_reg;
reg sign_reg;
reg [16:0] sr;

reg [3:0] cnt;
reg start_cnt;
reg [7:0] divisor_abs;
reg [7:0] dividend_abs;
reg q_sign, r_sign;
reg [7:0] quotient, remainder;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 1'b0;
        sr <= 17'b0;
        cnt <= 4'b0;
        start_cnt <= 1'b0;
        result <= 16'b0;
        dividend_reg <= 8'b0;
        divisor_reg <= 8'b0;
        sign_reg <= 1'b0;
        q_sign <= 1'b0;
        r_sign <= 1'b0;
        quotient <= 8'b0;
        remainder <= 8'b0;
    end else begin
        if (opn_valid && !res_valid) begin

            sign_reg <= sign;
            if (sign) begin
                dividend_abs <= (dividend[7]) ? (-dividend) : dividend;
                divisor_abs <= (divisor[7]) ? (-divisor) : divisor;
                q_sign <= dividend[7] ^ divisor[7];
                r_sign <= dividend[7];
            end else begin
                dividend_abs <= dividend;
                divisor_abs <= divisor;
                q_sign <= 1'b0;
                r_sign <= 1'b0;
            end
            dividend_reg <= dividend;
            divisor_reg <= divisor;

            sr <= { (dividend_abs << 1), 8'b0 };
            start_cnt <= 1'b1;
            cnt <= 4'd1;
            res_valid <= 1'b0;
        end else if (start_cnt) begin
            if (cnt <= 8) begin

                wire [16:0] shifted_sr = sr << 1;
                wire [8:0] divisor_ext = {1'b0, divisor_abs};
                wire [8:0] sub_result = shifted_sr[16:8] - divisor_ext;
                wire carry_out = sub_result[8];


                if (carry_out) begin

                    sr <= { shifted_sr[16:8], (shifted_sr[7:0] << 1) | 1'b0 };
                end else begin

                    sr <= { sub_result, (shifted_sr[7:0] << 1) | 1'b1 };
                end
                cnt <= cnt + 1;
            end else begin

                start_cnt <= 1'b0;
                cnt <= 4'b0;


                quotient <= sr[7:0];
                remainder <= sr[16:9];


                if (q_sign) begin
                    quotient <= ~quotient + 1;
                end
                if (r_sign) begin
                    remainder <= ~remainder + 1;
                end


                result <= { remainder, quotient };
                res_valid <= 1'b1;
            end
        end


        if (res_valid && opn_valid) begin
            res_valid <= 1'b0;
        end
    end
end

endmodule

