module fixed_point_adder #(
    parameter Q = 2,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;
reg sign_res;
reg [N-1:0] result_abs;

wire sign_a = a[N-1];
wire sign_b = b[N-1];

wire [N-1:0] a_abs = sign_a ? (-a) : a;
wire [N-1:0] b_abs = sign_b ? (-b) : b;

always @(*) begin
    if (sign_a == sign_b) begin

        result_abs = a_abs + b_abs;
        sign_res = sign_a;
    end else begin

        if (a_abs > b_abs) begin
            result_abs = a_abs - b_abs;
            sign_res = sign_a;
        end else if (b_abs > a_abs) begin
            result_abs = b_abs - a_abs;
            sign_res = sign_b;
        end else begin
            result_abs = 0;
            sign_res = 0;
        end
    end
    res = {sign_res, result_abs[N-2:0]};
    c = res;
end

endmodule

