module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg a_sign, b_sign, z_sign;
reg [7:0] a_exponent, b_exponent, sum_exponent, z_exponent;
reg [22:0] a_mantissa, b_mantissa;
reg [23:0] a_mantissa_full, b_mantissa_full;
reg [47:0] product;
reg guard_bit, round_bit, sticky;
reg [23:0] rounded_mantissa;
reg [9:0] z_exponent_ext;
reg is_nan, is_inf, is_zero;

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
        z <= 32'b0;
        a_sign <= 0;
        b_sign <= 0;
        a_exponent <= 0;
        b_exponent <= 0;
        a_mantissa <= 0;
        b_mantissa <= 0;
        is_nan <= 0;
        is_inf <= 0;
        is_zero <= 0;
    end else begin
        case (counter)
            3'b000: begin

                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= a[22:0];
                b_mantissa <= b[22:0];

                is_nan <= (a[30:23] == 8'hFF && a[22:0] != 0) || (b[30:23] == 8'hFF && b[22:0] != 0);
                is_inf <= (a[30:23] == 8'hFF && a[22:0] == 0) || (b[30:23] == 8'hFF && b[22:0] == 0);
                is_zero <= (a_exponent == 0 && a_mantissa == 0) || (b_exponent == 0 && b_mantissa == 0);

                counter <= counter + 1;
            end
            3'b001: begin

                a_mantissa_full <= {1'b1, a_mantissa};
                b_mantissa_full <= {1'b1, b_mantissa};
                product <= a_mantissa_full * b_mantissa_full;

                if (is_nan || (is_inf && is_zero)) begin
                    z_sign <= a_sign ^ b_sign;
                    z <= {a_sign ^ b_sign, 8'hFF, 23'h1};

                    counter <= 3'b111;
                end else if (is_inf) begin
                    z_sign <= a_sign ^ b_sign;
                    z <= {a_sign ^ b_sign, 8'hFF, 23'h0};

                    counter <= 3'b111;
                end else if (is_zero) begin
                    z <= {a_sign ^ b_sign, 31'h0};

                    counter <= 3'b111;
                end else begin
                    sum_exponent <= a_exponent + b_exponent - 10'd127;
                    counter <= counter + 1;
                end
            end
            3'b010: begin

                if (product >= 48'h800000000000) begin
                    product <= product >> 1;
                    sum_exponent <= sum_exponent + 10'd1;
                end

                guard_bit <= product[23];
                round_bit <= product[22];
                sticky <= |product[21:0];


                if (guard_bit) begin
                    rounded_mantissa <= product[46:23] + 24'h1;
                    if (rounded_mantissa[23]) begin 
                        rounded_mantissa <= rounded_mantissa >> 1;
                        sum_exponent <= sum_exponent + 10'd1;
                    end
                end else begin
                    rounded_mantissa <= product[46:23];
                end

                z_exponent_ext <= sum_exponent;
                counter <= counter + 1;
            end
            3'b011: begin

                if (z_exponent_ext > 10'h1FE) begin 
                    z <= {z_sign, 8'hFF, 23'h0};
                end else if (z_exponent_ext < 10'h1) begin 
                    z <= {z_sign, 31'h0};
                end else begin
                    z <= {z_sign, z_exponent_ext[7:0], rounded_mantissa[22:0]};
                end
                counter <= 3'b0;
            end
            default: counter <= 3'b0;
        endcase
    end
end

endmodule

