reg [2:0] SP;

integer i;

always @(posedge Clk) begin
    if (Rst) begin

        for (i = 0;
 i < 4;
 i = i + 1)
            stack_mem[i] <= 4'b0;
        SP <= 3'd4;
    end
    else if (EN) begin
        if (!RW) begin 
            if (SP != 3'd0) begin 
                stack_mem[SP - 1] <= dataIn;

                SP <= SP - 1;

            end
        end
        else begin 
            if (SP != 3'd4) begin 
                dataOut <= stack_mem[SP];

                stack_mem[SP] <= 4'b0;

                SP <= SP + 1;

            end
        end
    end
end


assign EMPTY = (SP == 3'd4);
assign FULL  = (SP == 3'd0);

