module alu (
    input [31:0] a, b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);

    parameter ADD = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND = 6'b100100;
    parameter OR = 6'b100101;
    parameter XOR = 6'b100110;
    parameter NOR = 6'b100111;
    parameter SLT = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL = 6'b000000;
    parameter SRL = 6'b000010;
    parameter SRA = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI = 6'b001111;

    reg [31:0] res;
    reg carry_reg, overflow_reg;

    wire signed [31:0] signed_a = $signed(a);
    wire signed [31:0] signed_b = $signed(b);
    wire [4:0] shamt = a[4:0];


    wire [32:0] add_sum = {1'b0, a} + {1'b0, b};
    wire [32:0] sub_diff = {1'b0, a} - {1'b0, b};


    wire [31:0] sll_val = b << shamt;
    wire [31:0] srl_val = b >> shamt;
    wire [31:0] sra_val = signed_b >>> shamt;

    wire [31:0] sllv_val = b << a[4:0];
    wire [31:0] srlv_val = b >> a[4:0];
    wire [31:0] srav_val = signed_b >>> a[4:0];


    wire [31:0] slt_res = (signed_a < signed_b) ? 32'd1 : 32'd0;
    wire [31:0] sltu_res = (a < b) ? 32'd1 : 32'd0;


    wire [31:0] lui_res = {a[31:16], 16'b0};


    always @(*) begin
        case (aluc)
            ADD: res = add_sum[31:0];
            ADDU: res = a + b;
            SUB: res = sub_diff[31:0];
            SUBU: res = a - b;
            AND: res = a & b;
            OR: res = a | b;
            XOR: res = a ^ b;
            NOR: res = ~(a | b);
            SLT: res = slt_res;
            SLTU: res = sltu_res;
            SLL: res = sll_val;
            SRL: res = srl_val;
            SRA: res = sra_val;
            SLLV: res = sllv_val;
            SRLV: res = srlv_val;
            SRAV: res = srav_val;
            LUI: res = lui_res;
            default: res = 32'bz;
        endcase
    end


    assign zero = (res == 32'b0);
    assign negative = res[31];
    assign flag = (aluc == SLT || aluc == SLTU) ? res[0] : 1'bz;


    always @(*) begin
        case (aluc)
            ADD: begin
                carry_reg = add_sum[32];
                overflow_reg = (a[31] == b[31]) && (res[31] != a[31]);
            end
            SUB: begin
                carry_reg = sub_diff[32];
                overflow_reg = (a[31] != b[31]) && (res[31] != a[31]);
            end
            ADDU, SUBU: begin
                carry_reg = 1'b0;
                overflow_reg = 1'b0;
            end
            default: begin
                carry_reg = 1'b0;
                overflow_reg = 1'b0;
            end
        endcase
    end

    assign carry = carry_reg;
    assign overflow = overflow_reg;

    assign r = res;

endmodule

