module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] abs_dividend, abs_divisor;
reg sign_quotient, sign_remainder;
reg [15:0] SR;
reg [3:0] cnt;
reg start_cnt;
wire [8:0] divisor_neg;
wire [8:0] sub_res;
wire carry_out;


always @(*) begin
    if (sign) begin
        abs_dividend = dividend[7] ? (~dividend + 1) : dividend;
        abs_divisor = divisor[7] ? (~divisor + 1) : divisor;
        sign_quotient = dividend[7] ^ divisor[7];
        sign_remainder = dividend[7];
    end else begin
        abs_dividend = dividend;
        abs_divisor = divisor;
        sign_quotient = 1'b0;
        sign_remainder = 1'b0;
    end
end

assign divisor_neg = -{1'b0, abs_divisor};

assign sub_res = {1'b0, SR[15:8]} - divisor_neg;
assign carry_out = ~sub_res[8];



always @(posedge clk) begin
    if (rst) begin
        res_valid <= 1'b0;
        SR <= 16'b0;
        cnt <= 4'b0;
        start_cnt <= 1'b0;
        result <= 16'b0;
    end else begin
        if (opn_valid && !res_valid && !start_cnt) begin
            SR <= {7'b0, abs_dividend, 1'b0};

            start_cnt <= 1'b1;
            cnt <= 4'b1;
        end

        if (start_cnt) begin
            if (cnt == 8) begin
                start_cnt <= 1'b0;
                res_valid <= 1'b1;
                cnt <= 4'b0;
            end else begin
                if (carry_out) begin
                    SR <= {sub_res[7:0], SR[7:1], 1'b1};
                end else begin
                    SR <= {SR[14:0], 1'b0};
                end
                cnt <= cnt + 1;
            end
        end

        if (res_valid) begin
            result <= { 
                (sign && sign_remainder) ? (~SR[7:0] + 1) : SR[7:0],
                (sign && sign_quotient) ? (~SR[15:8] + 1) : SR[15:8]
            };
            res_valid <= ~opn_valid;

        end
    end
end

endmodule

