  input rst_n,
  input [3:0] mul_a,
  input [3:0] mul_b,
  output [7:0] mul_out
);

  parameter size = 4;


  wire [7:0] mul_a_ext = {4'b0, mul_a};
  wire [7:0] mul_b_ext = {4'b0, mul_b};


  reg [7:0] a_reg, b_reg;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      a_reg <= 8'd0;
      b_reg <= 8'd0;
    end else begin
      a_reg <= mul_a_ext;
      b_reg <= mul_b_ext;
    end
  end


  wire [7:0] pp0 = b_reg[0] ? (a_reg << 0) : 8'd0;
  wire [7:0] pp1 = b_reg[1] ? (a_reg << 1) : 8'd0;
  wire [7:0] pp2 = b_reg[2] ? (a_reg << 2) : 8'd0;
  wire [7:0] pp3 = b_reg[3] ? (a_reg << 3) : 8'd0;


  wire [7:0] sum1 = pp0 + pp1;
  wire [7:0] sum2 = sum1 + pp2 + pp3;


  reg [7:0] stage1, stage2;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      stage1 <= 8'd0;
      stage2 <= 8'd0;
    end else begin
      stage1 <= sum1;
      stage2 <= sum2;
    end
  end

  assign mul_out = stage2;

endmodule

