module multi_16bit (
    input clk,
    input rst_n,
    input start,
    input [15:0] ain,
    input [15:0] bin,
    output reg [31:0] yout,
    output reg done
);

reg [15:0] areg, breg;
reg [4:0] i;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        areg <= 16'b0;
        breg <= 16'b0;
        yout <= 32'b0;
        i <= 5'b0;
        done <= 1'b0;
    end else begin

        if (start) begin
            if (i < 5'd17)
                i <= i + 1;
        end else
            i <= 5'b0;


        if (i == 5'd0 && start) begin
            areg <= ain;
            breg <= bin;
        end


        if (i == 5'd16)
            done <= 1'b1;
        else if (i == 5'd17)
            done <= 1'b0;


        if (start && i > 5'd0 && i < 5'd17) begin
            if (areg[i-1])
                yout <= yout + ( {16'b0, breg} << (i-1) );
        end
    end
end

endmodule

