module fixed_point_adder #(
    parameter Q = 3,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

    reg [N-1:0] res;
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];
    reg [N-1:0] a_abs, b_abs;

    always @(*) begin
        if (a_sign == b_sign) begin
            res = a + b;
        end else begin
            a_abs = a_sign ? (~a + 1) : a;
            b_abs = b_sign ? (~b + 1) : b;
            if (a_abs > b_abs) begin
                res = a - b;
            end else begin
                res = b - a;
            end
        end
    end

    assign c = res;

endmodule

