module fixed_point_subtractor #(
    parameter Q = 8,
    parameter N = 32
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;

always @(*) begin
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];
    wire same_sign = (a_sign == b_sign);
    wire [N-1:0] a_abs = a_sign ? (~a + 1) : a;
    wire [N-1:0] b_abs = b_sign ? (~b + 1) : b;

    if (same_sign) begin
        res = a - b;
        if (res == 0) begin
            res = {1'b0, res[N-2:0]};
        end else begin
            res[N-1] = a_sign;
        end
    end else begin
        if (a_abs > b_abs) begin
            res = a_abs - b_abs;
            res[N-1] = 1'b0;
        end else begin
            res = b_abs - a_abs;
            res[N-1] = 1'b1;
        end
    end

    c = res;
end

endmodule

