module sub_64bit (
    input [63:0] A,
    input [63:0] B,
    output [63:0] result,
    output overflow
);

    assign result = $signed(A) - $signed(B);

    wire positive_overflow = (~A[63] & B[63] & result[63]);
    wire negative_overflow = (A[63] & ~B[63] & ~result[63]);

    assign overflow = positive_overflow | negative_overflow;

endmodule

