    assign wptr_gray = {wptr_bin[3], wptr_bin[3] ^ wptr_bin[2], 
                        wptr_bin[2] ^ wptr_bin[1], wptr_bin[1] ^ wptr_bin[0]};
    assign rptr_gray = {rptr_bin[3], rptr_bin[3] ^ rptr_bin[2], 
                        rptr_bin[2] ^ rptr_bin[1], rptr_bin[1] ^ rptr_bin[0]};

    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_syn1 <= 4'b0;
            rptr_syn <= 4'b0;
        end else begin
            rptr_syn1 <= rptr_gray;
            rptr_syn <= rptr_syn1;
        end
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            wptr_syn1 <= 4'b0;
            wptr_syn <= 4'b0;
