            if (valid_in) begin
                stored_data <= data_in;
                stored_flag <= 1'b1;
                temp_valid <= 1'b0;
            end else begin
                temp_valid <= 1'b0;
            end
        end


        valid_out <= temp_valid;
        data_out <= temp_data;
    end
end

