module signal_generator (
    input clk,
    input rst_n,
    output reg [4:0] wave
);

reg state;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        state <= 1'b0;
        wave <= 5'b0;
    end else begin
        case (state)
            1'b0: begin
                wave <= wave + 1;
                if (wave == 5'b11111)
                    state <= 1'b1;
            end
            1'b1: begin
                wave <= wave - 1;
                if (wave == 5'b00000)
                    state <= 1'b0;
            end
        endcase
    end
end

endmodule

