                cnt2 <= 0;
            else
                cnt2 <= cnt2 + 1;

            if (cnt2 == (NUM_DIV - 1) / 2)
                clk_div2 <= ~clk_div2;
        end
    end

    assign clk_div = clk_div1 | clk_div2;

