module freq_divbyfrac (
    input clk,
    input rst_n,
    output clk_div
);

reg [2:0] counter;
reg prev_clk;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
        prev_clk <= 1'b0;
    else
        prev_clk <= clk;
end

wire edge_pulse;
assign edge_pulse = (prev_clk != clk);


always @(posedge clk, negedge rst_n) begin
    if (!rst_n)
        counter <= 3'b0;
    else if (edge_pulse) begin
        if (counter == 3'd6)
            counter <= 3'b0;
        else
            counter <= counter + 3'd1;
    end
end


wire clk1 = (counter >= 3'd0 && counter <= 3'd3) ? 1'b1 : 1'b0;
wire clk2 = (counter >= 3'd1 && counter <= 3'd4) ? 1'b1 : 1'b0;


assign clk_div = clk1 || clk2;

endmodule

