module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] saved_dividend_abs, saved_divisor_abs;
reg sign_reg;
reg [3:0] cnt;
reg start_cnt;
reg [15:0] SR;
reg [15:0] NEG_DIVISOR;
reg res_valid_reg;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        saved_dividend_abs <= 0;
        saved_divisor_abs <= 0;
        sign_reg <= 0;
        cnt <= 0;
        start_cnt <= 0;
        SR <= 0;
        NEG_DIVISOR <= 0;
        result <= 0;
    end else begin
        res_valid <= res_valid_reg;
        if (opn_valid && !res_valid) begin

            saved_dividend_abs <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
            saved_divisor_abs <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
            sign_reg <= sign;

            SR <= {saved_dividend_abs, 8'b0};
            NEG_DIVISOR <= -saved_divisor_abs;
            cnt <= 1;
            start_cnt <= 1;
            res_valid_reg <= 0;
        end else if (start_cnt) begin
            if (cnt < 8) begin

                wire [16:0] sum = SR + NEG_DIVISOR;
                wire carry_out = sum[16];
                SR <= {sum[15:0], carry_out};
                cnt <= cnt + 1;
            end else begin

                start_cnt <= 0;
                res_valid_reg <= 1;

                reg [7:0] quotient, remainder;
                quotient = SR[7:0];
                remainder = SR[15:8];
                if (sign_reg) begin

                    if (saved_dividend_abs[7] ^ saved_divisor_abs[7])
                        quotient = -quotient;

                    if (saved_dividend_abs[7])
                        remainder = -remainder;
                end
                result <= {remainder, quotient};
            end
        end
    end
end

endmodule

