module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [7:0] a_reg;
reg [7:0] b_reg;

always @(*) begin
    a_reg = A;
    b_reg = B;
end

always @(*) begin
    reg [15:0] quotient = 16'b0;
    reg [15:0] remainder = a_reg;
    integer i;

    for (i = 0;
 i < 16;
 i = i + 1) begin
        if (remainder >= {8'b0, b_reg}) begin
            quotient[i] = 1'b1;
            remainder = (remainder - {8'b0, b_reg}) << 1;
        end else begin
            quotient[i] = 1'b0;
            remainder = remainder << 1;
        end
        if (i < 15) begin
            remainder[0] = A[15 - i];
        end
    end

    result = quotient;
    odd = remainder;
end

endmodule

