genvar i;
for (i = 1;
 i <= 16;
 i = i + 1) begin : gen_p_g
    assign p[i] = A[i] ^ B[i];
    assign g[i] = A[i] & B[i];
end
endgenerate


assign P = &p;


generate
for (i = 1;
 i <= 16;
 i = i + 1) begin : gen_G_P_prev
    if (i == 1) begin
        assign G_prev[i] = g[i];
        assign P_prev[i] = p[i];
    end else begin
        assign G_prev[i] = g[i] | (p[i] & G_prev[i-1]);
        assign P_prev[i] = p[i] & P_prev[i-1];
    end
end
endgenerate


wire [16:1] c_in_bits;
assign c_in_bits[1] = c_in;

generate
for (i = 2;
 i <= 16;
 i = i + 1) begin : gen_c_in
    assign c_in_bits[i] = G_prev[i-1] | (P_prev[i-1] & c_in);
end
endgenerate


generate
for (i = 1;
 i <= 16;
 i = i + 1) begin : gen_S
    assign S[i] = p[i] ^ c_in_bits[i];
