generate
for (i = 1;
 i <= 16;
 i = i + 1) begin : gen_G_terms
    if (i == 16) begin
        assign G_terms[i] = g[i];
    end else begin
        assign G_terms[i] = g[i] & (&p[i+1:16]);
    end
