module fixed_point_adder #(
    parameter Q = 2,
    parameter N = 4
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;
    wire a_MSB = a[N-1];
    wire b_MSB = b[N-1];

    wire [N-1:0] a_abs = a_MSB ? (~a + 1) : a;
    wire [N-1:0] b_abs = b_MSB ? (~b + 1) : b;

    always @* begin
        if (a_MSB == b_MSB) begin
            res = a_abs + b_abs;
        end else begin
            if (a_abs > b_abs) begin
                res = a_abs - b_abs;
            end else begin
                res = b_abs - a_abs;
            end
        end
    end

    assign c = res;

endmodule

