module fixed_point_subtractor #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

reg signed [N-1:0] a_signed, b_signed;
reg signed [N-1:0] res_signed;
reg [N-2:0] a_abs, b_abs;

always @(*) begin
    a_signed = a;
    b_signed = b;

    if (a_signed == 0 || b_signed == 0) begin
        res_signed = a_signed - b_signed;
    end else if (a_signed >= 0 && b_signed >= 0) begin
        res_signed = a_signed - b_signed;
    end else if (a_signed < 0 && b_signed < 0) begin
        res_signed = a_signed - b_signed;
    end else begin
        a_abs = a_signed < 0 ? (~a_signed + 1) : a_signed;
        b_abs = b_signed < 0 ? (~b_signed + 1) : b_signed;

        if (a_abs > b_abs) begin
            res_signed = a_signed + b_signed;
        end else begin
            res_signed = b_signed + a_signed;
        end
    end


    if (res_signed == 0) begin
        res_signed = 0;
    end

    c = res_signed;
end

endmodule

