module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [8:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa;
    reg [48:0] product;
    reg guard_bit, round_bit, sticky;


    wire a_is_nan = (a_exponent == 9'h1FE) && (a_mantissa != 0);
    wire b_is_nan = (b_exponent == 9'h1FE) && (b_mantissa != 0);
    wire a_is_inf = (a_exponent == 9'h1FE) && (a_mantissa == 0);
    wire b_is_inf = (b_exponent == 9'h1FE) && (b_mantissa == 0);
    wire a_is_zero = (a_exponent == 0) && (a_mantissa == 0);
    wire b_is_zero = (b_exponent == 0) && (b_mantissa == 0);

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'h0;
        end else begin
            case (counter)
                3'b0: begin 
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= {1'b0, a[30:23]};
                    b_exponent <= {1'b0, b[30:23]};
                    a_mantissa <= (a_exponent[7] ? {1'b1, a[22:0]} : {1'b0, a[22:0]});
                    b_mantissa <= (b_exponent[7] ? {1'b1, b[22:0]} : {1'b0, b[22:0]});
                    counter <= 3'b1;
                end
                3'b1: begin 
                    if (a_is_nan || b_is_nan) begin
                        z <= {a_sign ^ b_sign, 9'h1FE, 23'h1};
                    end else if (a_is_inf) begin
                        z <= (b_is_zero) ? {a_sign ^ b_sign, 9'h1FE, 23'h1} : {a_sign ^ b_sign, 9'h1FE, 23'h0};
                    end else if (b_is_inf) begin
                        z <= (a_is_zero) ? {a_sign ^ b_sign, 9'h1FE, 23'h1} : {a_sign ^ b_sign, 9'h1FE, 23'h0};
                    end else if (a_is_zero) begin
                        z <= {a_sign ^ b_sign, 31'h0};
                    end else if (b_is_zero) begin
                        z <= {a_sign ^ b_sign, 31'h0};
                    end else begin
                        counter <= 3'b2;
                    end
                end
                3'b2: begin 
                    z_exponent <= a_exponent + b_exponent - 9'd254;
                    counter <= 3'b3;
                end
                3'b3: begin 
                    product <= a_mantissa * b_mantissa;
                    counter <= 3'b4;
                end
                3'b4: begin 
                    if (product[48]) begin 
                        product <= product[48:1];
                        z_exponent <= z_exponent + 1;
                    end else if (product[47]) begin 
                        product <= product >> 1;
                        z_exponent <= z_exponent + 1;
                    end
                    guard_bit <= product[0];
                    round_bit <= product[1];
                    sticky <= |product[2:0];
                    counter <= 3'b5;
                end
                3'b5: begin 
                    if (guard_bit) begin
                        if (round_bit || sticky) begin
                            product <= product + 1;
                        end
                    end
                    counter <= 3'b6;
                end
                3'b6: begin 
                    if (z_exponent[8] || (z_exponent == 0 && product[47:23] != 0)) begin 
                        z <= {z_sign, 9'h1FE, 23'h0};
                    end else if (z_exponent < 9'd1) begin 
                        z <= {z_sign, 9'h0, product[22:0] >> (1 - z_exponent)};
                    end else begin
                        z <= {z_sign, z_exponent[7:0], product[22:0]};
                    end
                    counter <= 3'b0;
                end
                default: counter <= 3'b0;
            endcase
        end
    end

endmodule

