module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

reg [1:0] state;
parameter state0 = 2'b00,
          state1 = 2'b01,
          state2 = 2'b10;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        state <= state0;
        data_out <= 1'b0;
    end else begin
        case (state)
            state0: begin
                if (data_in == 1'b0) begin
                    state <= state1;
                    data_out <= 1'b0;
                end else begin
                    state <= state0;
                    data_out <= 1'b0;
                end
            end
            state1: begin
                if (data_in == 1'b1) begin
                    state <= state2;
                    data_out <= 1'b0;
