                    state <= state1;
                    data_out <= 1'b0;
                end
            end
            state2: begin
                if (data_in == 1'b0) begin
                    state <= state0;
                    data_out <= 1'b1;
                end else begin
                    state <= state0;
                    data_out <= 1'b0;
                end
            end
            default: begin
                state <= state0;
                data_out <= 1'b0;
            end
        endcase
    end
end

