module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

parameter idle = 2'b00;
parameter s1_red = 2'b01;
parameter s2_yellow = 2'b10;
parameter s3_green = 2'b11;

reg [7:0] cnt;
reg [1:0] state;
reg p_red, p_yellow, p_green;


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
    end else begin
        case (state)
            idle: state <= s1_red;
            s1_red: if (cnt == 3) state <= s3_green else state <= s1_red;
            s3_green: if (cnt == 3) state <= s2_yellow else state <= s3_green;
            s2_yellow: if (cnt == 3) state <= s1_red else state <= s2_yellow;
            default: state <= idle;
        endcase
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 10;
    end else begin
        if (pass_request && green) begin
            cnt <= 10;
        end else if (!green && p_green) begin
            cnt <= 60;
        end else if (!yellow && p_yellow) begin
            cnt <= 5;
        end else if (!red && p_red) begin
            cnt <= 10;
        end else begin
            cnt <= cnt - 1;
        end
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        red <= 0;
        yellow <= 0;
        green <= 0;
    end else begin
        red <= p_red;
        yellow <= p_yellow;
        green <= p_green;
    end
end


always @(*) begin
    case (state)
        idle: {p_red, p_yellow, p_green} = 3'b000;
        s1_red: {p_red, p_yellow, p_green} = 3'b100;
        s3_green: {p_red, p_yellow, p_green} = 3'b001;
        s2_yellow: {p_red, p_yellow, p_green} = 3'b010;
        default: {p_red, p_yellow, p_green} = 3'b000;
    endcase
end

assign clock = cnt;

endmodule

