module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] dividend_abs, divisor_abs;
reg dividend_sign, divisor_sign;
reg [15:0] SR;
reg [3:0] cnt;
reg start_cnt;
reg [7:0] NEG_DIVISOR;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        result <= 16'b0;
        dividend_abs <= 8'b0;
        divisor_abs <= 8'b0;
        dividend_sign <= 0;
        divisor_sign <= 0;
        SR <= 16'b0;
        cnt <= 4'b0;
        start_cnt <= 0;
        NEG_DIVISOR <= 8'b0;
    end else begin
        if (opn_valid && !res_valid) begin
            dividend_sign <= sign ? dividend[7] : 0;
            divisor_sign <= sign ? divisor[7] : 0;
            dividend_abs <= sign ? (-dividend) : dividend;
            divisor_abs <= sign ? (-divisor) : divisor;
            NEG_DIVISOR <= -divisor_abs;
            SR <= {7'b0, dividend_abs, 1'b0};
            cnt <= 4'd1;
            start_cnt <= 1;
            res_valid <= 0;
        end else if (start_cnt) begin
            if (cnt <= 8) begin
                reg [15:0] shifted_SR = SR << 1;
                reg [15:0] sub_result = shifted_SR - {{8{NEG_DIVISOR[7]}}, NEG_DIVISOR};
                if (sub_result[15]) begin
                    SR <= shifted_SR;
                end else begin
                    SR <= sub_result;
                end
                cnt <= cnt + 1;
            end else begin
                reg [7:0] remainder = SR[15:8];
                reg [7:0] quotient = SR[7:0];
                reg [7:0] remainder_adj = remainder;
                reg [7:0] quotient_adj = quotient;

                if (sign) begin
                    if (dividend_sign && !divisor_sign) begin
                        remainder_adj = -remainder;
                    end
                    if (dividend_sign != divisor_sign) begin
                        quotient_adj = -quotient;
                    end
                end

                result <= {remainder_adj, quotient_adj};
                res_valid <= 1;
                start_cnt <= 0;
                cnt <= 0;
            end
        end else if (res_valid) begin
            if (opn_valid) begin
                res_valid <= 0;
            end
        end
    end
end

endmodule

