module fixed_point_adder #(
    parameter Q = 2, 
    parameter N = 4   
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

    reg [N-1:0] res;

    wire sign_a = a[N-1];
    wire sign_b = b[N-1];

    wire [N-1:0] magnitude_a = sign_a ? (~a + 1) : a;
    wire [N-1:0] magnitude_b = sign_b ? (~b + 1) : b;

    reg [N-1:0] sum_magnitude;
    reg result_sign;

    always @(*) begin
        if (sign_a == sign_b) begin
            sum_magnitude = magnitude_a + magnitude_b;
            result_sign = sign_a;
        end else begin
            if (magnitude_a > magnitude_b) begin
                sum_magnitude = magnitude_a - magnitude_b;
                result_sign = sign_a;
            end else if (magnitude_b > magnitude_a) begin
                sum_magnitude = magnitude_b - magnitude_a;
                result_sign = sign_b;
            end else begin
                sum_magnitude = 0;
                result_sign = 0;
            end
        end


        if (sign_a == sign_b && sum_magnitude[N-1]) begin
            sum_magnitude = {1'b0, {(N-1){1'b1}}};
            result_sign = sign_a;
        end
    end

    assign res = {result_sign, sum_magnitude[N-2:0]};
    assign c = res;

endmodule

