    same_sign = (a[N-1] == b[N-1]);

    if (same_sign) begin
        a_sub = a - b;
        if (a_sub == 0)
            c = {1'b0, a_sub[N-2:0]};
        else
            c = a_sub;
    end else begin
        a_abs = a[N-1] ? (~a + 1) : a;
        b_abs = b[N-1] ? (~b + 1) : b;
        sum_mag = a_abs + b_abs;
        sign_diff = (a_abs > b_abs) ? a[N-1] : ~a[N-1];
        if (sum_mag == 0)
            c = 0;
        else
            c = {sign_diff, sum_mag[N-2:0]};
    end
end

endmodule

