module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign;
    reg [7:0] a_exponent, b_exponent;
    reg [23:0] a_mantissa, b_mantissa;
    reg [49:0] product;
    reg guard_bit, round_bit, sticky;
    reg [8:0] final_exponent;
    reg [22:0] final_mantissa;
    reg final_sign;
    reg is_nan, is_inf, is_zero;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
            a_sign <= 0;
            b_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            product <= 0;
            final_exponent <= 0;
            final_mantissa <= 0;
            final_sign <= 0;
            is_nan <= 0;
            is_inf <= 0;
            is_zero <= 0;
            guard_bit <= 0;
            round_bit <= 0;
            sticky <= 0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a[30:23] == 8'b0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b[30:23] == 8'b0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                    is_nan <= (a[30:23] == 8'hFF && |a[22:0]) || (b[30:23] == 8'hFF && |b[22:0]);
                    is_inf <= (a[30:23] == 8'hFF && ~|a[22:0]) || (b[30:23] == 8'hFF && ~|b[22:0]);
                    is_zero <= (a[30:23] == 8'h00 && ~|a[22:0]) || (b[30:23] == 8'h00 && ~|b[22:0]);
                    counter <= counter + 1;
                end
                3'b001: begin

                    product <= a_mantissa * b_mantissa;

                    final_exponent <= (a_exponent[7] ? (a_exponent - 9'd127) : a_exponent) + 
                                     (b_exponent[7] ? (b_exponent - 9'd127) : b_exponent) - 9'd127;
                    counter <= counter + 1;
                end
                3'b010: begin

                    reg [5:0] leading_one;
                    integer i;
                    leading_one = 6'd0;
                    for (i = 49;
 i >= 0;
 i = i - 1) begin
                        if (product[i]) begin
                            leading_one = i;
                            disable find_leading_one;
                        end
