module sub_64bit(
    input [63:0] A,
    input [63:0] B,
    output [63:0] result,
    output overflow
);

    assign result = A - B;

    wire sign_A = A[63];
    wire sign_B = B[63];
    wire sign_result = result[63];

    wire positive_overflow = (~sign_A) & sign_B & sign_result;
    wire negative_overflow = sign_A & (~sign_B) & (~sign_result);

    assign overflow = positive_overflow | negative_overflow;

endmodule

