module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wresetn,
    input winc,
    input [WIDTH-1:0] wdata,
    output wfull,
    input rclk,
    input rresetn,
    input rinc,
    output rempty,
    output [WIDTH-1:0] rdata
);


    wire [2:0] waddr = waddr_bin[2:0];

    wire [2:0] raddr = raddr_bin[2:0];
    wire wen = winc && !wfull;
    wire renc = rinc && !rempty;

    dual_port_RAM #(
        .DEPTH(DEPTH),
        .WIDTH(WIDTH)
    ) ram (
        .wclk(wclk),
        .wenc(wen),
        .waddr(waddr),
        .wdata(wdata),
        .rclk(rclk),
        .renc(renc),
        .raddr(raddr),
        .rdata(rdata)
    );


    reg [3:0] waddr_bin;
    always @(posedge wclk or negedge wresetn) begin
        if (!wresetn) waddr_bin <= 0;
        else if (wen) waddr_bin <= waddr_bin + 1;
    end


    reg [3:0] raddr_bin;
    always @(posedge rclk or negedge rresetn) begin
        if (!rresetn) raddr_bin <= 0;
        else if (renc) raddr_bin <= raddr_bin + 1;
    end


    wire [3:0] wptr = (waddr_bin >> 1) ^ waddr_bin;
    wire [3:0] rptr = (raddr_bin >> 1) ^ raddr_bin;


    reg [3:0] rptr_sync1, rptr_sync;
    reg [3:0] wptr_sync1, wptr_sync;


    always @(posedge wclk or negedge wresetn) begin
        if (!wresetn) {rptr_sync1, rptr_sync} <= 0;
        else {rptr_sync1, rptr_sync} <= {rptr, rptr_sync1};
    end


    always @(posedge rclk or negedge rresetn) begin
        if (!rresetn) {wptr_sync1, wptr_sync} <= 0;
        else {wptr_sync1, wptr_sync} <= {wptr, wptr_sync1};
    end


    assign wfull = (wptr[3] != rptr_sync[3]) && (wptr[2] != rptr_sync[2]) && (wptr[1:0] == rptr_sync[1:0]);
    assign rempty = (rptr == wptr_sync);

