module LIFObuffer (
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output wire EMPTY,
    output wire FULL,
    output wire [3:0] dataOut
);

    reg [3:0] stack_mem [0:3];

    reg [2:0] SP;

    reg [3:0] dataOut_reg;

    assign EMPTY = (SP == 3'b100);

    assign FULL = (SP == 3'b000);

    assign dataOut = dataOut_reg;

    always @(posedge Clk) begin
        if (Rst) begin

            SP <= 3'b100;
            dataOut_reg <= 4'b0;
            stack_mem[0] <= 4'b0;
            stack_mem[1] <= 4'b0;
            stack_mem[2] <= 4'b0;
            stack_mem[3] <= 4'b0;
        end else if (EN) begin
            if (!FULL) begin 
                if (!RW) begin
                    stack_mem[SP - 1] <= dataIn;
                    SP <= SP - 1;
                end
            end
            if (!EMPTY) begin 
                if (RW) begin
                    dataOut_reg <= stack_mem[SP];
                    stack_mem[SP] <= 4'b0;
                    SP <= SP + 1;
                end
            end
        end
    end

endmodule

