module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    reg state_reg;
    localparam IDLE = 1'b0;
    localparam FIRST_1 = 1'b1;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state_reg <= IDLE;
            data_out <= 1'b0;
        end else begin
            case (state_reg)
                IDLE: begin
                    if (data_in) begin
                        state_reg <= FIRST_1;
                        data_out <= 1'b0;
                    end else begin
                        state_reg <= IDLE;
                        data_out <= 1'b0;
                    end
                end
                FIRST_1: begin
                    if (data_in) begin
                        state_reg <= FIRST_1;
                        data_out <= 1'b0;
                    end else begin
                        state_reg <= IDLE;
                        data_out <= 1'b1;
                    end
                end
                default: begin
                    state_reg <= IDLE;
                    data_out <= 1'b0;
                end
            endcase
        end
    end

endmodule

