module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);


    parameter idle = 2'b00;
    parameter s1_red = 2'b01;
    parameter s2_yellow = 2'b10;
    parameter s3_green = 2'b11;

    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case (state)
                idle: state <= s1_red;
                s1_red: if (cnt == 10) state <= s3_green;
                s3_green: if (cnt == 60) state <= s2_yellow;
                s2_yellow: if (cnt == 5) state <= s1_red;
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (pass_request && green)
                cnt <= 10;
            else if (!green && p_green)
                cnt <= 60;
            else if (!yellow && p_yellow)
                cnt <= 5;
            else if (!red && p_red)
                cnt <= 10;
            else
                cnt <= cnt - 1;
        end
    end


    always @(*) begin
        case (state)
            s1_red: {p_red, p_yellow, p_green} = 3'b100;
            s2_yellow: {p_red, p_yellow, p_green} = 3'b010;
            s3_green: {p_red, p_yellow, p_green} = 3'b001;
            default: {p_red, p_yellow, p_green} = 3'b000;
        endcase
    end


    reg r_red, r_yellow, r_green;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            {r_red, r_yellow, r_green} <= 3'b000;
        end else begin
            {r_red, r_yellow, r_green} <= {p_red, p_yellow, p_green};
        end
    end

    assign {red, yellow, green} = {r_red, r_yellow, r_green};
    assign clock = cnt;

endmodule

