wire [8:0] sub_result = upper_bits - NEG_DIVISOR;
wire carry_out = ~sub_result[8];

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        result <= 0;
        saved_dividend <= 0;
        saved_divisor <= 0;
        saved_sign_dividend <= 0;
        saved_sign_divisor <= 0;
        SR <= 0;
        cnt <= 0;
        NEG_DIVISOR <= 0;
        computing <= 0;
        start_cnt <= 0;
        abs_quotient <= 0;
        abs_remainder <= 0;
    end else begin
