        end else if (opn_valid && !res_valid) begin

            saved_dividend <= dividend;
            saved_divisor <= divisor;
            saved_sign_dividend <= dividend[7];
            saved_sign_divisor <= divisor[7];
            NEG_DIVISOR <= -(divisor[7] ? (~divisor + 1) : divisor);
            SR <= {abs_dividend, 8'b0} << 1;
            start_cnt <= 1;
            computing <= 1;
            cnt <= 1;
            abs_quotient <= 0;
            abs_remainder <= 0;
        end else if (res_valid) begin
            res_valid <= 0;
        end
    end
end

