module fixed_point_adder #(
    parameter Q = 8,
    parameter N = 16
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

    reg [N-1:0] res;
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];
    wire [N-1:0] a_abs = a_sign ? (~a + 1) : a;
    wire [N-1:0] b_abs = b_sign ? (~b + 1) : b;
    wire a_gt_b = (a_abs > b_abs);
    wire a_eq_b = (a_abs == b_abs);

    always @(*) begin
        if (a_sign == b_sign) begin

            res = {a_sign, (a_abs + b_abs)[N-2:0]};
        end else begin

            if (a_gt_b) begin
                res = {a_sign, (a_abs - b_abs)};
            end else if (a_eq_b) begin
                res = {1'b0, {N-1{1'b0}}};
            end else begin
                res = {b_sign, (b_abs - a_abs)};
            end
        end
    end

    assign c = res;

endmodule

