module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [23:0] a_mantissa_full, b_mantissa_full;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;
    reg [23:0] z_mantissa_tmp;
    reg [8:0] z_exponent_tmp;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= a[22:0];
                    b_mantissa <= b[22:0];
                    counter <= counter + 1;
                end
                3'b001: begin

                    if (a_exponent == 8'hff || b_exponent == 8'hff) begin

                        if (a_exponent == 8'hff && a_mantissa != 0 ||
                            b_exponent == 8'hff && b_mantissa != 0) begin

                            z <= {a_sign ^ b_sign, 8'hff, 23'h1};
                        end else if (a_exponent == 8'hff && b_exponent == 8'hff) begin

                            z <= {a_sign ^ b_sign, 8'hff, 23'h0};
                        end else begin

                            z <= {1'b0, 8'hff, 23'h1};
                        end
                        counter <= 3'b000;
                    end else if (a_exponent == 0 || b_exponent == 0) begin

                        z <= {a_sign ^ b_sign, 31'b0};
                        counter <= 3'b000;
                    end else begin

                        z_sign <= a_sign ^ b_sign;
                        a_mantissa_full <= {1'b1, a_mantissa};
                        b_mantissa_full <= {1'b1, b_mantissa};
                        z_exponent_tmp <= a_exponent + b_exponent - 9'd127;
                        counter <= counter + 1;
                    end
                end
                3'b010: begin

                    product <= a_mantissa_full * b_mantissa_full;
                    counter <= counter + 1;
                end
                3'b011: begin

                    if (product[47]) begin
                        z_mantissa_tmp <= {product[46:23], 1'b0};
                        z_exponent_tmp <= z_exponent_tmp + 1;
                    end else begin
                        z_mantissa_tmp <= {1'b0, product[47:23]};
                    end
                    counter <= counter + 1;
                end
                3'b100: begin

                    guard_bit <= product[22];
                    round_bit <= product[21];
                    sticky <= |product[20:0];
                    counter <= counter + 1;
                end
                3'b101: begin

                    if (guard_bit && (round_bit || sticky || z_mantissa_tmp[23])) begin
                        z_mantissa_tmp <= z_mantissa_tmp + 1;
                        if (z_mantissa_tmp[23:23] == 1'b1 && z_mantissa_tmp[22:0] == 23'h1fffff) begin
                            z_exponent_tmp <= z_exponent_tmp + 1;
                        end
                    end
                    counter <= counter + 1;
                end
                3'b110: begin

                    if (z_exponent_tmp >= 9'd255) begin
                        z <= {z_sign, 8'hff, 23'h0};
                    end else if (z_exponent_tmp <= 9'd0) begin
                        z <= {z_sign, 31'b0};
                    end else begin
                        z <= {z_sign, z_exponent_tmp[7:0], z_mantissa_tmp[22:0]};
                    end
                    counter <= 3'b000;
                end
                default: counter <= 3'b000;
            endcase
        end
    end

endmodule

