module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output [15:0] result
);

    reg [7:0] dividend_reg, divisor_reg;
    reg [7:0] abs_dividend, abs_divisor;
    reg [7:0] quotient, remainder;
    reg [3:0] cnt;
    reg start_cnt;
    reg [16:0] SR;

    reg sign_quotient, sign_remainder;
    wire [8:0] sub_result;

    assign sub_result = {1'b0, SR[16:9]} - {1'b0, abs_divisor};


    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            start_cnt <= 0;
            cnt <= 0;
            dividend_reg <= 0;
            divisor_reg <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
            SR <= 0;
            quotient <= 0;
            remainder <= 0;
            sign_quotient <= 0;
            sign_remainder <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                res_valid <= 0;
                sign_quotient <= (sign && (dividend[7] ^ divisor[7]));
                sign_remainder <= sign && dividend[7];

                abs_dividend <= sign ? (dividend[7] ? (~dividend + 1) : dividend) : dividend;
                abs_divisor <= sign ? (divisor[7] ? (~divisor + 1) : divisor) : divisor;

                SR <= {abs_dividend, 1'b0};
                cnt <= 1;
                start_cnt <= 1;
                quotient <= 0;
            end else if (start_cnt) begin
                if (cnt == 8) begin

                    start_cnt <= 0;
                    res_valid <= 1;

                    quotient <= sign_quotient ? (~quotient + 1) : quotient;
                    remainder <= sign_remainder ? SR[16:9] : SR[16:9];
                end else begin
                    cnt <= cnt + 1;
                    if (sub_result[8] == 1'b0) begin 
                        SR <= {sub_result[7:0], 1'b1, quotient[7:1]};
                    end else begin
                        SR <= {SR[16:9], 1'b0, quotient[7:1]};
                    end
                    quotient <= {quotient[6:0], sub_result[8] ? 1'b0 : 1'b1};
                end
            end
        end
    end

    assign result = {remainder, quotient};

endmodule

