module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output [15:0] result,
    output [15:0] odd
);

    reg [15:0] a_reg, b_reg;
    reg [15:0] quotient = 0;
    reg [15:0] remainder = 0;

    always @(*) begin
        a_reg = A;
        b_reg = B;
        quotient = 16'b0;
        remainder = 16'b0;

        for (integer i = 15;
 i >= 0;
 i = i - 1) begin
            reg [7:0] current_dividend = {remainder[7:0], a_reg[15:8]};
            if (current_dividend >= b_reg) begin
                quotient[i] = 1'b1;
                remainder[7:0] = current_dividend - b_reg;
                a_reg = {a_reg[7:0], 8'b0};
            end else begin
                quotient[i] = 1'b0;
                remainder[7:0] = current_dividend;
                a_reg = a_reg << 1;
            end
        end
    end

    assign result = quotient;
    assign odd = {remainder[7:0], a_reg[15:8]};

endmodule

