module fixed_point_adder #(parameter Q=3, parameter N=8) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

reg [N-1:0] res;

always @(*) begin
    reg sign_a, sign_b;
    reg [N-2:0] mag_a, mag_b;
    reg mag_a_gt_mag_b, mag_b_gt_mag_a, mag_eq;
    reg [N-2:0] sum_mag;
    reg overflow;
    reg result_sign;
    reg [N-2:0] result_mag;

    sign_a = a[N-1];
    mag_a = a[N-2:0];
    sign_b = b[N-1];
    mag_b = b[N-2:0];

    mag_a_gt_mag_b = (mag_a > mag_b);
    mag_b_gt_mag_a = (mag_b > mag_a);
    mag_eq = (mag_a == mag_b);

    sum_mag = mag_a + mag_b;
    overflow = sum_mag > (2**(N-1) - 1);

    if (sign_a == sign_b) begin
        if (overflow) begin
            result_mag = 2**(N-1) - 1;
            result_sign = 1'b1;
        end else begin
            result_mag = sum_mag;
            result_sign = sign_a;
        end
    end else begin
        if (mag_a_gt_mag_b) begin
            result_mag = mag_a - mag_b;
            result_sign = 1'b0;
        end else if (mag_b_gt_mag_a) begin
            result_mag = mag_b - mag_a;
            result_sign = 1'b1;
        end else begin
            result_mag = 0;
            result_sign = 1'b0;
        end
    end

    res = {result_sign, result_mag};
end

assign c = res;

endmodule

