module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;

    wire a_is_nan = (a_exponent == 8'hFF) && (a_mantissa != 0);
    wire b_is_nan = (b_exponent == 8'hFF) && (b_mantissa != 0);
    wire a_is_inf = (a_exponent == 8'hFF) && (a_mantissa == 0);
    wire b_is_inf = (b_exponent == 8'hFF) && (b_mantissa == 0);
    wire a_is_zero = (a_exponent == 0) && (a_mantissa == 0);
    wire b_is_zero = (b_exponent == 0) && (b_mantissa == 0);

    reg [47:0] normalized_product;
    reg [7:0] final_exponent;
    reg [22:0] rounded_mantissa;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a_exponent == 0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b_exponent == 0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                    counter <= counter + 1;
                end
                3'b001: begin

                    product <= {1'b0, a_mantissa} * {1'b0, b_mantissa};
                    counter <= counter + 1;
                end
                3'b010: begin

                    if (product >= 48'h800000000000) begin
                        normalized_product <= product >> 1;
                        final_exponent <= a_exponent + b_exponent - 8'd127 + 8'd1;
                    end else begin
                        normalized_product <= product;
                        final_exponent <= a_exponent + b_exponent - 8'd127;
                    end
                    counter <= counter + 1;
                end
                3'b011: begin

                    guard_bit <= normalized_product[23];
                    round_bit <= normalized_product[22];
                    sticky <= |normalized_product[21:0];

                    if (guard_bit && round_bit) begin
                        if (sticky) rounded_mantissa <= normalized_product[23:1] + 1;
                        else rounded_mantissa <= normalized_product[23:1] + (normalized_product[0] ? 1 : 0);
                    end else if (guard_bit) begin
                        rounded_mantissa <= normalized_product[23:1] + 1;
                    end else begin
                        rounded_mantissa <= normalized_product[23:1];
                    end

                    if (rounded_mantissa[23]) begin
                        rounded_mantissa <= 23'b0;
                        final_exponent <= final_exponent + 8'd1;
                    end
                    counter <= counter + 1;
                end
                3'b100: begin

                    if (a_is_nan || b_is_nan) z <= {1'b0, 8'hFF, 23'h1};

                    else if (a_is_inf && b_is_zero) z <= {1'b0, 8'hFF, 23'h1};

                    else if (b_is_inf && a_is_zero) z <= {1'b0, 8'hFF, 23'h1};

                    else if (a_is_inf || b_is_inf) z <= {1'b0, 8'hFF, 23'h0};

                    else if (a_is_zero || b_is_zero) z <= {1'b0, 8'h00, 23'h0};

                    else begin
                        if (final_exponent >= 8'hFF) z <= {z_sign, 8'hFF, 23'h0};

                        else if (final_exponent == 0 || rounded_mantissa == 0) z <= {z_sign, 8'h00, 23'h0};

                        else z <= {z_sign, final_exponent, rounded_mantissa};
                    end
                    counter <= 3'b000;
                end
                default: counter <= 3'b000;
            endcase
        end
    end

    always @(*) begin
        z_sign = a_sign ^ b_sign;
    end

