    if (RST) begin
        current_state <= S0;
    end else begin
        current_state <= next_state;
    end
end


always @(*) begin
    case (current_state)
        S0: next_state = IN ? S1 : S0;
        S1: next_state = IN ? S1 : S2;
        S2: next_state = IN ? S1 : S3;
        S3: next_state = IN ? S4 : S0;
        S4: next_state = IN ? S5 : S0;
        S5: next_state = IN ? S1 : S0;
        default: next_state = S0;
    endcase
end


always @(*) begin
    MATCH = 1'b0;
    if (current_state == S4 && IN) begin
        MATCH = 1'b1;
    end
end

endmodule

