module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

reg [1:0] current_state;
localparam IDLE = 2'b00;
localparam S1   = 2'b01;
localparam S2   = 2'b10;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        current_state <= IDLE;
        data_out <= 1'b0;
    end else begin
        case (current_state)
            IDLE: begin
                if (data_in) begin
                    current_state <= S1;
                end else begin
                    current_state <= IDLE;
                end
                data_out <= 1'b0;
            end
            S1: begin
                if (data_in) begin
                    current_state <= S1;
                end else begin
                    current_state <= S2;
                end
                data_out <= 1'b0;
            end
            S2: begin
                current_state <= IDLE;
                data_out <= 1'b1;
            end
            default: begin
                current_state <= IDLE;
                data_out <= 1'b0;
            end
        endcase
    end
end

endmodule

