module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output red,
    output yellow,
    output green
);

    parameter idle = 2'd0,
              s1_red = 2'd1,
              s3_green = 2'd2,
              s2_yellow = 2'd3;

    reg [1:0] state;
    reg [7:0] cnt;
    reg p_red, p_yellow, p_green;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            cnt <= 8'd10;
        end else begin
            case (state)
                idle: state <= s1_red;
                s1_red: state <= (cnt == 0) ? s3_green : s1_red;
                s3_green: state <= (cnt == 0) ? s2_yellow : s3_green;
                s2_yellow: state <= (cnt == 0) ? s1_red : s2_yellow;
                default: state <= idle;
            endcase

            if (pass_request && (state == s3_green) && (cnt > 10))
                cnt <= 8'd10;
            else if (state != idle)
                cnt <= cnt - 1;
            else
                cnt <= 8'd10;

            p_red <= red;
            p_yellow <= yellow;
            p_green <= green;
        end
    end

    assign red = (state == s1_red);
    assign green = (state == s3_green);
    assign yellow = (state == s2_yellow);
    assign clock = cnt;

endmodule

