module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);

    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;

    reg [32:0] res;

    always @(*) begin
        case (aluc)
            ADD:  res = {1'b0, a} + {1'b0, b};
            ADDU: res = {1'b0, a} + {1'b0, b};
            SUB:  res = {1'b0, a} - {1'b0, b};
            SUBU: res = {1'b0, a} - {1'b0, b};
            AND:  res = {32'b0, a & b};
            OR:   res = {32'b0, a | b};
            XOR:  res = {32'b0, a ^ b};
            NOR:  res = {32'b0, ~(a | b)};
            SLT:  res = ($signed(a) < $signed(b)) ? 33'b1 : 33'b0;
            SLTU: res = (a < b) ? 33'b1 : 33'b0;
            SLL:  res = {32'b0, a} << b[4:0];
            SRL:  res = {32'b0, a} >> b[4:0];
            SRA:  res = $signed({32'b0, a}) >>> b[4:0];
            SLLV: res = {32'b0, b} << a[4:0];
            SRLV: res = {32'b0, b} >> a[4:0];
            SRAV: res = $signed({32'b0, b}) >>> a[4:0];
            LUI:  res = {a[31:16], 16'b0};
            default: res = 33'bz;
        endcase
    end

    assign r = res[31:0];
    assign zero = (r == 32'b0);
    assign negative = res[31];
    assign carry = (aluc == ADD || aluc == ADDU || aluc == SUB || aluc == SUBU) ? res[32] : 1'b0;
    assign overflow = (aluc == ADD) ? (a[31] == b[31] && res[31] != a[31]) :
                     (aluc == SUB) ? (a[31] != b[31] && res[31] != a[31]) : 1'b0;
    assign flag = (aluc == SLT || aluc == SLTU) ? ((aluc == SLT) ? ($signed(a) < $signed(b)) : (a < b)) : 1'bz;

endmodule

