module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [15:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] dividend_abs;
    reg [7:0] divisor_abs;
    reg sign_quotient;
    reg remainder_sign;
    reg [8:0] NEG_DIVISOR;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            SR <= 0;
            cnt <= 0;
            start_cnt <= 0;
            dividend_abs <= 0;
            divisor_abs <= 0;
            sign_quotient <= 0;
            remainder_sign <= 0;
            NEG_DIVISOR <= 0;
            result <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                if (sign) begin
                    dividend_abs <= dividend[7] ? -dividend : dividend;
                    divisor_abs <= divisor[7] ? -divisor : divisor;
                    sign_quotient <= dividend[7] ^ divisor[7];
                    remainder_sign <= dividend[7];
                end else begin
                    dividend_abs <= dividend;
                    divisor_abs <= divisor;
                    sign_quotient <= 0;
                    remainder_sign <= 0;
                end

                NEG_DIVISOR <= -{1'b0, divisor_abs};

                SR <= {dividend_abs, 8'b0} << 1;
                cnt <= 4'd1;
                start_cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt) begin
                if (cnt < 4'd8) begin

                    if ($signed(SR[15:7]) >= $signed(NEG_DIVISOR)) begin
                        SR <= (SR - {7'b0, NEG_DIVISOR}) << 1;
                    end else begin
                        SR <= SR << 1;
                    end
                    cnt <= cnt + 1;
                end else begin

                    start_cnt <= 0;

                    if (sign) begin
                        if (remainder_sign)
                            result[15:8] <= -SR[15:8];
                        else
                            result[15:8] <= SR[15:8];
                        if (sign_quotient)
                            result[7:0] <= -SR[7:0];
                        else
                            result[7:0] <= SR[7:0];
                    end else begin
                        result <= SR;
                    end
                    res_valid <= 1;
                end
            end

            if (res_valid && !opn_valid)
                res_valid <= 0;
        end
    end
endmodule

