module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [15:0] a_reg;
reg [7:0] b_reg;

always @(*) begin
    a_reg = A;
    b_reg = B;
end

always @(*) begin
    reg [15:0] q;
    reg [15:0] r;
    integer i;

    q = 16'b0;
    r = 16'b0;
    r[15:8] = a_reg[15:8];


    for (i = 7;
 i >= 0;
 i = i - 1) begin
        r = r << 1;
        r[0] = a_reg[i];
        if (r >= b_reg) begin
            q[i + 8] = 1'b1;

            r = r - b_reg;
        end else begin
            q[i + 8] = 1'b0;
        end
    end

    result = q;
    odd = r;
end

endmodule

