module multi_8bit (
    input [7:0] A,
    input [7:0] B,
    output [15:0] product
);

reg [15:0] product_reg;
integer i;

always @(*) begin
    product_reg = 16'b0;
    for (i = 0;
 i < 8;
 i = i + 1) begin
        if (B[i]) begin
            product_reg = product_reg + ( ({8'b0, A}) << i );
        end
    end
end

assign product = product_reg;

