module multi_pipe_4bit (
    input clk,
    input rst_n,
    input [3:0] mul_a,
    input [3:0] mul_b,
    output reg [7:0] mul_out
);

parameter size = 4;

wire [7:0] a_ext = {{4{1'b0}}, mul_a};
wire [7:0] b_ext = {{4{1'b0}}, mul_b};

wire [7:0] pp0 = b_ext[0] ? a_ext : 8'd0;
wire [7:0] pp1 = b_ext[1] ? (a_ext << 1) : 8'd0;
wire [7:0] pp2 = b_ext[2] ? (a_ext << 2) : 8'd0;
wire [7:0] pp3 = b_ext[3] ? (a_ext << 3) : 8'd0;

reg [7:0] s1_reg, s2_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        s1_reg <= 8'd0;
        s2_reg <= 8'd0;
    end else begin
        s1_reg <= pp0 + pp1;
        s2_reg <= pp2 + pp3;
    end
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        mul_out <= 8'd0;
    end else begin
        mul_out <= s1_reg + s2_reg;
    end
end

endmodule

