    input C_in,
    output [3:1] S,
    output P,
    output G
);
    wire p0, p1, p2, p3;
    wire g0, g1, g2, g3;
    wire c1, c2, c3;

    assign p0 = A[1] ^ B[1];
    assign g0 = A[1] & B[1];
    assign p1 = A[2] ^ B[2];
    assign g1 = A[2] & B[2];
    assign p2 = A[3] ^ B[3];
    assign g2 = A[3] & B[3];
    assign p3 = A[4] ^ B[4];
    assign g3 = A[4] & B[4];

