    assign c1 = g0 | (p0 & C_in);
    assign S[2] = p1 ^ c1;
    assign c2 = g1 | (p1 & c1);
    assign S[3] = p2 ^ c2;
    assign c3 = g2 | (p2 & c2);
    assign S[4] = p3 ^ c3;

    assign P = p0 & p1 & p2 & p3;
    assign G = g3 | (p3 & g2) | (p3 & p2 & g1) | (p3 & p2 & p1 & g0) | (p3 & p2 & p1 & p0 & C_in);
