module fixed_point_adder #(
    parameter Q = 8,
    parameter N = 16
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;

    always @(*) begin
        reg a_sign, b_sign;
        reg [N-1:0] a_abs, b_abs;
        reg [N-2:0] res_mag;
        reg res_sign;

        a_sign = a[N-1];
        b_sign = b[N-1];

        if (a_sign == b_sign) begin
            res = a + b;
        end else begin
            a_abs = a_sign ? (~a + 1) : a;
            b_abs = b_sign ? (~b + 1) : b;

            if (a_abs > b_abs) begin
                res_mag = a_abs[N-2:0] - b_abs[N-2:0];
                res_sign = a_sign;
            end else if (b_abs > a_abs) begin
                res_mag = b_abs[N-2:0] - a_abs[N-2:0];
                res_sign = b_sign;
            end else begin
                res_mag = 0;
                res_sign = 0;
            end
            res = {res_sign, res_mag};
        end
    end

    assign c = res;

endmodule

