module fixed_point_subtractor #(
    parameter Q = 3,
    parameter N = 5
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] res;
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];
    wire [N-1:0] a_abs = a_sign ? (~a + 1) : a;
    wire [N-1:0] b_abs = b_sign ? (~b + 1) : b;

    always @(*) begin
        if (a_sign == b_sign) begin

            res = a - b;
            res[N-1] = a_sign;
        end else begin

            if (a_sign == 1'b0) begin

                if (a_abs > b_abs) begin
                    res = a_abs - b_abs;
                    res[N-1] = 1'b0;
                end else begin
                    res = b_abs - a_abs;
                    res[N-1] = 1'b1;
                end
            end else begin

                if (a_abs > b_abs) begin
                    res = a_abs - b_abs;
                    res[N-1] = 1'b1;
                end else begin
                    res = b_abs - a_abs;
                    res[N-1] = 1'b0;
                end
            end
        end


        if (res == 0)
            res[N-1] = 1'b0;

        c = res;
    end

endmodule

