module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output reg [7:0] clock,
    output red,
    output yellow,
    output green
);

localparam idle = 2'd0;
localparam s1_red = 2'd1;
localparam s2_yellow = 2'd2;
localparam s3_green = 2'd3;

reg [1:0] state;
reg [7:0] cnt;
reg p_red, p_yellow, p_green;
reg next_red, next_yellow, next_green;


always @(*) begin
    case (state)
        idle: begin
            next_red = 0;
            next_yellow = 0;
            next_green = 0;
        end
        s1_red: begin
            next_red = 1;
            next_yellow = 0;
            next_green = 0;
        end
        s2_yellow: begin
            next_red = 0;
            next_yellow = 1;
            next_green = 0;
        end
        s3_green: begin
            next_red = 0;
            next_yellow = 0;
            next_green = 1;
        end
        default: begin
            next_red = 0;
            next_yellow = 0;
            next_green = 0;
        end
    endcase
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
    end else begin
        case (state)
            idle: state <= s1_red;
            s1_red: state <= (cnt == 0) ? s2_yellow : s1_red;
            s2_yellow: state <= (cnt == 0) ? s3_green : s2_yellow;
            s3_green: state <= (cnt == 0) ? s1_red : s3_green;
            default: state <= idle;
        endcase
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 10;
    end else begin
        if (pass_request && green) begin
            cnt <= (cnt > 10) ? 10 : cnt;
        end else if (!green && p_green) begin
            cnt <= 60;
        end else if (!yellow && p_yellow) begin
            cnt <= 5;
        end else if (!red && p_red) begin
            cnt <= 10;
        end else begin
            cnt <= cnt - 1;
        end
    end
end


always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        p_red <= 0;
        p_yellow <= 0;
        p_green <= 0;
    end else begin
        p_red <= next_red;
        p_yellow <= next_yellow;
        p_green <= next_green;
    end
end

assign red = p_red;
assign yellow = p_yellow;
assign green = p_green;
assign clock = cnt;

endmodule

