module serial2parallel (
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0] dout_parallel,
    output reg dout_valid
);

reg [7:0] shift_reg;
reg [3:0] cnt;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        shift_reg <= 8'b0;
        cnt <= 4'b0;
        dout_parallel <= 8'b0;
        dout_valid <= 1'b0;
    end else begin
        dout_valid <= 1'b0;


        if (din_valid) begin

            case (cnt)
                4'd0: shift_reg[7] <= din_serial;
                4'd1: shift_reg[6] <= din_serial;
                4'd2: shift_reg[5] <= din_serial;
                4'd3: shift_reg[4] <= din_serial;
                4'd4: shift_reg[3] <= din_serial;
                4'd5: shift_reg[2] <= din_serial;
                4'd6: shift_reg[1] <= din_serial;
                4'd7: shift_reg[0] <= din_serial;
                default: ;

            endcase
            cnt <= cnt + 1;
        end


        if (cnt == 4'd8) begin
            dout_parallel <= shift_reg;
            dout_valid <= 1'b1;
            cnt <= 4'd0;

        end
    end
end

