module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [7:0] dividend_reg, divisor_reg;
reg sign_reg;
reg [15:0] SR;
reg [3:0] cnt;
reg start_cnt;
reg [7:0] remainder_reg, quotient_reg;
reg quotient_sign_reg, remainder_sign_reg;
reg [7:0] NEG_DIVISOR;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 0;
        SR <= 16'b0;
        cnt <= 0;
        start_cnt <= 0;
        result <= 16'b0;
        dividend_reg <= 0;
        divisor_reg <= 0;
        sign_reg <= 0;
        quotient_sign_reg <= 0;
        remainder_sign_reg <= 0;
        remainder_reg <= 0;
        quotient_reg <= 0;
        NEG_DIVISOR <= 0;
    end else begin
        if (opn_valid && !res_valid) begin
            dividend_reg <= dividend;
            divisor_reg <= divisor;
            sign_reg <= sign;


            if (sign) begin
                dividend_reg <= dividend[7] ? (-dividend) : dividend;
                divisor_reg <= divisor[7] ? (-divisor) : divisor;
                quotient_sign_reg <= dividend[7] ^ divisor[7];
                remainder_sign_reg <= dividend[7];
            end else begin
                dividend_reg <= dividend;
                divisor_reg <= divisor;
                quotient_sign_reg <= 0;
                remainder_sign_reg <= 0;
            end


            SR <= {dividend_reg, 8'b0} << 1;
            NEG_DIVISOR <= -divisor_reg;

            cnt <= 1;
            start_cnt <= 1;
            res_valid <= 0;
        end else if (start_cnt) begin
            if (cnt < 8) begin
                reg [8:0] temp_remainder;
                reg [7:0] new_remainder;
                reg new_quotient_bit;


                temp_remainder = {1'b0, SR[15:8]} - NEG_DIVISOR;
                new_remainder = temp_remainder[7:0];
                new_quotient_bit = ~temp_remainder[8];



                SR <= {new_remainder, SR[7:1], new_quotient_bit};
                cnt <= cnt + 1;
            end else begin

                remainder_reg <= remainder_sign_reg ? (-SR[15:8]) : SR[15:8];
                quotient_reg <= quotient_sign_reg ? (-SR[7:0]) : SR[7:0];
                result <= {remainder_reg, quotient_reg};
                res_valid <= 1;
                start_cnt <= 0;
                cnt <= 0;
            end
        end
    end
end

endmodule

