module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg [9:0] data_out,
    output reg valid_out
);

    reg [1:0] counter;
    reg [7:0] buffer [0:3];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 2'b0;
            buffer[0] <= 8'b0;
            buffer[1] <= 8'b0;
            buffer[2] <= 8'b0;
            buffer[3] <= 8'b0;
            data_out <= 10'b0;
            valid_out <= 1'b0;
        end else begin
            valid_out <= 1'b0;
            if (valid_in) begin

                buffer[0] <= buffer[1];
                buffer[1] <= buffer[2];
                buffer[2] <= buffer[3];
                buffer[3] <= data_in;
                counter <= counter + 1;

                if (counter == 2'b11) begin
                    data_out <= buffer[0] + buffer[1] + buffer[2] + data_in;
                    valid_out <= 1'b1;
                end
            end
        end
    end

endmodule

