module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

    reg [N-1:0] res;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire [N-2:0] mag_a = a[N-2:0];
    wire [N-2:0] mag_b = b[N-2:0];

    wire [N-1:0] sum_mag = {1'b0, mag_a} + {1'b0, mag_b};
    wire sum_overflow = sum_mag[N];
    wire [N-2:0] max_mag = (2**(N-1) - 1);

    wire [N-2:0] mag_diff = (mag_a > mag_b) ? (mag_a - mag_b) :
                             (mag_b > mag_a) ? (mag_b - mag_a) : {N-1{1'b0}};
    wire res_sign_sub = (mag_a > mag_b) ? 1'b0 :
                        (mag_b > mag_a) ? 1'b1 : 1'b0;

    always @* begin
        if (sign_a == sign_b) begin
            res = sum_overflow ? {1'b1, max_mag} : {sign_a, sum_mag[N-2:0]};
        end else begin
            res = {res_sign_sub, mag_diff};
        end
    end

    assign c = res;

endmodule

