module fixed_point_subtractor #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

reg [N-1:0] res;

always @* begin
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire same_sign = (sign_a == sign_b);

    if (same_sign) begin
        res = a - b;
    end else begin
        if (sign_a && !sign_b) begin 
            wire [N-1:0] abs_a = -a;
            wire [N-1:0] sum = abs_a + b;
            res = (-a > b) ? sum : -sum;
        end else begin 
            wire [N-1:0] abs_b = -b;
            wire [N-1:0] sum = a + abs_b;
            res = (a > abs_b) ? sum : -sum;
        end
    end


    if (res == 0) begin
        res[N-1] = 1'b0;
    end
end

assign c = res;

endmodule

