module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z = 0
);

    reg [2:0] counter = 0;
    reg [7:0] a_exp, b_exp, sum_exp;
    reg a_sign, b_sign, z_sign;
    reg [23:0] a_man, b_man;
    reg [48:0] product;

    reg guard, round, sticky;
    reg [22:0] mantissa;
    reg [7:0] final_exp;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 0;
        end else begin
            case (counter)
                0: begin 
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exp <= a[30:23];
                    b_exp <= b[30:23];
                    a_man <= {1'b1, a[22:0]};
                    b_man <= {1'b1, b[22:0]};
                    counter <= counter + 1;
                end

                1: begin 
                    if (a_exp == 8'hFF || b_exp == 8'hFF) begin
                        if (a_exp == 8'hFF && a_man != 0) || (b_exp == 8'hFF && b_man != 0) begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h0};

                        end else if ((a_exp == 8'hFF && a_man == 0) && (b_exp == 8'hFF && b_man == 0)) begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h1};

                        end else if (a_exp == 8'hFF && a_man == 0) begin
                            if (b_exp == 8'h00 && b_man == 0) z <= {a_sign ^ b_sign, 8'hFF, 23'h1};

                            else z <= {a_sign ^ b_sign, 8'hFF, 23'h1};

                        end else if (b_exp == 8'hFF && b_man == 0) begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h1};

                        end else begin
                            counter <= counter + 1;
                        end
                    end else if (a_exp == 8'h00 || b_exp == 8'h00) begin
                        if ((a_exp == 8'h00 && a_man == 0) || (b_exp == 8'h00 && b_man == 0)) begin
                            z <= {a_sign ^ b_sign, 8'h00, 23'h0};

                        end else begin
                            counter <= counter + 1;
                        end
                    end else begin
                        sum_exp <= a_exp + b_exp - 8'd127;
                        product <= a_man * b_man;

                        counter <= counter + 1;
                    end
                end

                2: begin 
                    product <= a_man * b_man;
                    counter <= counter + 1;
                end

                3: begin 
                    if (product[49]) begin 
                        mantissa <= product[48:26];

                        final_exp <= sum_exp + 8'd1;
                        sticky <= |product[25:0];
                    end else begin
                        mantissa <= product[47:25];

                        final_exp <= sum_exp;
                        sticky <= |product[24:0];
                    end
                    counter <= counter + 1;
                end

                4: begin 
                    {guard, round, sticky} = {product[24], product[23], sticky};

                    if (guard) begin
                        if (round || sticky || mantissa[0]) begin
                            mantissa <= mantissa + 1;
