                    end
                    counter <= counter + 1;
                end

                5: begin 
                    if (mantissa[23]) begin 
                        mantissa <= 23'h0;
                        final_exp <= final_exp + 8'd1;
                    end

                    if (final_exp > 8'hFE) begin 
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h0};

                    end else if (final_exp < 8'h01) begin 
                        z <= {a_sign ^ b_sign, 8'h00, 23'h0};

                    end else begin
                        z <= {a_sign ^ b_sign, final_exp, mantissa};
                    end
                    counter <= 3'b0;

                end
            endcase
