module sub_64bit (
    input [63:0] A,
    input [63:0] B,
    output reg [63:0] result,
    output reg overflow
);

    wire signed [63:0] signed_A = A;
    wire signed [63:0] signed_B = B;
    wire signed [63:0] signed_result = signed_A - signed_B;

    always @* begin
        result = A - B;
        overflow = ((signed_A >= 0) && (signed_B < 0) && (signed_result < 0)) || 
                   ((signed_A < 0) && (signed_B >= 0) && (signed_result >= 0));
    end

endmodule

