    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S0;
            data_out <= 1'b0;
        end else begin
            case (state)
                S0: begin
                    if (data_in == 1'b0) begin
                        state <= S1;
                    end else begin
                        state <= S0;
                    end
                    data_out <= 1'b0;
                end
                S1: begin
                    if (data_in == 1'b1) begin
                        state <= S2;
                    end else begin
                        state <= S0;
                    end
                    data_out <= 1'b0;
                end
                S2: begin
                    if (data_in == 1'b0) begin
                        state <= S0;
                        data_out <= 1'b1;
                    end else begin
                        state <= S0;
                        data_out <= 1'b0;
                    end
                end
                default: begin
                    state <= S0;
                    data_out <= 1'b0;
                end
            endcase
        end
    end

