    reg [3:0] cnt_reg;
    reg start_cnt_reg;
    reg [7:0] quotient_reg;
    reg [7:0] remainder_reg;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 1'b0;
            sr_reg <= 16'b0;
            cnt_reg <= 4'b0;
            start_cnt_reg <= 1'b0;
            dividend_sign_reg <= 1'b0;
            divisor_sign_reg <= 1'b0;
            dividend_abs_reg <= 8'b0;
            divisor_abs_reg <= 8'b0;
            neg_divisor_reg <= 8'b0;
            quotient_reg <= 8'b0;
            remainder_reg <= 8'b0;
        end else begin
            if (opn_valid && !res_valid) begin

                dividend_sign_reg <= sign ? dividend[7] : 1'b0;
                divisor_sign_reg <= sign ? divisor[7] : 1'b0;
                dividend_abs_reg <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                divisor_abs_reg <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
                neg_divisor_reg <= ~divisor_abs_reg + 1;
                sr_reg <= {dividend_abs_reg, 8'b0};

                cnt_reg <= 4'd1;
                start_cnt_reg <= 1'b1;
                res_valid <= 1'b0;
