                        remainder_reg <= dividend_sign_reg ? -sr_reg[15:8] : sr_reg[15:8];
                        quotient_reg <= (dividend_sign_reg ^ divisor_sign_reg) ? -sr_reg[7:0] : sr_reg[7:0];
                    end else begin
                        remainder_reg <= sr_reg[15:8];
                        quotient_reg <= sr_reg[7:0];
                    end
                    res_valid <= 1'b1;
                    result <= {remainder_reg, quotient_reg};
                    start_cnt_reg <= 1'b0;
                end else begin

                    reg [8:0] sub_result;
                    sub_result = {1'b0, sr_reg[15:9]} - {1'b0, divisor_abs_reg};
                    if (!sub_result[8]) begin 
                        sr_reg <= {sub_result[7:0], sr_reg[7:1], 1'b1};
                    end else begin 
                        sr_reg <= {sr_reg[15:9], sr_reg[7:1], 1'b0};
                    end
                    cnt_reg <= cnt_reg + 1;
                end
            end
        end
    end

