module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [15:0] a_reg;
reg [7:0] b_reg;


always @(*) begin
    a_reg = A;
    b_reg = B;
end


always @(*) begin
    result = 16'b0;
    odd = 16'b0;

    reg [15:0] dividend = a_reg;
    reg [15:0] remainder = 16'b0;
    reg [7:0] divisor = b_reg;

    for (integer i = 15;
 i >= 0;
 i--) begin

        remainder = {remainder[14:0], dividend[15]};
        dividend = {dividend[14:0], 1'b0};


        if (remainder >= {8'b0, divisor}) begin
            result[i] = 1'b1;
            remainder = remainder - {8'b0, divisor};
        end else begin
            result[i] = 1'b0;
        end
    end

    odd = remainder;
end

endmodule

