module comparator_4bit (
    input [3:0] A,
    input [3:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

    wire [4:0] sum;
    assign sum = {1'b0, A} + {1'b0, ~B} + 5'b1;

    wire borrow = ~sum[4];
    wire [3:0] sub = sum[3:0];

    assign A_less = borrow;
    assign A_equal = (sub == 4'b0);
    assign A_greater = (~borrow) && (sub != 4'b0);

endmodule

