module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output valid_out,
    output [9:0] data_out
);

reg [9:0] sum_reg;
reg [1:0] counter;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum_reg <= 10'd0;
        counter <= 2'd0;
    end else begin
        if (valid_in) begin
            sum_reg <= sum_reg + data_in;
        end
        if (valid_in) begin
            if (counter == 2'd3) begin
                counter <= 2'd0;
            end else begin
                counter <= counter + 1;
            end
        end
    end
end

assign valid_out = (counter == 2'd3) && valid_in;
assign data_out = valid_out ? (sum_reg + data_in) : 10'd0;

endmodule

