    input wire [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] res;
    wire sign_a = a[N-1];
    wire sign_b = b[N-1];
    wire [N-1:0] abs_a = sign_a ? (~a + 1) : a;
    wire [N-1:0] abs_b = sign_b ? (~b + 1) : b;
    wire [N:0] sum_abs = abs_a + abs_b;

    always @(*) begin
        if (sign_a == sign_b) begin
            res = {sum_abs[N], sum_abs[N-1:1]};

        end else begin
            if (abs_a > abs_b) begin
                res = {1'b0, (abs_a - abs_b)[N-2:0]};

            end else if (abs_b > abs_a) begin
                res = {1'b1, (abs_b - abs_a)[N-2:0]};

            end else begin
                res = {(N){1'b0}};

            end
        end
    end

    always @(*) begin
        c = res;
    end

endmodule

