    reg [9:0] z_exponent;
    reg [23:0] z_mantissa;

    wire a_is_nan = (a[30:23] == 8'hFF) && (a[22:0] != 23'b0);
    wire b_is_nan = (b[30:23] == 8'hFF) && (b[22:0] != 23'b0);
    wire a_is_inf = (a[30:23] == 8'hFF) && (a[22:0] == 23'b0);
    wire b_is_inf = (b[30:23] == 8'hFF) && (b[22:0] == 23'b0);
    wire a_is_zero = (a[30:23] == 8'h00) && (a[22:0] == 23'b0);
    wire b_is_zero = (b[30:23] == 8'h00) && (b[22:0] == 23'b0);

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            case (counter)
                3'b000: begin

                    a_reg <= a;
                    b_reg <= b;
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= {1'b1, a[22:0]};
                    b_mantissa <= {1'b1, b[22:0]};
                    z_sign <= a_sign ^ b_sign;


                    if (a_is_nan || b_is_nan) begin
                        z <= {z_sign, 8'hFF, 23'h000001};
                    end else if (a_is_inf && b_is_zero) begin
                        z <= {z_sign, 8'hFF, 23'h000001};
                    end else if (b_is_inf && a_is_zero) begin
                        z <= {z_sign, 8'hFF, 23'h000001};
                    end else if (a_is_inf || b_is_inf) begin
                        z <= {z_sign, 8'hFF, 23'b0};
                    end else if (a_is_zero || b_is_zero) begin
                        z <= {z_sign, 31'b0};
                    end else begin
                        z <= 32'b0;
                    end

                    counter <= 3'b001;
                end
                3'b001: begin

                    product <= a_mantissa * b_mantissa;
                    counter <= 3'b010;
                end
                3'b010: begin

                    if (product[47]) begin
                        product <= product >> 1;
                        z_exponent <= a_exponent + b_exponent - 9'd127 - 9'd127 + 1;
                        guard <= product[0];
                        round <= product[1];
                        sticky <= |product[2:0];
                        z_mantissa <= {product[46:24], 1'b0};
                    end else begin
                        z_exponent <= a_exponent + b_exponent - 9'd127 - 9'd127;
                        guard <= product[47];
                        round <= product[46];
                        sticky <= |product[45:0];
                        z_mantissa <= {product[47:25], 1'b0};
                    end

                    counter <= 3'b011;
                end
                3'b011: begin

                    if (guard && (round || sticky || (z_mantissa[0]))) begin
                        z_mantissa <= z_mantissa + 1;
                    end


                    if (z_mantissa[23]) begin
                        z_exponent <= z_exponent + 1;
                        z_mantissa <= 24'h0;
                    end

                    counter <= 3'b100;
                end
                3'b100: begin

                    if (z_exponent > 9'd254) begin
                        z <= {z_sign, 8'hFF, 23'b0};
                    end else if (z_exponent < 9'd1) begin
                        z <= {z_sign, 31'b0};
                    end else begin
                        z <= {z_sign, z_exponent[7:0], z_mantissa[22:0]};
                    end

                    counter <= 3'b000;
                end
                default: counter <= 3'b000;
            endcase
        end
    end

