reg [PTR_WIDTH:0] waddr_gray, raddr_gray;

reg [PTR_WIDTH:0] raddr_gray_synced_wrclk [1:0];
reg [PTR_WIDTH:0] waddr_gray_synced_rclk [1:0];

assign waddr_gray = waddr_bin ^ (waddr_bin >> 1);
assign raddr_gray = raddr_bin ^ (raddr_bin >> 1);

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        raddr_gray_synced_wrclk[0] <= 0;
        raddr_gray_synced_wrclk[1] <= 0;
    end else begin
        raddr_gray_synced_wrclk[0] <= raddr_gray;
        raddr_gray_synced_wrclk[1] <= raddr_gray_synced_wrclk[0];
    end
end

always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        waddr_gray_synced_rclk[0] <= 0;
        waddr_gray_synced_rclk[1] <= 0;
    end else begin
        waddr_gray_synced_rclk[0] <= waddr_gray;
        waddr_gray_synced_rclk[1] <= waddr_gray_synced_rclk[0];
    end
end

assign rempty = (raddr_gray == waddr_gray_synced_rclk[1]);
assign wfull = (waddr_gray == {~raddr_gray_synced_wrclk[1][PTR_WIDTH:PTR_WIDTH-1], raddr_gray_synced_wrclk[1][PTR_WIDTH-2:0]});

always @(posedge wclk or negedge wrstn) begin
    if (!wrstn)
        waddr_bin <= 0;
    else if (winc && !wfull)
        waddr_bin <= waddr_bin + 1;
