module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

parameter idle = 2'b00,
          s1_red = 2'b01,
          s2_yellow = 2'b10,
          s3_green = 2'b11;

reg [1:0] state, next_state;
reg [7:0] cnt;
reg p_red, p_yellow, p_green;

assign clock = cnt;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= idle;
    end else begin
        state <= next_state;
    end
end

always @(*) begin
    case (state)
        idle: next_state = s1_red;
        s1_red: next_state = (cnt == 10) ? s2_yellow : s1_red;
        s2_yellow: next_state = (cnt == 5) ? s3_green : s2_yellow;
        s3_green: next_state = (cnt == 60) ? s1_red : s3_green;
        default: next_state = idle;
    endcase
end

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 8'd10;
        p_red <= 0;
        p_yellow <= 0;
        p_green <= 0;
    end else begin
        if (pass_request && p_green) begin
            if ((60 - cnt) > 10) begin
                cnt <= 60 - 10;
            end
        end else begin
            case (state)
                s1_red: begin
                    if (cnt == 10) begin
                        cnt <= 5;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s2_yellow: begin
                    if (cnt == 5) begin
                        cnt <= 60;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                s3_green: begin
                    if (cnt == 60) begin
                        cnt <= 10;
                    end else begin
                        cnt <= cnt - 1;
                    end
                end
                default: cnt <= cnt;
            endcase
        end
        p_red <= (state == s1_red);
        p_yellow <= (state == s2_yellow);
        p_green <= (state == s3_green);
    end
end

assign red = p_red;
assign yellow = p_yellow;
assign green = p_green;

endmodule

