            if (cnt == 4'd7) begin
                cnt <= 4'b0;
            end else begin
                cnt <= cnt + 1;
            end

            if (cnt == 4'd7) begin
                dout_valid <= 1'b1;
                dout_parallel <= next_shift_reg;
            end
        end
    end
end

