module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);


parameter ADD  = 6'b100000;
parameter ADDU = 6'b100001;
parameter SUB  = 6'b100010;
parameter SUBU = 6'b100011;
parameter AND  = 6'b100100;
parameter OR   = 6'b100101;
parameter XOR  = 6'b100110;
parameter NOR  = 6'b100111;
parameter SLT  = 6'b101010;
parameter SLTU = 6'b101011;
parameter SLL  = 6'b000000;
parameter SRL  = 6'b000010;
parameter SRA  = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI  = 6'b001111;

reg [32:0] add_res, sub_res;
wire [32:0] addu_sum = {1'b0, a} + {1'b0, b};
wire [32:0] subu_diff = {1'b0, a} - {1'b0, b};

always @(*) begin
    case (aluc)
        ADD: begin
            add_res = {1'b0, a} + {1'b0, b};
            r = add_res[31:0];
        end
        ADDU: begin
            r = addu_sum[31:0];
        end
        SUB: begin
            sub_res = {1'b0, a} - {1'b0, b};
            r = sub_res[31:0];
        end
        SUBU: begin
            r = subu_diff[31:0];
        end
        AND: r = a & b;
        OR:  r = a | b;
        XOR: r = a ^ b;
        NOR: r = ~(a | b);
        SLT: r = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
        SLTU: r = (a < b) ? 32'd1 : 32'd0;
        SLL: r = b << a[4:0];
        SRL: r = b >> a[4:0];
        SRA: r = $signed(b) >>> a[4:0];
        SLLV: r = b << a[4:0];
        SRLV: r = b >> a[4:0];
        SRAV: r = $signed(b) >>> a[4:0];
        LUI: r = {a[31:16], 16'b0};
        default: r = 32'bz;
    endcase
end


assign carry = (aluc == ADD) ? add_res[32] :
               (aluc == SUB) ? sub_res[32] :
               (aluc == ADDU) ? addu_sum[32] :
               (aluc == SUBU) ? subu_diff[32] :
               1'b0;

assign overflow = (aluc == ADD || aluc == SUB) ? 
                    ((a[31] == b[31]) && (r[31] != a[31])) : 
                    1'b0;

assign zero = (r == 32'd0);
assign negative = r[31];
assign flag = (aluc == SLT || aluc == SLTU) ? r[0] : 1'b0;

endmodule

