module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output [15:0] result
);

    reg [15:0] SR_reg;
    reg [3:0] cnt_reg;
    reg start_cnt_reg;
    reg [15:0] result_reg;
    reg sign_reg;
    reg dividend_sign_reg;
    reg divisor_sign_reg;


    wire [7:0] abs_dividend = sign ? (dividend[7] ? -dividend : dividend) : dividend;
    wire [7:0] abs_divisor = sign ? (divisor[7] ? -divisor : divisor) : divisor;
    wire [7:0] NEG_DIVISOR = -abs_divisor;

    wire [8:0] temp_remainder_9bit = {1'b0, SR_reg[15:8]} + {1'b0, NEG_DIVISOR};
    wire carry_out = temp_remainder_9bit[8];

    assign result = res_valid ? result_reg : 16'b0;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 1'b0;
            start_cnt_reg <= 1'b0;
            cnt_reg <= 4'd0;
            SR_reg <= 16'd0;
            sign_reg <= 1'b0;
            dividend_sign_reg <= 1'b0;
            divisor_sign_reg <= 1'b0;
            result_reg <= 16'd0;
        end else begin
            if (opn_valid && !res_valid) begin
                sign_reg <= sign;
                dividend_sign_reg <= sign ? dividend[7] : 1'b0;
                divisor_sign_reg <= sign ? divisor[7] : 1'b0;
                SR_reg <= {abs_dividend, 8'b0} << 1;
                cnt_reg <= 4'd1;
                start_cnt_reg <= 1'b1;
                res_valid <= 1'b0;
            end else if (start_cnt_reg) begin
                if (cnt_reg == 4'd8) begin
                    start_cnt_reg <= 1'b0;
                    cnt_reg <= 4'd0;
                    res_valid <= 1'b1;
                    result_reg <= { 
                        (sign_reg && dividend_sign_reg) ? -SR_reg[15:8] : SR_reg[15:8],
                        (sign_reg && (dividend_sign_reg != divisor_sign_reg)) ? -SR_reg[7:0] : SR_reg[7:0] 
                    };
                end else begin
                    if (carry_out) begin
                        SR_reg <= {temp_remainder_9bit[7:0], SR_reg[7:1], 1'b1};
                    end else begin
                        SR_reg <= {SR_reg[15:8], SR_reg[7:1], 1'b0};
                    end
                    cnt_reg <= cnt_reg + 1;
                end
            end
        end
    end

endmodule

