reg [7:0] b_reg;


always @(*) begin
    a_reg = A;
    b_reg = B;
end


always @(*) begin
    reg [15:0] remainder = 16'b0;
    reg [15:0] divisor = {8'b0, b_reg};

    reg [15:0] quotient = 16'b0;

    for (int i = 15;
 i >= 0;
 i = i - 1) begin

        remainder = {remainder[14:0], a_reg[i]};
        if (remainder >= divisor) begin
            remainder = remainder - divisor;
            quotient[i] = 1'b1;
        end else begin
            quotient[i] = 1'b0;
        end
    end

    result = quotient;
    odd = remainder;
end

endmodule

