module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

wire sign_a = a[N-1];
wire sign_b = b[N-1];
wire [N-2:0] mag_a = sign_a ? (~a[N-2:0] + 1) : a[N-2:0];
wire [N-2:0] mag_b = sign_b ? (~b[N-2:0] + 1) : b[N-2:0];

wire [N-1:0] sum_mag = {1'b0, mag_a} + {1'b0, mag_b};
wire [N-1:0] diff_mag;
wire res_sign;

assign diff_mag = (mag_a >= mag_b) ? ({1'b0, mag_a} - {1'b0, mag_b}) : ({1'b0, mag_b} - {1'b0, mag_a});
assign res_sign = (mag_a >= mag_b) ? 1'b0 : 1'b1;

assign c = (sign_a == sign_b) ? sum_mag : {res_sign, diff_mag[N-2:0]};

endmodule

