    reg [23:0] a_mantissa, b_mantissa, z_mantissa;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            case (counter)
                3'b000: begin

                    counter <= counter + 1;
                end
                3'b001: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a[30:23] == 8'b0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b[30:23] == 8'b0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                    counter <= counter + 1;
                end
                3'b010: begin

                    if ((a_exponent == 8'hff && |a[22:0]) || (b_exponent == 8'hff && |b[22:0])) begin
                        z <= 32'h7FC00000;

                    end else if (a_exponent == 8'hff && b_exponent == 8'hff) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h0};

                    end else if (a_exponent == 8'hff || b_exponent == 8'hff) begin
                        if ((a_exponent == 8'hff && b_exponent != 8'hff) || (b_exponent == 8'hff && a_exponent != 8'hff)) begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'h0};

                        end else begin
                            z <= 32'h0;

                        end
                    end else if (a_exponent == 8'h00 && b_exponent == 8'h00) begin
                        if (a_mantissa == 24'h0 && b_mantissa == 24'h0) begin
                            z <= 32'h0;

                        end else begin
                            z <= 32'h0;

                        end
                    end else begin
                        counter <= counter + 1;
                    end
                end
                3'b011: begin

                    product <= a_mantissa * b_mantissa;
                    z_sign <= a_sign ^ b_sign;
                    counter <= counter + 1;
                end
                3'b100: begin

                    if (product[47]) begin
                        product <= product >> 1;
                        z_exponent <= a_exponent + b_exponent - 8'd127 + 8'd1;
                        z_mantissa <= product[46:24];
                        guard_bit <= product[23];
                        round_bit <= product[22];
                        sticky <= |product[21:0];
                    end else begin
                        z_exponent <= a_exponent + b_exponent - 8'd127;
                        z_mantissa <= product[46:24];
                        guard_bit <= product[23];
                        round_bit <= product[22];
                        sticky <= |product[21:0];
                    end
                    counter <= counter + 1;
                end
                3'b101: begin

                    if (guard_bit && (round_bit || sticky || (guard_bit && !round_bit && !sticky))) begin
                        if (z_mantissa == 23'h7FFFFF) begin
                            z_mantissa <= 23'h0;
                            z_exponent <= z_exponent + 8'd1;
                        end else begin
                            z_mantissa <= z_mantissa + 23'd1;
                        end
                    end
                    counter <= counter + 1;
                end
                3'b110: begin

                    if (z_exponent >= 8'hFF) begin
                        z <= {z_sign, 8'hFF, 23'h0};

                    end else if (z_exponent == 8'h00) begin
                        z <= 32'h0;

                    end else begin
                        z <= {z_sign, z_exponent, z_mantissa[22:0]};
                    end
                    counter <= 3'b000;
                end
                default: begin
                    counter <= 3'b000;
                end
            endcase
        end
    end

