                    if (rst) begin
                        res_valid_reg <= 0;
                        SR <= 0;
                        cnt <= 0;
                        start_cnt <= 0;
                        dividend_abs <= 0;
                        divisor_abs <= 0;
                        dividend_sign <= 0;
