module div_16bit (A, B, result, odd);
    input [15:0] A;
    input [7:0] B;
    output reg [15:0] result;
    output reg [15:0] odd;

    reg [15:0] a_reg, b_reg;


    always @(*) begin
        a_reg = A;
        b_reg = B;
    end


    always @(*) begin
        integer i;
        reg [15:0] remainder;
        reg [15:0] temp_A;
        reg [15:0] temp_result;

        remainder = 16'b0;
        temp_A = a_reg;
        temp_result = 16'b0;

        for (i = 15;
 i >= 0;
 i = i - 1) begin
            remainder = {remainder[14:0], temp_A[i]};
            if (remainder >= {8'b0, b_reg}) begin
                temp_result[i] = 1'b1;
                remainder = remainder - {8'b0, b_reg};
            end else begin
                temp_result[i] = 1'b0;
            end
        end

        result = temp_result;
        odd = remainder;
    end
endmodule

