    assign diff[1] = A[1] - B[1] - borrow_0;
    assign borrow_1 = (A[1] < (B[1] + borrow_0)) ? 1'b1 : 1'b0;


    assign diff[2] = A[2] - B[2] - borrow_1;
    assign borrow_2 = (A[2] < (B[2] + borrow_1)) ? 1'b1 : 1'b0;


    assign diff[3] = A[3] - B[3] - borrow_2;
    assign borrow_3 = (A[3] < (B[3] + borrow_2)) ? 1'b1 : 1'b0;

    assign borrow_out = borrow_3;

    assign A_less = borrow_out;
    assign A_equal = (diff == 4'b0) && !borrow_out;
    assign A_greater = (diff != 4'b0) && !borrow_out;

endmodule

