    reg [63:0] addb_pipe [0:N_STAGES];
    reg [63:0] sum_pipe [0:N_STAGES];
    reg [64:0] carry_pipe [0:N_STAGES];
    reg [63:0] o_en_pipe;

    integer i;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0;
 i <= N_STAGES;
 i = i + 1) begin
                adda_pipe[i] <= 64'b0;
                addb_pipe[i] <= 64'b0;
                sum_pipe[i] <= 64'b0;
                carry_pipe[i] <= 65'b0;
            end
            o_en_pipe <= 64'b0;
            result <= 65'b0;
            o_en <= 1'b0;
        end else begin

            if (i_en) begin
                adda_pipe[0] <= adda;
                addb_pipe[0] <= addb;
                sum_pipe[0] <= 64'b0;
                carry_pipe[0] <= 65'b0;
                o_en_pipe[0] <= 1'b1;
            end else begin
                adda_pipe[0] <= adda_pipe[0];
                addb_pipe[0] <= addb_pipe[0];
                sum_pipe[0] <= sum_pipe[0];
                carry_pipe[0] <= carry_pipe[0];
                o_en_pipe[0] <= 1'b0;
            end


            for (i = 1;
 i <= N_STAGES;
 i = i + 1) begin
                if (o_en_pipe[i-1]) begin

                    wire a = adda_pipe[i-1][i-1];
                    wire b = addb_pipe[i-1][i-1];
                    wire carry_in = carry_pipe[i-1];
                    wire sum_bit = a ^ b ^ carry_in;
                    wire carry_out = (a & b) | (a & carry_in) | (b & carry_in);


                    adda_pipe[i] <= adda_pipe[i-1];
                    addb_pipe[i] <= addb_pipe[i-1];
                    sum_pipe[i] <= {sum_pipe[i-1][62:0], sum_bit};
                    carry_pipe[i] <= carry_out;
                    o_en_pipe[i] <= o_en_pipe[i-1];
                end else begin
                    adda_pipe[i] <= adda_pipe[i];
                    addb_pipe[i] <= addb_pipe[i];
                    sum_pipe[i] <= sum_pipe[i];
                    carry_pipe[i] <= carry_pipe[i];
                    o_en_pipe[i] <= o_en_pipe[i];
                end
            end


            result <= {carry_pipe[N_STAGES], sum_pipe[N_STAGES]};
            o_en <= o_en_pipe[N_STAGES];
        end
    end

