module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

    wire a_sign = a[N-1];
    wire b_sign = b[N-1];

    wire [N-2:0] a_mag = a_sign ? (~a[N-2:0] + 1) : a[N-2:0];
    wire [N-2:0] b_mag = b_sign ? (~b[N-2:0] + 1) : b[N-2:0];

    wire same_sign = (a_sign == b_sign);

    always @(*) begin
        if (same_sign) begin
            reg [N-2:0] sum_mag = a_mag + b_mag;
            c = {a_sign, sum_mag};
        end else begin
            if (a_mag > b_mag)
                c = {a_sign, a_mag - b_mag};
            else if (b_mag > a_mag)
                c = {b_sign, b_mag - a_mag};
            else
                c = {1'b0, {(N-2){1'b0}}};
        end
    end

endmodule

