module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [49:0] product;
    reg guard_bit, round_bit, sticky;
    reg [23:0] z_mantissa;


    wire a_is_nan = (a_exponent == 8'hff) && (a_mantissa != 0);
    wire a_is_inf = (a_exponent == 8'hff) && (a_mantissa == 0);
    wire a_is_zero = (a_exponent == 0) && (a_mantissa == 0);
    wire b_is_nan = (b_exponent == 8'hff) && (b_mantissa != 0);
    wire b_is_inf = (b_exponent == 8'hff) && (b_mantissa == 0);
    wire b_is_zero = (b_exponent == 0) && (b_mantissa == 0);


    reg [5:0] leading_one_pos;
    wire [49:0] leading_one_mask = product | (product >> 1) | (product >> 2) | (product >> 3) |
                                  (product >> 4) | (product >> 5) | (product >> 6) | (product >> 7) |
                                  (product >> 8) | (product >> 9) | (product >> 10) | (product >> 11) |
                                  (product >> 12) | (product >> 13) | (product >> 14) | (product >> 15) |
                                  (product >> 16) | (product >> 17) | (product >> 18) | (product >> 19) |
                                  (product >> 20) | (product >> 21) | (product >> 22) | (product >> 23) |
                                  (product >> 24) | (product >> 25) | (product >> 26) | (product >> 27) |
                                  (product >> 28) | (product >> 29) | (product >> 30) | (product >> 31) |
                                  (product >> 32) | (product >> 33) | (product >> 34) | (product >> 35) |
                                  (product >> 36) | (product >> 37) | (product >> 38) | (product >> 39) |
                                  (product >> 40) | (product >> 41) | (product >> 42) | (product >> 43) |
                                  (product >> 44) | (product >> 45) | (product >> 46) | (product >> 47);

    always @(*) begin
        leading_one_pos = 6'd49;
        for (integer i = 49;
 i >= 0;
 i = i - 1) begin
            if (leading_one_mask[i] != 0)
                leading_one_pos = i;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
            a_sign <= 0;
            b_sign <= 0;
            z_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            z_exponent <= 0;
            a_mantissa <= 0;
            b_mantissa <= 0;
            product <= 0;
            guard_bit <= 0;
            round_bit <= 0;
            sticky <= 0;
            z_mantissa <= 0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    a_exponent <= a[30:23];
                    a_mantissa <= a[22:0];
                    b_sign <= b[31];
                    b_exponent <= b[30:23];
                    b_mantissa <= b[22:0];
                    counter <= 3'b001;
                end
                3'b001: begin

                    if (a_is_nan || b_is_nan) begin
                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 8'hff;
                        z_mantissa <= 23'h1;
                        z <= {z_sign, z_exponent, z_mantissa};
                        counter <= 3'b111;
                    end else if (a_is_inf || b_is_inf) begin
                        if (a_is_zero || b_is_zero) begin
                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= 8'hff;
                            z_mantissa <= 23'h1;
                            z <= {z_sign, z_exponent, z_mantissa};
                            counter <= 3'b111;
                        end else begin
                            z_sign <= a_sign ^ b_sign;
                            z_exponent <= 8'hff;
                            z_mantissa <= 23'b0;
                            z <= {z_sign, z_exponent, z_mantissa};
                            counter <= 3'b111;
                        end
                    end else if (a_is_zero || b_is_zero) begin
                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 8'b0;
                        z_mantissa <= 23'b0;
                        z <= {z_sign, z_exponent, z_mantissa};
                        counter <= 3'b111;
                    end else begin

                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= a_exponent + b_exponent - 127;

                        product <= {1'b1, a_mantissa} * {1'b1, b_mantissa};
                        counter <= 3'b010;
                    end
                end
                3'b010: begin

                    if (product != 0) begin
                        reg [7:0] shift = 49 - leading_one_pos;
                        reg [49:0] normalized_product = product << shift;
                        z_exponent <= z_exponent + shift;

                        guard_bit <= normalized_product[24];
                        round_bit <= normalized_product[23];
                        sticky <= |normalized_product[22:0];
                    end
                    counter <= 3'b011;
                end
                3'b011: begin

                    if (product != 0) begin
                        reg [23:0] rounded_mantissa = {1'b0, normalized_product[48:25]} + {23'd0, guard_bit & (round_bit | sticky)};
                        if (rounded_mantissa[23]) begin
                            z_exponent <= z_exponent + 1;
                            z_mantissa <= rounded_mantissa[23:1];
                        end else begin
                            z_mantissa <= rounded_mantissa[22:0];
                        end
                    end
                    counter <= 3'b100;
                end
                3'b100: begin

                    if (z_exponent > 8'hfe) begin

                        z <= {z_sign, 8'hff, 23'b0};
                    end else if (z_exponent == 0) begin

                        z <= {z_sign, 8'b0, z_mantissa};
                    end else begin

                        z <= {z_sign, z_exponent, z_mantissa};
                    end
                    counter <= 3'b000;
                end
                default: counter <= 3'b000;
            endcase
        end
    end

endmodule

