module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wrstn,
    input winc,
    input [WIDTH-1:0] wdata,
    output wfull,
    input rclk,
    input rrstn,
    input rinc,
    output rempty,
    output [WIDTH-1:0] rdata
);

localparam PTR_WIDTH = $clog2(DEPTH);
localparam ADDR_WIDTH = $clog2(DEPTH);


reg [PTR_WIDTH-1:0] waddr_bin, wptr_gray, wptr_buff;
reg [PTR_WIDTH-1:0] rptr_gray_rclk, rptr_syn;


reg [PTR_WIDTH-1:0] raddr_bin, rptr_gray, rptr_buff;
reg [PTR_WIDTH-1:0] wptr_gray_wclk, wptr_syn;


reg [PTR_WIDTH-1:0] rptr_gray_sync1, rptr_gray_sync2;
reg [PTR_WIDTH-1:0] wptr_gray_sync1, wptr_gray_sync2;

function [PTR_WIDTH-1:0] bin2gray;
    input [PTR_WIDTH-1:0] bin;
    begin
        bin2gray = bin ^ (bin >> 1);
    end
endfunction

wire [PTR_WIDTH-1:0] wptr_gray = bin2gray(waddr_bin);
wire [PTR_WIDTH-1:0] rptr_gray = bin2gray(raddr_bin);


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rptr_gray_sync1 <= 0;
        rptr_gray_sync2 <= 0;
    end else begin
        rptr_gray_sync1 <= rptr_gray;
        rptr_gray_sync2 <= rptr_gray_sync1;
    end
end
assign rptr_syn = rptr_gray_sync2;


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        wptr_gray_sync1 <= 0;
        wptr_gray_sync2 <= 0;
    end else begin
        wptr_gray_sync1 <= wptr_gray;
        wptr_gray_sync2 <= wptr_gray_sync1;
    end
end
assign wptr_syn = wptr_gray_sync2;


always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        waddr_bin <= 0;
        wptr_buff <= 0;
    end else begin
        waddr_bin <= waddr_bin + (winc && !wfull);
        wptr_buff <= waddr_bin;
    end
end


always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        raddr_bin <= 0;
        rptr_buff <= 0;
    end else begin
        raddr_bin <= raddr_bin + (rinc && !rempty);
        rptr_buff <= raddr_bin;
    end
end


assign wfull = (wptr_gray == rptr_syn) ? 
               1'b0 : 
               ((wptr_gray[PTR_WIDTH-1] != rptr_syn[PTR_WIDTH-1]) && 
                (wptr_gray[PTR_WIDTH-2] != rptr_syn[PTR_WIDTH-2]) && 
                (wptr_gray[PTR_WIDTH-3:0] == rptr_syn[PTR_WIDTH-3:0]));

assign rempty = (wptr_syn == rptr_gray) ? 1'b1 : 1'b0;


wire wen = winc && !wfull;
wire ren = rinc && !rempty;

dual_port_RAM #(
    .WIDTH(WIDTH),
    .DEPTH(DEPTH)
) ram_inst (
    .wclk(wclk),
    .wenc(wen),
    .waddr(waddr_bin[ADDR_WIDTH-2:0]),
    .wdata(wdata),
    .rclk(rclk),
    .renc(ren),
    .raddr(raddr_bin[ADDR_WIDTH-2:0]),
    .rdata(rdata)
);

endmodule

module dual_port_RAM #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wenc,
    input [$clog2(DEPTH)-1:0] waddr,
    input [WIDTH-1:0] wdata,
    input rclk,
    input renc,
    input [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

always @(posedge wclk) begin
    if (wenc)
        RAM_MEM[waddr] <= wdata;
end

always @(posedge rclk) begin
    if (renc)
        rdata <= RAM_MEM[raddr];
end

endmodule

