module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);

    reg [32:0] res;

    reg [4:0] shamt;


    assign flag = (aluc == SLT || aluc == SLTU) ? 1'b1 : 1'bz;


    always @* begin
        case (aluc)
            ADD, ADDU: begin
                res = {1'b0, a} + {1'b0, b};
            end
            SUB, SUBU: begin
                res = {1'b0, a} - {1'b0, b};
            end
            AND: res = {1'b0, a & b};
            OR: res = {1'b0, a | b};
            XOR: res = {1'b0, a ^ b};
            NOR: res = {1'b0, ~(a | b)};
            SLT: res = {1'b0, (a < b) ? 32'd1 : 32'd0};
            SLTU: res = {1'b0, (a < b) ? 32'd1 : 32'd0};
            SLL: begin
                shamt = a[4:0];
                res = {1'b0, a} << shamt;
            end
            SRL: begin
                shamt = a[4:0];
                res = {1'b0, a} >> shamt;
            end
            SRA: begin
                shamt = a[4:0];
                res = $signed({1'b0, a}) >>> shamt;
            end
            SLLV: begin
                shamt = a[4:0];
                res = {1'b0, b} << shamt;
            end
            SRLV: begin
                shamt = a[4:0];
                res = {1'b0, b} >> shamt;
            end
            SRAV: begin
                shamt = a[4:0];
                res = $signed({1'b0, b}) >>> shamt;
            end
            LUI: res = {a[15:0], 16'b0};
            default: res = 33'bz;
        endcase
    end

    assign r = res[31:0];
    assign carry = (aluc == ADD || aluc == ADDU || aluc == SUB || aluc == SUBU) ? res[32] : 
                    (aluc inside {SLL, SRL, SRA, SLLV, SRLV, SRAV}) ? 
                        (aluc == SLL) ? ((shamt == 0) ? 1'b0 : a[32 - shamt]) :
                        (aluc == SRL || aluc == SRA) ? ((shamt == 0) ? 1'b0 : a[shamt - 1]) :
                        (aluc == SLLV) ? ((shamt == 0) ? 1'b0 : b[32 - shamt]) :
                        (aluc == SRLV || aluc == SRAV) ? ((shamt == 0) ? 1'b0 : b[shamt - 1]) : 1'b0 : 1'b0;

    assign zero = (r == 32'b0);
    assign negative = r[31];
    assign overflow = (aluc == ADD || aluc == SUB) ? 
                        ((aluc == ADD) ? ((a[31] == b[31]) && (r[31] != a[31])) :
                                         ((a[31] != b[31]) && (r[31] != a[31]))) : 1'b0;

endmodule

