module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output [15:0] result
);

    reg [15:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] abs_dividend, abs_divisor;
    reg dividend_sign, divisor_sign;
    reg [7:0] NEG_DIVISOR;
    reg [15:0] result_reg;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            cnt <= 0;
            start_cnt <= 0;
            SR <= 0;
            abs_dividend <= 0;
            abs_divisor <= 0;
            dividend_sign <= 0;
            divisor_sign <= 0;
            NEG_DIVISOR <= 0;
            result_reg <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                dividend_sign <= dividend[7];
                divisor_sign <= divisor[7];
                abs_dividend <= sign ? (dividend[7] ? -dividend : dividend) : dividend;
                abs_divisor <= sign ? (divisor[7] ? -divisor : divisor) : divisor;
                NEG_DIVISOR <= -abs_divisor;

                SR <= {abs_dividend, 1'b0};
                cnt <= 1;
                start_cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt) begin
                if (cnt == 8) begin

                    start_cnt <= 0;
                    cnt <= 0;
                    res_valid <= 1;

                    if (sign) begin
                        reg [7:0] q = SR[7:0];
                        reg [7:0] r = SR[15:8];
                        reg [7:0] signed_q = (dividend_sign ^ divisor_sign) ? -q : q;
                        reg [7:0] signed_r = dividend_sign ? -r : r;
                        result_reg <= {signed_r, signed_q};
                    end else begin
                        result_reg <= SR;
                    end
                end else begin

                    reg [8:0] temp_remainder = {1'b0, SR[15:8]} - {1'b0, NEG_DIVISOR};
                    if (temp_remainder[8] == 1'b0) begin 
                        SR <= {temp_remainder[7:0], SR[7:1] | 1'b1};
                    end else begin
                        SR <= {SR[15:8], SR[7:1] | 1'b0};
                    end
                    cnt <= cnt + 1;
                end
            end
        end
    end

    assign result = result_reg;

endmodule

