module div_16bit(
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

reg [15:0] a_reg, b_reg;


always @(*) begin
    a_reg = A;
    b_reg = B;
end


always @(*) begin
    reg [15:0] quo = 16'd0;
    reg [15:0] rem = 16'd0;
    integer i;

    for (i = 15;
 i >= 0;
 i = i - 1) begin
        rem = rem << 1;
        rem[0] = a_reg[i];
        if (rem >= b_reg) begin
            quo[i] = 1'b1;
            rem = rem - b_reg;
        end
    end

    result = quo;
    odd = rem;
end

endmodule

