module comparator_4bit (
    input [3:0] A,
    input [3:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

    wire [3:0] borrow;
    assign borrow[0] = 1'b0;

    genvar i;
    generate
        for (i = 0;
 i < 4;
 i = i + 1) begin : sub
            assign borrow[i+1] = (A[i] < (B[i] + borrow[i])) ? 1'b1 : 1'b0;
        end
    endgenerate

    wire [3:0] diff = A - B;
    wire borrow_out = borrow[4];

    assign A_less = borrow_out;
    assign A_equal = (diff == 4'b0) && !borrow_out;
    assign A_greater = (diff != 4'b0) && !borrow_out;

endmodule

