module fixed_point_adder #(
    parameter Q = 2,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

reg [N-1:0] res;
reg sign_a, sign_b;
reg [N-2:0] mag_a, mag_b;
reg a_gt_b;

always @(*) begin
    sign_a = a[N-1];
    sign_b = b[N-1];
    mag_a = sign_a ? (~a[N-2:0] + 1) : a[N-2:0];
    mag_b = sign_b ? (~b[N-2:0] + 1) : b[N-2:0];
    a_gt_b = (mag_a > mag_b) || ((mag_a == mag_b) && (sign_a > sign_b));

    if (sign_a == sign_b) begin

        res = {sign_a, mag_a + mag_b};
    end else begin

        if (mag_a > mag_b) begin
            res = {sign_a, mag_a - mag_b};
        end else if (mag_b > mag_a) begin
            res = {sign_b, mag_b - mag_a};
        end else begin
            res = 0;
        end
    end
end

assign c = res;

endmodule

