    if (a[N-1] == b[N-1]) begin

        res = a - b;
        res[N-1] = a[N-1];

    end else begin

        reg [N-1:0] abs_a, abs_b;
        abs_a = a[N-1] ? (~a + 1) : a;

        abs_b = b[N-1] ? (~b + 1) : b;

        res = abs_a + abs_b;

        res[N-1] = (abs_a > abs_b) ? 1'b0 : 1'b1;
    end

    if (res == 0)
        res[N-1] = 1'b0;
end

assign c = res;

endmodule

