module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign;
    reg [7:0] a_exponent, b_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [23:0] a_mantissa_full, b_mantissa_full;
    reg [47:0] product;
    reg [8:0] exponent_initial, exponent_final;
    reg z_sign;
    reg guard_bit, round_bit, sticky_bit;
    reg [23:0] mantissa_rounded;

    wire a_is_nan = (a_exponent == 8'hff) && (a_mantissa != 0);
    wire b_is_nan = (b_exponent == 8'hff) && (b_mantissa != 0);
    wire a_is_inf = (a_exponent == 8'hff) && (a_mantissa == 0);
    wire b_is_inf = (b_exponent == 8'hff) && (b_mantissa == 0);
    wire a_is_zero = (a_exponent == 0) && (a_mantissa == 0);
    wire b_is_zero = (b_exponent == 0) && (b_mantissa == 0);

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            case (counter)
                3'b000: begin
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= a[22:0];
                    b_mantissa <= b[22:0];

                    a_mantissa_full <= (a_exponent == 0) ? {1'b0, a_mantissa} : {1'b1, a_mantissa};
                    b_mantissa_full <= (b_exponent == 0) ? {1'b0, b_mantissa} : {1'b1, b_mantissa};

                    product <= a_mantissa_full * b_mantissa_full;

                    exponent_initial <= ((a_exponent == 0) ? -9'd126 : (a_exponent - 127)) + 
                                       ((b_exponent == 0) ? -9'd126 : (b_exponent - 127)) + 9'd127;

                    z_sign <= a_sign ^ b_sign;
                    counter <= 3'b001;
                end

                3'b001: begin
                    reg [47:0] temp_product = product;
                    integer i;
                    reg [5:0] leading_one_pos;
                    leading_one_pos = 6'd47;
                    for (i = 47;
 i >= 0;
 i = i - 1)
                        if (temp_product[i]) begin
                            leading_one_pos = i;
                            break;
                        end

                    reg [5:0] shift_amount = 6'd47 - leading_one_pos;
                    reg [47:0] product_shifted = temp_product << shift_amount;
                    exponent_final <= exponent_initial - shift_amount;

                    reg [23:0] mantissa_bits = product_shifted[47:24];
                    guard_bit <= product_shifted[23];
                    round_bit <= product_shifted[22];
                    sticky_bit <= |product_shifted[21:0];

                    if (guard_bit && (round_bit || sticky_bit))
                        mantissa_rounded = mantissa_bits + 1;
                    else
                        mantissa_rounded = mantissa_bits;

                    if (mantissa_rounded[23]) begin
                        exponent_final <= exponent_final + 1;
                        mantissa_rounded <= 24'b0;
                    end

                    counter <= 3'b010;
                end

                3'b010: begin
                    if (exponent_final[8] || exponent_final > 9'd254) begin
                        if (exponent_final > 9'd254)
                            z <= {z_sign, 8'hff, 23'h000001};
                        else if (exponent_final == 9'd0)
                            z <= {z_sign, 31'd0};
                        else
                            z <= {z_sign, 8'hff, 23'h000001};
                    end else
                        z <= {z_sign, exponent_final[7:0], mantissa_rounded[22:0]};
                    counter <= 3'b0;
                end

                default: counter <= 3'b0;
            endcase
        end
    end

endmodule

