module sub_64bit (
    input [63:0] A,
    input [63:0] B,
    output [63:0] result,
    output overflow
);

    assign result = A - B;


    wire sign_A = A[63];
    wire sign_B = B[63];
    wire sign_res = result[63];


    assign overflow = (sign_A == 1'b0 && sign_B == 1'b1 && sign_res == 1'b1) ||
                      (sign_A == 1'b1 && sign_B == 1'b0 && sign_res == 1'b0);

endmodule

