module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

reg [1:0] state, state_next;
localparam IDLE        = 2'b00,
           WAIT_FOR_1 = 2'b01,
           WAIT_FOR_0 = 2'b10;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        data_out <= 1'b0;
    end
    else begin
        state <= state_next;
        data_out <= (state == WAIT_FOR_0 && data_in == 1'b0) ? 1'b1 : 1'b0;
    end
end

always @(*) begin
    case (state)
        IDLE: 
            state_next = (data_in == 1'b0) ? WAIT_FOR_1 : IDLE;
        WAIT_FOR_1: 
            state_next = (data_in == 1'b1) ? WAIT_FOR_0 : IDLE;
        WAIT_FOR_0: 
            state_next = (data_in == 1'b0) ? IDLE : IDLE;
        default: 
            state_next = IDLE;
    endcase
end

endmodule

