module traffic_light(
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

    reg [7:0] cnt;
    reg [1:0] state;
    reg p_red, p_yellow, p_green;
    reg p_red_prev, p_yellow_prev, p_green_prev;

    localparam idle = 2'b00,
               s3_green = 2'b01,
               s2_yellow = 2'b10,
               s1_red = 2'b11;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            case (state)
                idle: state <= s3_green;

                s3_green: state <= s2_yellow;

                s2_yellow: state <= s1_red;

                s1_red: state <= s3_green;

                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red_prev <= 1'b0;
            p_yellow_prev <= 1'b0;
            p_green_prev <= 1'b0;
        end else begin
            p_red_prev <= p_red;
            p_yellow_prev <= p_yellow;
            p_green_prev <= p_green;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd10;
        end else begin
            if (pass_request && p_green && (cnt > 8'd10)) begin
                cnt <= 8'd10;
            end else case (1'b1)
                (state == s3_green): cnt <= cnt - 8'd1;

                (state == s2_yellow): cnt <= cnt - 8'd1;

                (state == s1_red): cnt <= cnt - 8'd1;

                (state == idle): cnt <= 8'd60;

                default: cnt <= cnt;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red <= 1'b0;
            p_yellow <= 1'b0;
            p_green <= 1'b0;
        end else begin
            case (state)
                idle: {p_red, p_yellow, p_green} <= 3'b000;
                s3_green: {p_red, p_yellow, p_green} <= 3'b001;
                s2_yellow: {p_red, p_yellow, p_green} <= 3'b010;
                s1_red: {p_red, p_yellow, p_green} <= 3'b100;
                default: {p_red, p_yellow, p_green} <= 3'b000;
            endcase
        end
    end

    assign clock = cnt;
    assign red = p_red;
    assign yellow = p_yellow;
    assign green = p_green;

endmodule

