module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

reg [15:0] SR;

reg [3:0] cnt;
reg start_cnt;
reg [7:0] dividend_abs, divisor_abs;
reg sign_reg;

always @(posedge clk) begin
    if (rst) begin
        res_valid <= 1'b0;
        SR <= 16'b0;
        cnt <= 4'b0;
        start_cnt <= 1'b0;
        dividend_abs <= 8'b0;
        divisor_abs <= 8'b0;
        sign_reg <= 1'b0;
    end else begin
        if (opn_valid && !res_valid) begin

            if (sign) begin
                sign_reg <= dividend[7];
                dividend_abs <= dividend[7] ? -dividend : dividend;
                divisor_abs <= divisor[7] ? -divisor : divisor;
            end else begin
                sign_reg <= 1'b0;
                dividend_abs <= dividend;
                divisor_abs <= divisor;
            end


            SR <= {dividend_abs, 8'b0} << 1;
            cnt <= 4'd1;
            start_cnt <= 1'b1;
            res_valid <= 1'b0;
        end else if (start_cnt && !res_valid) begin
            if (cnt == 4'd8) begin

                start_cnt <= 1'b0;
                cnt <= 4'd0;


                if (sign) begin
                    if (dividend[7] ^ divisor[7]) 
                        SR[7:0] <= -SR[7:0];

                    if (sign_reg != dividend[7]) 
                        SR[16:8] <= SR[16:9] - {1'b0, divisor_abs};

                end
                result <= {SR[16:9], SR[7:0]};
                res_valid <= 1'b1;
            end else begin

                if (SR[16:8] >= {1'b0, divisor_abs}) begin
                    SR <= {SR[16:8] - {1'b0, divisor_abs}, SR[7:1], 1'b1};
                end else begin
                    SR <= {SR[16:8], SR[7:1], 1'b0};
                end
                cnt <= cnt + 1;
            end
        end else begin
            res_valid <= 1'b0;
        end
    end
end

endmodule

