module cla_16bit (
    input [15:0] A,
    input [15:0] B,
    input C_in,
    output [15:0] S,
    output P,
    output G
);

wire [15:0] p = A ^ B;
wire [15:0] g = A & B;

assign P = &p;



wire [15:0] G_temp;
assign G_temp[15] = g[15];
genvar i;
generate
    for (i = 14;
 i >= 0;
 i = i - 1) begin : gen_g_temp
        assign G_temp[i] = G_temp[i + 1] | (p[i + 1] & g[i]);
    end
endgenerate
assign G = G_temp[0];


wire [15:0] C;
assign C[0] = C_in;
genvar j;
generate
    for (j = 1;
 j <= 15;
 j = j + 1) begin : gen_carry
        assign C[j] = G_temp[j-1] | (p[j-1] & C[j-1]);
    end
endgenerate

assign S = p ^ C;

endmodule

module adder_32bit (
    input [32:1] A,
    input [32:1] B,
