module fixed_point_adder #(
    parameter Q,
    parameter N
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output [N-1:0] c
);

reg [N-1:0] res;
wire a_msb = a[N-1];
wire b_msb = b[N-1];

wire [N-1:0] abs_a = a_msb ? (-a) : a;
wire [N-1:0] abs_b = b_msb ? (-b) : b;
wire [N-1:0] sum_abs = abs_a + abs_b;

always @* begin
    if (a_msb == b_msb) begin

        res = {a_msb, sum_abs[N-2:0]};
    end else begin

        if (abs_a > abs_b) begin
            res = {abs_a[N-1], (abs_a - abs_b)[N-2:0]};
        end else if (abs_b > abs_a) begin
            res = {abs_b[N-1], (abs_b - abs_a)[N-2:0]};
        end else begin

            res = {1'b0, {(N-1){1'b0}}};
        end
    end
end

assign c = res;

endmodule

