module fixed_point_subtractor #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

reg sign_a, sign_b;
reg [N-2:0] magnitude_a, magnitude_b;
reg [N-1:0] sum_mag;
reg res_sign;
reg [N-1:0] res;

always @(*) begin
    sign_a = a[N-1];
    sign_b = b[N-1];
    res = 0;

    if (sign_a == sign_b) begin

        res = a - b;
        res_sign = sign_a;
    end else begin

        magnitude_a = sign_a ? (~a[N-2:0] + 1) : a[N-2:0];
        magnitude_b = sign_b ? (~b[N-2:0] + 1) : b[N-2:0];
        sum_mag = magnitude_a + magnitude_b;


        if (magnitude_a > magnitude_b) begin
            res_sign = sign_a;
        end else begin
            res_sign = ~sign_a;
        end


        if (res_sign) begin
            res = ~sum_mag + 1;

        end else begin
            res = sum_mag;
        end
    end


    if (res == 0) begin
        res = 0;
    end

    c = res;
end

endmodule

