module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);
    reg [2:0] counter;
    reg [7:0] a_exponent, b_exponent;
    reg a_sign, b_sign;
    reg [22:0] a_mantissa, b_mantissa;
    reg [49:0] product;
    reg guard_bit, round_bit, sticky;
    reg [7:0] z_exponent;
    reg z_sign;
    reg [22:0] z_mantissa;


    reg a_is_zero, b_is_zero;
    reg a_is_inf, b_is_inf;
    reg a_is_nan, b_is_nan;
    reg special_case;


    always @(posedge clk) begin
        if (rst)
            counter <= 3'b0;
        else
            counter <= counter + 1;
    end


    always @(*) begin
        a_sign = a[31];
        a_exponent = a[30:23];
        a_mantissa = (a_exponent == 0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
        b_sign = b[31];
        b_exponent = b[30:23];
        b_mantissa = (b_exponent == 0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};

        a_is_zero = (a_exponent == 0) && (a_mantissa == 0);
        b_is_zero = (b_exponent == 0) && (b_mantissa == 0);
        a_is_inf = (a_exponent == 8'hFF) && (a_mantissa == 0);
        b_is_inf = (b_exponent == 8'hFF) && (b_mantissa == 0);
        a_is_nan = (a_exponent == 8'hFF) && (a_mantissa != 0);
        b_is_nan = (b_exponent == 8'hFF) && (b_mantissa != 0);
        special_case = a_is_nan || b_is_nan || 
                       (a_is_inf && b_is_zero) || 
                       (b_is_inf && a_is_zero);
    end


    always @(*) begin
        product = a_mantissa * b_mantissa;
        if (product == 0) begin
            z_exponent = 0;
            z_mantissa = 0;
            z_sign = a_sign ^ b_sign;
        end else begin
            integer i;
            reg [5:0] leading_one;
            leading_one = 6'd47;
            for (i = 47;
 i >= 0;
 i = i - 1)
                if (product[i]) begin
                    leading_one = i;
                    break;
                end
            product = product << (47 - leading_one);
            z_exponent = a_exponent + b_exponent - 127 + (47 - leading_one);
            z_mantissa = product[46:24];
            guard_bit = product[23];
            round_bit = product[22];
            sticky = |product[21:0];
            if (guard_bit && (round_bit || sticky)) begin
                z_mantissa = z_mantissa + 1;
                if (z_mantissa == 0)
                    z_exponent = z_exponent + 1;
            end
        end
    end


    always @(posedge clk) begin
        if (rst) begin
            z <= 0;
            counter <= 0;
        end else if (special_case) begin
            z <= {1'b0, 8'hFF, 23'h1};
        end else if (a_is_zero || b_is_zero) begin
            z <= {a_sign ^ b_sign, 8'd0, 23'd0};
        end else begin
            z <= {z_sign, z_exponent, z_mantissa};
        end
    end

endmodule

