module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wrstn,
    input winc,
    input [WIDTH-1:0] wdata,
    output wfull,
    output rempty,
    output [WIDTH-1:0] rdata,
    input rclk,
    input rrstn,
    input rinc
);


    dual_port_RAM #(
        .DEPTH(DEPTH),
        .WIDTH(WIDTH)
    ) ram (
        .wclk(wclk),
        .wenc(winc && !wfull),
        .waddr(waddr_bin[2:0]),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc && !rempty),
        .raddr(raddr_bin[2:0]),
        .rdata(rdata)
    );


    reg [3:0] waddr_bin, raddr_bin;
    wire [3:0] wptr_gray = (waddr_bin >> 1) ^ waddr_bin;
    wire [3:0] rptr_gray = (raddr_bin >> 1) ^ raddr_bin;


    reg [3:0] rptr_gray_sync1, rptr_gray_sync2;
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) {rptr_gray_sync2, rptr_gray_sync1} <= 8'b0;
        else {rptr_gray_sync2, rptr_gray_sync1} <= {rptr_gray_sync1, rptr_gray};
    end


    reg [3:0] wptr_gray_sync1, wptr_gray_sync2;
    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) {wptr_gray_sync2, wptr_gray_sync1} <= 8'b0;
        else {wptr_gray_sync2, wptr_gray_sync1} <= {wptr_gray_sync1, wptr_gray};
    end


    assign wfull = (wptr_gray[3] != rptr_gray_sync2[3]) && 
                   (wptr_gray[2] != rptr_gray_sync2[2]) && 
                   (wptr_gray[1:0] == rptr_gray_sync2[1:0]);
    assign rempty = (rptr_gray == wptr_gray_sync2);


    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) waddr_bin <= 0;
        else if (winc && !wfull) waddr_bin <= waddr_bin + 1;
    end

    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) raddr_bin <= 0;
        else if (rinc && !rempty) raddr_bin <= raddr_bin + 1;
    end

endmodule


