module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output reg red,
    output reg yellow,
    output reg green
);

    parameter idle = 2'd0;
    parameter s1_red = 2'd1;
    parameter s2_yellow = 2'd2;
    parameter s3_green = 2'd3;

    reg [7:0] cnt;
    reg [1:0] state, next_state;
    reg p_red, p_yellow, p_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
        end else begin
            state <= next_state;
        end
    end


    always @(*) begin
        case (state)
            idle: next_state = s1_red;
            s1_red: next_state = (cnt == 0) ? s3_green : s1_red;
            s3_green: next_state = (cnt == 0) ? s2_yellow : s3_green;
            s2_yellow: next_state = (cnt == 0) ? s1_red : s2_yellow;
            default: next_state = idle;
        endcase
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 8'd10;
        end else begin
            if (pass_request && p_green) begin
                cnt <= 8'd10;
            end else if (state == s3_green && p_green) begin
                cnt <= 8'd60;
            end else if (state == s2_yellow && p_yellow) begin
                cnt <= 8'd5;
            end else if (state == s1_red && p_red) begin
                cnt <= 8'd10;
            end else begin
                cnt <= cnt - 1;
            end
        end
    end

    assign clock = cnt;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            p_red <= 1'b0;
            p_yellow <= 1'b0;
            p_green <= 1'b0;
        end else begin
            p_red <= (state == s1_red) ? 1'b1 : p_red;
            p_yellow <= (state == s2_yellow) ? 1'b1 : p_yellow;
            p_green <= (state == s3_green) ? 1'b1 : p_green;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            red <= 1'b0;
            yellow <= 1'b0;
            green <= 1'b0;
        end else begin
            red <= p_red;
            yellow <= p_yellow;
            green <= p_green;
        end
    end

endmodule

