module width_8to16 (
    input clk,
    input rst_n,
    input valid_in,
    input [7:0] data_in,
    output reg valid_out,
    output reg [15:0] data_out
);

    reg [7:0] data_lock;
    reg flag;
    reg [15:0] concat_reg;
    reg concat_valid_reg;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_lock <= 8'b0;
            flag <= 1'b0;
        end else begin
            if (valid_in) begin
                if (flag) begin

                    data_lock <= 8'b0;
                    flag <= 1'b0;
                end else begin

                    data_lock <= data_in;
                    flag <= 1'b1;
                end
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            concat_reg <= 16'b0;
            concat_valid_reg <= 1'b0;
        end else begin
            concat_reg <= 16'b0;
            concat_valid_reg <= 1'b0;

            if (valid_in && flag) begin
                concat_reg <= {data_lock, data_in};
                concat_valid_reg <= 1'b1;
            end
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_out <= 16'b0;
            valid_out <= 1'b0;
        end else begin
            data_out <= concat_reg;
            valid_out <= concat_valid_reg;
        end
    end

endmodule

