module serial2parallel (
    input clk,
    input rst_n,
    input din_serial,
    input din_valid,
    output reg [7:0] dout_parallel,
    output reg dout_valid
);

reg [3:0] cnt;
reg [7:0] shift_reg;

always @(posedge clk) begin
    if (!rst_n) begin
        shift_reg <= 8'b0;
        cnt <= 4'b0;
        dout_parallel <= 8'b0;
        dout_valid <= 1'b0;
    end else begin
        dout_valid <= 1'b0;

        if (din_valid) begin

            shift_reg <= {din_serial, shift_reg[7:1]};

            if (cnt == 4'd7) begin

                dout_parallel <= {din_serial, shift_reg[7:1]};
                dout_valid <= 1'b1;
                cnt <= 4'b0;
            end else begin
                cnt <= cnt + 1;
            end
        end
    end
end

endmodule

