module signal_generator (
    input clk,
    input rst_n,
    output reg [4:0] wave
);

reg state;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        state <= 1'b0;
        wave <= 5'b0;
    end else begin
        case (state)
            1'b0: begin
                if (wave == 5'd30) begin
                    state <= 1'b1;
                    wave <= 5'd31;
                end else begin
                    wave <= wave + 1;
                end
            end
            1'b1: begin
                if (wave == 5'd1) begin
                    state <= 1'b0;
                    wave <= 5'd0;
                end else begin
                    wave <= wave - 1;
                end
            end
        endcase
    end
end

endmodule

