module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output flag
);


    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;


    reg [32:0] sum_add, sum_addu;
    reg [32:0] diff_sub, diff_subu;
    reg [31:0] slt, sltu;
    reg [31:0] sll, srl, sra;
    reg [31:0] sllv, srlv, srav;
    reg [31:0] lui;

    always @(*) begin

        r = 32'bz;
        carry = 1'b0;
        overflow = 1'b0;

        case (aluc)
            ADD: begin
                sum_add = {1'b0, a} + {1'b0, b};
                r = sum_add[31:0];
                carry = sum_add[32];
                overflow = (a[31] == b[31]) && (r[31] != a[31]);
            end
            ADDU: begin
                sum_addu = {1'b0, a} + {1'b0, b};
                r = sum_addu[31:0];
                carry = sum_addu[32];
            end
            SUB: begin
                diff_sub = {1'b0, a} - {1'b0, b};
                r = diff_sub[31:0];
                carry = diff_sub[32];
                overflow = (a[31] != b[31]) && (r[31] != a[31]);
            end
            SUBU: begin
                diff_subu = {1'b0, a} - {1'b0, b};
                r = diff_subu[31:0];
                carry = diff_subu[32];
            end
            AND: begin
                r = a & b;
            end
            OR: begin
                r = a | b;
            end
            XOR: begin
                r = a ^ b;
            end
            NOR: begin
                r = ~(a | b);
            end
            SLT: begin
                slt = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
                r = slt;
            end
            SLTU: begin
                sltu = (a < b) ? 32'd1 : 32'd0;
                r = sltu;
            end
            SLL: begin
                sll = b << a[4:0];
                r = sll;
            end
            SRL: begin
                srl = b >> a[4:0];
                r = srl;
            end
            SRA: begin
                sra = $signed(b) >>> a[4:0];
                r = sra;
            end
            SLLV: begin
                sllv = b << a[4:0];
                r = sllv;
            end
            SRLV: begin
                srlv = b >> a[4:0];
                r = srlv;
            end
            SRAV: begin
                srav = $signed(b) >>> a[4:0];
                r = srav;
            end
            LUI: begin
                lui = {a[15:0], 16'b0};
                r = lui;
            end
            default: r = 32'bz;
        endcase
    end


    assign zero = (r == 32'b0);
    assign negative = r[31];
    assign flag = (aluc == SLT || aluc == SLTU) ? 1'b1 : 1'bz;

endmodule

