module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [7:0] abs_dividend;
    reg [7:0] abs_divisor;
    reg [8:0] NEG_DIVISOR;
    reg [15:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    reg sign_reg;
    reg div_sign;
    reg quo_sign;
    reg rem_sign;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 1'b0;
            SR <= 16'b0;
            cnt <= 4'b0;
            start_cnt <= 1'b0;
            abs_dividend <= 8'b0;
            abs_divisor <= 8'b0;
            NEG_DIVISOR <= 9'b0;
            sign_reg <= 1'b0;
            div_sign <= 1'b0;
            quo_sign <= 1'b0;
            rem_sign <= 1'b0;
            result <= 16'b0;
        end else begin
            if (opn_valid && !res_valid) begin

                sign_reg <= sign;
                if (sign) begin
                    div_sign <= divisor[7];
                    quo_sign <= (dividend[7] ^ divisor[7]) ? 1'b1 : 1'b0;
                    rem_sign <= dividend[7];
                    abs_dividend <= dividend[7] ? -dividend : dividend;
                    abs_divisor <= divisor[7] ? -divisor : divisor;
                    NEG_DIVISOR <= -(divisor[7] ? -divisor : divisor);
                end else begin
                    quo_sign <= 1'b0;
                    rem_sign <= 1'b0;
                    abs_dividend <= dividend;
                    abs_divisor <= divisor;
                    NEG_DIVISOR <= -divisor;
                end
                SR <= {7'b0, abs_dividend << 1};

                start_cnt <= 1'b1;
                cnt <= 4'b1;
                res_valid <= 1'b0;
            end else if (start_cnt) begin
                if (cnt == 4'b1000) begin 
                    start_cnt <= 1'b0;
                    res_valid <= 1'b1;
                    result <= {SR[15:8], SR[7:0]};
                end else begin
                    cnt <= cnt + 1;
                    reg [8:0] sub_res = SR[15:7] - NEG_DIVISOR;
                    if (sub_res[8] == 1'b1) begin
                        SR <= {sub_res[7:0], SR[6:0], 1'b1};
                    end else begin
                        SR <= {sub_res[7:0], SR[6:0], 1'b0};
                    end
                end
            end else begin
                res_valid <= 1'b0;
            end
        end
    end


    always @(posedge clk) begin
        if (res_valid && sign) begin
            if (quo_sign) begin
                result[7:0] <= ~result[7:0] + 1'b1;
            end
            if (rem_sign && (abs_dividend >= abs_divisor)) begin
                result[15:8] <= ~result[15:8] + 1'b1;
            end
        end
    end

endmodule

