module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output [15:0] result,
    output [15:0] odd
);

reg [15:0] a_reg;
reg [7:0] b_reg;
reg [15:0] quotient;
reg [15:0] remainder;


always @(*) begin
    a_reg = A;
    b_reg = B;
end


always @(*) begin
    quotient = 16'b0;
    remainder = 16'b0;


    reg [7:0] upper_part = a_reg[15:8];
    reg [7:0] rem1 = upper_part;
    reg [7:0] sub_rem;

    if (rem1 >= b_reg) begin
        sub_rem = rem1 - b_reg;
        quotient[15] = 1'b1;
    end else begin
        sub_rem = rem1;
        quotient[15] = 1'b0;
    end


    integer i;
    reg [2:0] pos;
    pos = 0;
    for (i = 7;
 i >= 0;
 i = i - 1) begin
        if (a_reg[i] && pos == 0)
            pos = i;
    end


    reg [8:0] new_rem = {sub_rem, a_reg[pos]};
    if (new_rem >= {1'b0, b_reg}) begin
        remainder[8:0] = new_rem - {1'b0, b_reg};
        quotient[14] = 1'b1;
    end else begin
        remainder[8:0] = new_rem;
        quotient[14] = 1'b0;
    end


    reg [7:0] lower_part = a_reg[7:0];
    reg [8:0] rem3 = remainder[8:0];
    for (i = 7;
 i >= 0;
 i = i - 1) begin
        rem3 = (rem3 << 1) | lower_part[i];
        if (rem3 >= {1'b0, b_reg}) begin
            rem3 = rem3 - {1'b0, b_reg};
            quotient[14 - (7 - i)] = 1'b1;
        end else begin
            quotient[14 - (7 - i)] = 1'b0;
        end
    end
    remainder[15:9] = rem3[8:0];

end

assign result = quotient;
assign odd = remainder;

endmodule

