wire [7:0] mul_b_ext = {4'b0, mul_b};



wire [7:0] partial_products [0:3];
genvar i;
generate
    for (i=0;
 i<size;
 i=i+1) begin : gen_partial
        assign partial_products[i] = mul_b[i] ? (mul_a_ext << i) : 8'b0;
    end
endgenerate


wire [7:0] sum = partial_products[0] + partial_products[1] + partial_products[2] + partial_products[3];


reg [7:0] stage1_reg, stage2_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        stage1_reg <= 8'b0;
        stage2_reg <= 8'b0;
        mul_out <= 8'b0;
    end else begin
        stage1_reg <= sum;
        stage2_reg <= stage1_reg;
        mul_out <= stage2_reg;
    end
end

endmodule

