module accu (
    input clk,
    input rst_n,
    input [7:0] data_in,
    input valid_in,
    output reg valid_out,
    output [9:0] data_out
);

    reg [1:0] count;
    reg [9:0] sum_reg;
    wire [9:0] data_in_ext = {2'b0, data_in};

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sum_reg <= 10'b0;
            count <= 2'b0;
            valid_out <= 1'b0;
        end else begin
            valid_out <= 1'b0;
            if (valid_in) begin
                if (count == 2'b11) begin
                    valid_out <= 1'b1;
                    sum_reg <= 10'b0;
                    count <= 2'b00;
                end else begin
                    sum_reg <= sum_reg + data_in_ext;
                    count <= count + 1'b1;
                end
            end
        end
    end

    assign data_out = valid_out ? (sum_reg + data_in_ext) : 10'b0;

endmodule

