module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

wire a_sign = a[N-1];
wire b_sign = b[N-1];
wire [N-2:0] a_mag = a[N-2:0];
wire [N-2:0] b_mag = b[N-2:0];

wire [N-1:0] sum_mag_same = {1'b0, a_mag} + {1'b0, b_mag};
wire [N-2:0] sub_a = a_mag - b_mag;
wire [N-2:0] sub_b = b_mag - a_mag;

always @* begin
    if (a_sign == b_sign) begin
        c[N-1] = a_sign;
        c[N-2:0] = sum_mag_same[N-2:0];
    end else begin
        if (a_mag > b_mag) begin
            c[N-1] = a_sign;
            c[N-2:0] = sub_a;
        end else if (b_mag > a_mag) begin
            c[N-1] = b_sign;
            c[N-2:0] = sub_b;
        end else begin
            c[N-1] = 1'b0;
            c[N-2:0] = 0;
        end
    end
end

endmodule

