module fixed_point_subtractor #(
    parameter Q = 8,
    parameter N = 16
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

    reg [N-1:0] res;

    wire sign_a = a[N-1];
    wire sign_b = b[N-1];

    wire [N-1:0] a_abs = sign_a ? (~a + 1) : a;
    wire [N-1:0] b_abs = sign_b ? (~b + 1) : b;

    wire same_sign = (sign_a == sign_b);

    always @(*) begin
        if (same_sign) begin

            res = {sign_a, (a - b)[N-2:0]};

            if (res == 0) begin
                res = 0;
            end
        end else begin

            wire [N-1:0] sum_abs = a_abs + b_abs;
            reg result_sign;

            if (sign_a == 0 && sign_b == 1) begin

                result_sign = (a_abs > b_abs) ? 1'b0 : 1'b1;
            end else begin

                result_sign = (a_abs > b_abs) ? 1'b0 : 1'b1;
            end

            res = {result_sign, sum_abs[N-2:0]};

            if (res == 0) begin
                res = 0;
            end
        end
    end

    assign c = res;

endmodule

