module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa, z_mantissa;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;
    reg [47:0] product_shifted;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'd0;
            z <= 32'd0;
        end else begin
            case (counter)
                3'd0: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= (a[30:23] == 8'd0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                    b_mantissa <= (b[30:23] == 8'd0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};


                    if ((a[30:23] == 8'hff && a[22:0] != 0) || (b[30:23] == 8'hff && b[22:0] != 0)) begin
                        z <= 32'h7fc00000;

                    end else if ((a[30:23] == 8'hff && a[22:0] == 0) || (b[30:23] == 8'hff && b[22:0] == 0)) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'd0};

                    end else if ((a[30:23] == 8'd0 && a[22:0] == 23'd0) || (b[30:23] == 8'd0 && b[22:0] == 23'd0)) begin
                        z <= {a_sign ^ b_sign, 8'd0, 23'd0};

                    end else begin
                        product <= a_mantissa * b_mantissa;
                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= a_exponent + b_exponent - 8'd127;
                        counter <= counter + 1;
                    end
                end

                3'd1: begin

                    if (product >= 48'h800000000000) begin
                        product_shifted <= product >> 1;
                        z_mantissa <= {1'b1, product_shifted[46:23]};
                        guard_bit <= product_shifted[22];
                        round_bit <= product_shifted[21];
                        sticky <= |product_shifted[20:0];
                    end else begin
                        product_shifted <= product;
                        z_mantissa <= {1'b1, product_shifted[47:24]};
                        guard_bit <= product_shifted[23];
                        round_bit <= product_shifted[22];
                        sticky <= |product_shifted[21:0];
                    end
                    counter <= counter + 1;
                end

                3'd2: begin

                    if ((guard_bit && (round_bit || sticky)) || (guard_bit && round_bit && z_mantissa[0])) begin
                        if (z_mantissa[23]) begin
                            z_mantissa <= z_mantissa >> 1;
                            z_exponent <= z_exponent + 1;
                        end else begin
                            z_mantissa <= z_mantissa + 1;
                        end
                    end
                    counter <= counter + 1;
                end

                3'd3: begin

                    if (z_mantissa[23]) begin
                        z_mantissa <= z_mantissa >> 1;
                        z_exponent <= z_exponent + 1;
                    end
                    if (z_exponent >= 255) begin
                        z <= {z_sign, 8'hff, 23'd0};

                    end else if (z_exponent <= 0) begin
                        z <= {z_sign, 8'd0, (z_mantissa != 0) ? z_mantissa[22:0] : 23'd0};

                    end else begin
                        z <= {z_sign, z_exponent[7:0], z_mantissa[22:0]};
                    end
                    counter <= 0;
                end

                default: counter <= 0;
            endcase
