module sub_64bit (
    input [63:0] A,
    input [63:0] B,
    output [63:0] result,
    output overflow
);

assign result = A - B;

wire a_sign = A[63];
wire b_sign = B[63];
wire res_sign = result[63];

assign overflow = ( (a_sign == 1'b0) && (b_sign == 1'b1) && (res_sign == 1'b1) ) ||
                  ( (a_sign == 1'b1) && (b_sign == 1'b0) && (res_sign == 1'b0) );

