module fsm (
    input IN,
    input CLK,
    input RST,
    output reg MATCH
);

    parameter S0 = 3'b000;
    parameter S1 = 3'b001;
    parameter S2 = 3'b010;
    parameter S3 = 3'b011;
    parameter S4 = 3'b100;
    parameter S5 = 3'b101;

    reg [2:0] current_state, next_state;

    always @(posedge CLK or posedge RST) begin
        if (RST)
            current_state <= S0;
        else
            current_state <= next_state;
    end

    always @(*) begin
        case (current_state)
            S0: next_state = IN ? S1 : S0;
            S1: next_state = IN ? S1 : S2;
            S2: next_state = IN ? S1 : S3;
            S3: next_state = IN ? S4 : S3;
            S4: next_state = IN ? S5 : S0;
            S5: next_state = IN ? S1 : S0;
            default: next_state = S0;
        endcase
    end

    always @(*) begin
        if (RST)
            MATCH = 1'b0;
        else begin
            case (current_state)
                S4: MATCH = IN ? 1'b1 : 1'b0;
                S5: MATCH = IN ? 1'b1 : 1'b0;
                default: MATCH = 1'b0;
            endcase
        end
    end

endmodule

