module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    reg [1:0] state;
    localparam IDLE = 2'b00;
    localparam FIRST = 2'b01;
    localparam SECOND = 2'b10;

    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= IDLE;
            data_out <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (data_in == 1'b0) begin
                        state <= FIRST;
                        data_out <= 1'b0;
                    end else begin
                        state <= IDLE;
                        data_out <= 1'b0;
                    end
                end
                FIRST: begin
                    if (data_in == 1'b1) begin
                        state <= SECOND;
                        data_out <= 1'b0;
                    end else begin
                        state <= FIRST;
                        data_out <= 1'b0;
                    end
                end
                SECOND: begin
                    state <= IDLE;
                    data_out <= (data_in == 1'b0) ? 1'b1 : 1'b0;
                end
                default: begin
                    state <= IDLE;
                    data_out <= 1'b0;
                end
            endcase
        end
    end

endmodule

