module traffic_light (
    input rst_n,
    input clk,
    input pass_request,
    output [7:0] clock,
    output red,
    output yellow,
    output green
);

    parameter idle = 2'b00,
              s1_red = 2'b01,
              s2_yellow = 2'b10,
              s3_green = 2'b11;

    reg [1:0] state;
    reg p_red, p_yellow, p_green;
    reg [7:0] cnt;
    reg prev_red, prev_yellow, prev_green;


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            p_red <= 1'b0;
            p_yellow <= 1'b0;
            p_green <= 1'b0;
        end else begin
            case (state)
                idle: begin
                    state <= s1_red;
                    p_red <= 1'b1;
                    p_yellow <= 1'b0;
                    p_green <= 1'b0;
                end
                s1_red: begin
                    if (cnt == 0) begin
                        state <= s3_green;
                        p_red <= 1'b0;
                        p_yellow <= 1'b1;
                        p_green <= 1'b0;
                    end else begin
                        state <= s1_red;
                    end
                end
                s2_yellow: begin
                    if (cnt == 0) begin
                        state <= s1_red;
                        p_yellow <= 1'b0;
                        p_red <= 1'b1;
                        p_green <= 1'b0;
                    end else begin
                        state <= s2_yellow;
                    end
                end
                s3_green: begin
                    if (cnt == 0) begin
                        state <= s2_yellow;
                        p_green <= 1'b0;
                        p_yellow <= 1'b1;
                        p_red <= 1'b0;
                    end else begin
                        state <= s3_green;
                    end
                end
                default: state <= idle;
            endcase
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            prev_red <= 1'b0;
            prev_yellow <= 1'b0;
            prev_green <= 1'b0;
        end else begin
            prev_red <= p_red;
            prev_yellow <= p_yellow;
            prev_green <= p_green;
        end
    end


    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 10;
        end else begin
            if (pass_request && p_green && (cnt > 10)) begin
                cnt <= 10;
            end else if (p_green && !prev_green) begin
                cnt <= 60;
            end else if (p_yellow && !prev_yellow) begin
                cnt <= 5;
            end else if (p_red && !prev_red) begin
                cnt <= 10;
            end else begin
                cnt <= cnt - 1;
            end
        end
    end

    assign clock = cnt;
    assign red = p_red;
    assign yellow = p_yellow;
    assign green = p_green;

endmodule

