module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);

    reg [31:0] res;
    reg carry_reg, overflow_reg;
    reg flag_reg;
    wire [4:0] shamt = a[4:0];

    always @(*) begin
        res = 32'bz;
        carry_reg = 1'b0;
        overflow_reg = 1'b0;
        flag_reg = 1'bz;

        case (aluc)
            ADD: begin
                {carry_reg, res} = {1'b0, a} + {1'b0, b};
                overflow_reg = (a[31] == b[31]) && (res[31] != a[31]);
            end
            ADDU: begin
                res = a + b;
                carry_reg = (a + b) < a;
            end
            SUB: begin
                {carry_reg, res} = {1'b0, a} - {1'b0, b};
                overflow_reg = (a[31] != b[31]) && (res[31] != a[31]);
                carry_reg = ~carry_reg;
            end
            SUBU: begin
                res = a - b;
                carry_reg = (a < b);
            end
            AND: res = a & b;
            OR: res = a | b;
            XOR: res = a ^ b;
            NOR: res = ~(a | b);
            SLT: begin
                res = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
                flag_reg = 1'b1;
            end
            SLTU: begin
                res = (a < b) ? 32'd1 : 32'd0;
                flag_reg = 1'b1;
            end
            SLL: res = b << shamt;
            SRL: res = b >> shamt;
            SRA: res = $signed(b) >>> shamt;
            SLLV: res = b << shamt;
            SRLV: res = b >> shamt;
            SRAV: res = $signed(b) >>> shamt;
            LUI: res = {a[15:0], 16'b0};
            default: res = 32'bz;
        endcase
    end

    assign r = res;
    assign zero = (res == 32'b0);
    assign negative = res[31];
    assign overflow = overflow_reg;
    assign carry = carry_reg;
    assign flag = flag_reg;

endmodule

