module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [15:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] saved_dividend_abs, saved_divisor_abs;
    reg sign_reg;
    reg [7:0] quotient;
    reg [7:0] remainder;

    wire [15:0] abs_divisor = (sign_reg && saved_divisor_abs[7]) ? (~saved_divisor_abs + 1) : saved_divisor_abs;
    wire [15:0] NEG_DIVISOR = -abs_divisor;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            start_cnt <= 0;
            cnt <= 0;
            SR <= 0;
            saved_dividend_abs <= 0;
            saved_divisor_abs <= 0;
            sign_reg <= 0;
            quotient <= 0;
            remainder <= 0;
        end else begin
            if (opn_valid && !res_valid) begin
                sign_reg <= sign;
                saved_dividend_abs <= sign && dividend[7] ? (~dividend + 1) : dividend;
                saved_divisor_abs <= sign && divisor[7] ? (~divisor + 1) : divisor;
                SR <= {saved_dividend_abs, 8'b0} << 1;

                start_cnt <= 1;
                cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt) begin
                if (cnt == 8) begin
                    start_cnt <= 0;
                    cnt <= 0;
                    remainder <= SR[15:8];
                    quotient <= SR[7:0];
                    res_valid <= 1;
                end else begin
                    cnt <= cnt + 1;
                    reg [16:0] temp = SR + NEG_DIVISOR;
                    if (temp[16]) begin
                        quotient <= {quotient[6:0], 1'b1};
                    end else begin
                        quotient <= {quotient[6:0], 1'b0};
                    end
                    SR <= {temp[14:0], temp[15]};

                end
            end else begin
                res_valid <= res_valid;
            end
        end
    end

    always @(*) begin
        if (res_valid) begin
            reg [7:0] q = quotient;
            reg [7:0] r = remainder;
            if (sign_reg) begin
                if ((saved_dividend_abs[7] ^ saved_divisor_abs[7])) begin
                    q = -q;
                end
                if (saved_dividend_abs[7]) begin
                    r = -r;
                end
            end
            result = {r, q};
        end else begin
            result = 16'b0;
        end
    end

endmodule

