module fixed_point_adder #(
    parameter Q = 2,
    parameter N = 4
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

    reg [N-1:0] res;
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];
    wire msbs_same = (a_sign == b_sign);

    wire [N-1:0] a_abs = a_sign ? (~a + 1) : a;
    wire [N-1:0] b_abs = b_sign ? (~b + 1) : b;

    wire [N-1:0] sum_abs = a_abs + b_abs;
    wire [N-1:0] sub_res = (a_abs > b_abs) ? (a_abs - b_abs) : (b_abs - a_abs);

    wire [N-1:0] res_abs = msbs_same ? sum_abs : sub_res;
    wire res_sign = msbs_same ? a_sign : 1'b0;

    always @(*) begin
        res = {res_sign, res_abs[N-2:0]};
        c = res;
    end

endmodule

