module fixed_point_subtractor #(
    parameter Q = 8,
    parameter N = 16
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output wire [N-1:0] c
);

    reg [N-1:0] res_reg;

    always @(*) begin
        reg sign_a, sign_b;
        reg same_sign;
        reg [N-1:0] abs_a, abs_b;
        reg [N-1:0] sum_abs;
        reg sign_diff;

        sign_a = a[N-1];
        sign_b = b[N-1];
        same_sign = (sign_a == sign_b);

        if (same_sign) begin

            res_reg = a - b;
            res_reg[N-1] = sign_a;

        end else begin

            abs_a = sign_a ? (~a + 1) : a;
            abs_b = sign_b ? (~b + 1) : b;
            sum_abs = abs_a + abs_b;


            if (abs_a > abs_b) begin
                sign_diff = sign_a;
            end else if (abs_b > abs_a) begin
                sign_diff = sign_b;
            end else begin
                sign_diff = 1'b0;

            end

            res_reg = {sign_diff, sum_abs[N-2:0]};
        end


        if (res_reg == 0) begin
            res_reg = 0;
        end
    end

    assign c = res_reg;

endmodule

