module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

reg [2:0] counter;
reg a_sign, b_sign, z_sign;
reg [7:0] a_exponent, b_exponent, z_exponent;
reg [22:0] a_mantissa, b_mantissa;
reg [23:0] a_full_mantissa, b_full_mantissa;
reg [49:0] product;
reg guard_bit, round_bit, sticky;
reg [23:0] normalized_mantissa;
reg [9:0] exp_sum;
reg [47:0] product_reg;

always @(posedge clk) begin
    if (rst) begin
        counter <= 3'b0;
        z <= 32'b0;
        a_sign <= 0;
        b_sign <= 0;
        z_sign <= 0;
        a_exponent <= 0;
        b_exponent <= 0;
        z_exponent <= 0;
        a_mantissa <= 0;
        b_mantissa <= 0;
        a_full_mantissa <= 0;
        b_full_mantissa <= 0;
        product <= 0;
        guard_bit <= 0;
        round_bit <= 0;
        sticky <= 0;
        normalized_mantissa <= 0;
        exp_sum <= 0;
    end else begin
        case (counter)
            3'b000: begin 
                a_sign <= a[31];
                b_sign <= b[31];
                a_exponent <= a[30:23];
                b_exponent <= b[30:23];
                a_mantissa <= a[22:0];
                b_mantissa <= b[22:0];


                if (a_exponent == 8'hFF) begin
                    if (b_exponent == 8'hFF && |b_mantissa) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h000001};

                    end else if (b_exponent == 8'h00) begin
                        z <= {a_sign ^ b_sign, 8'hFF, 23'h000000};

                    end else begin
                        z_sign <= a_sign ^ b_sign;
                        z <= {z_sign, 8'hFF, 23'h000000};

                    end
                end else if (b_exponent == 8'hFF) begin
                    z_sign <= a_sign ^ b_sign;
                    z <= {z_sign, 8'hFF, 23'h000000};

                end else if (a_exponent == 8'h00 && |a_mantissa) begin 
                    if (b_exponent == 8'h00 && |b_mantissa) begin
                        z <= {a_sign ^ b_sign, 8'h00, 23'h000001};

                    end else begin
                        counter <= 3'b100;
                    end
                end else if (b_exponent == 8'h00 && |b_mantissa) begin 
                    z <= {a_sign ^ b_sign, 8'h00, 23'h000001};

                end else begin
                    counter <= 3'b001;
                end
            end

            3'b001: begin 
                exp_sum <= a_exponent + b_exponent - 9'd127;
                if (a_exponent == 8'h00) begin
                    a_full_mantissa <= {1'b0, a_mantissa};
                end else begin
                    a_full_mantissa <= {1'b1, a_mantissa};
                end
                if (b_exponent == 8'h00) begin
                    b_full_mantissa <= {1'b0, b_mantissa};
                end else begin
                    b_full_mantissa <= {1'b1, b_mantissa};
                end
                product <= a_full_mantissa * b_full_mantissa;
                counter <= 3'b010;
            end

            3'b010: begin 
                if (product[47]) begin
                    normalized_mantissa <= {1'b0, product[46:0]};
                    z_exponent <= exp_sum + 10'd1;
                end else begin
                    normalized_mantissa <= {1'b0, product[45:0], 1'b0};
                    z_exponent <= exp_sum + 10'd0;
                end
                counter <= 3'b011;
            end

            3'b011: begin 
                guard_bit <= normalized_mantissa[23];
                round_bit <= normalized_mantissa[22];
                sticky <= |normalized_mantissa[21:0];
                counter <= 3'b100;
            end

            3'b100: begin 
                if ((guard_bit && (round_bit || sticky)) || (guard_bit && !round_bit && !sticky && normalized_mantissa[0])) begin
                    normalized_mantissa <= normalized_mantissa + 24'd1;
                end
                counter <= 3'b101;
            end

            3'b101: begin 
                if (normalized_mantissa[23]) begin
                    z_exponent <= z_exponent + 10'd1;
                end
                if (z_exponent >= 10'hFF) begin 
                    z <= {z_sign, 8'hFF, 23'h000000};
                end else if (z_exponent == 0 && normalized_mantissa[22:0] == 0) begin 
                    z <= {z_sign, 31'd0};
                end else begin
                    z <= {z_sign, z_exponent[7:0], normalized_mantissa[22:0]};
                end
                counter <= 3'b000;
            end

            default: counter <= 3'b000;
        endcase
    end
end

endmodule

