module asyn_fifo #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wrstn,
    input winc,
    input [WIDTH-1:0] wdata,
    output reg rempty,
    output reg [WIDTH-1:0] rdata,
    output reg wfull,

    input rclk,
    input rrstn,
    input rinc
);


    dual_port_RAM #(
        .WIDTH(WIDTH),
        .DEPTH(DEPTH)
    ) ram (
        .wclk(wclk),
        .wenc(winc && !wfull),
        .waddr(wptr_bin),
        .wdata(wdata),
        .rclk(rclk),
        .renc(rinc && !rempty),
        .raddr(rptr_bin),
        .rdata(rdata)
    );


    reg [3:0] wptr_bin, wptr_gray;
    function [3:0] bin2gray;
        input [3:0] bin;
        bin2gray = bin ^ (bin >> 1);
    endfunction
    always @(posedge wclk or negedge wrstn) begin
        if (~wrstn) wptr_bin <= 0;
        else if (winc && !wfull) wptr_bin <= wptr_bin + 1;
    end
    always @(*) wptr_gray = bin2gray(wptr_bin);


    reg [3:0] rptr_bin, rptr_gray;
    always @(posedge rclk or negedge rrstn) begin
        if (~rrstn) rptr_bin <= 0;
        else if (rinc && !rempty) rptr_bin <= rptr_bin + 1;
    end
    always @(*) rptr_gray = bin2gray(rptr_bin);


    reg [3:0] rptr_gray_sync1, rptr_gray_sync2;
    reg [3:0] wptr_gray_sync1, wptr_gray_sync2;
    always @(posedge wclk or negedge wrstn) begin
        if (~wrstn) begin
            rptr_gray_sync1 <= 0;
            rptr_gray_sync2 <= 0;
        end else begin
            rptr_gray_sync1 <= rptr_gray;
            rptr_gray_sync2 <= rptr_gray_sync1;
        end
    end
    always @(posedge rclk or negedge rrstn) begin
        if (~rrstn) begin
            wptr_gray_sync1 <= 0;
            wptr_gray_sync2 <= 0;
        end else begin
            wptr_gray_sync1 <= wptr_gray;
            wptr_gray_sync2 <= wptr_gray_sync1;
        end
    end


    always @(*) begin
        rempty = (rptr_gray == wptr_gray_sync2);
        wfull = (wptr_gray == {~rptr_gray_sync2[3], ~rptr_gray_sync2[2], rptr_gray_sync2[1:0]});
    end

endmodule

module dual_port_RAM #(
    parameter WIDTH = 8,
    parameter DEPTH = 16
) (
    input wclk,
    input wenc,
    input [$clog2(DEPTH)-1:0] waddr,
    input [WIDTH-1:0] wdata,
    input rclk,
    input renc,
    input [$clog2(DEPTH)-1:0] raddr,
    output reg [WIDTH-1:0] rdata
);

    reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

    always @(posedge wclk) begin
        if (wenc) RAM_MEM[waddr] <= wdata;
    end

    always @(posedge rclk) begin
        if (renc) rdata <= RAM_MEM[raddr];
    end

endmodule

