module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

reg [1:0] state;
localparam IDLE  = 2'b00;
localparam S1    = 2'b01;
localparam S2    = 2'b10;

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        state <= IDLE;
    end else begin
        case (state)
            IDLE: state <= (data_in) ? S1 : IDLE;
            S1:   state <= (data_in) ? IDLE : S2;
            S2:   state <= IDLE;
            default: state <= IDLE;
        endcase
    end
end

always @(*) begin
    data_out = (state == S2) ? 1'b1 : 1'b0;
end

endmodule

