module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);
    reg [15:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] dividend_abs, divisor_abs;
    reg div_sign, div_sign_stored;
    reg quo_sign, rem_sign;
    reg [15:0] NEG_DIVISOR;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 0;
            result <= 16'b0;
            cnt <= 0;
            start_cnt <= 0;
            dividend_abs <= 0;
            divisor_abs <= 0;
            div_sign <= 0;
            div_sign_stored <= 0;
            quo_sign <= 0;
            rem_sign <= 0;
            SR <= 0;
        end else begin
            if (opn_valid && !res_valid) begin

                div_sign_stored <= sign && dividend[7];
                div_sign <= sign;
                dividend_abs <= sign ? ((dividend[7]) ? (~dividend + 1) : dividend) : dividend;
                divisor_abs <= sign ? ((divisor[7]) ? (~divisor + 1) : divisor) : divisor;
                quo_sign <= div_sign_stored ^ (sign && divisor[7]);
                rem_sign <= div_sign_stored;
                NEG_DIVISOR <= -{9'b0, divisor_abs};
                SR <= {dividend_abs, 1'b0} << 1;

                cnt <= 1;
                start_cnt <= 1;
                res_valid <= 0;
            end else if (start_cnt) begin
                if (cnt == 8) begin

                    reg [7:0] quo = SR[7:0];
                    reg [7:0] rem = SR[15:8];
                    if (quo_sign) quo = ~quo + 1;
                    if (sign) begin
                        rem = rem_sign ? (~rem + 1) : rem;
                    end
                    result <= {rem, quo};
                    res_valid <= 1;
                    start_cnt <= 0;
                    cnt <= 0;
                end else begin

                    reg [8:0] sub_result = {1'b0, SR[15:8]} - {9'b0, divisor_abs};
                    if (sub_result[8]) begin 
                        SR <= {SR[15:8], SR[7:0], 1'b0};
                    end else begin
                        SR <= {sub_result[7:0], SR[7:0], 1'b1};
                    end
                    cnt <= cnt + 1;
                end
            end
        end
    end
endmodule

