module div_16bit (
    input  [15:0] A,
    input  [7:0]  B,
    output reg [15:0] result,
    output reg [15:0] odd
);

    reg [15:0] a_reg, b_reg;


    always @(*) begin
        a_reg = A;
        b_reg = B;
    end


    always @(*) begin
        reg [15:0] dividend = a_reg;
        reg [15:0] quotient = 16'b0;
        reg [15:0] remainder = 16'b0;
        integer i;

        for (i = 15;
 i >= 0;
 i = i - 1) begin

            remainder = remainder << 1;
            remainder[0] = dividend[15];
            dividend = dividend << 1;


            if (remainder[15:8] >= b_reg) begin
                remainder[15:8] = remainder[15:8] - b_reg;
                quotient = {quotient[14:0], 1'b1};
            end else begin
                quotient = {quotient[14:0], 1'b0};
            end
        end

        result = quotient;
        odd = remainder;
    end

endmodule

