module fixed_point_subtractor #(
    parameter Q = 4,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;
reg sign_a, sign_b;

always @(*) begin
    sign_a = a[N-1];
    sign_b = b[N-1];

    if (sign_a == sign_b) begin

        res = a - b;
        if (res == 0)
            res[N-1] = 1'b0;

        else
            res[N-1] = sign_a;

    end else begin

        reg [N-1:0] abs_a = sign_a ? (~a + 1) : a;
        reg [N-1:0] abs_b = sign_b ? (~b + 1) : b;
        if (abs_a > abs_b)
            res = {1'b0, abs_a - abs_b[N-2:0]};

        else
            res = {1'b1, abs_b - abs_a[N-2:0]};

    end
    c = res;
end

endmodule

