module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa;
    reg [47:0] product;
    reg [4:0] guard_bit, round_bit, sticky;
    reg [22:0] z_mantissa;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            case (counter)
                3'b000: begin  
                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];
                    a_mantissa <= {1'b1, a[22:0]};
                    b_mantissa <= {1'b1, b[22:0]};
                    counter <= 3'b001;
                end

                3'b001: begin  
                    if (a_exponent == 8'hff && (a[22:0] != 0) || 
                        b_exponent == 8'hff && (b[22:0] != 0)) begin
                        z <= 32'h7FC00000;

                        counter <= 3'b111;
                    end else if (a_exponent == 8'hff) begin  
                        if (b_exponent == 0 && (b[22:0] == 0)) begin
                            z <= 32'h7FC00000;

                        end else begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'b0};

                        end
                        counter <= 3'b111;
                    end else if (b_exponent == 8'hff) begin
                        if (a_exponent == 0 && (a[22:0] == 0)) begin
                            z <= 32'h7FC00000;

                        end else begin
                            z <= {a_sign ^ b_sign, 8'hFF, 23'b0};
                        end
                        counter <= 3'b111;
                    end else if (a_exponent == 0 && (a[22:0] == 0)) begin  
                        if (b_exponent == 0 && (b[22:0] == 0)) begin
                            z <= 32'h7FC00000;

                        end else begin
                            z <= 32'b0;
                        end
                        counter <= 3'b111;
                    end else if (b_exponent == 0 && (b[22:0] == 0)) begin
                        if (a_exponent == 0 && (a[22:0] == 0)) begin
                            z <= 32'b0;

                        end else begin
                            z <= 32'b0;
                        end
                        counter <= 3'b111;
                    end else begin
                        product <= a_mantissa * b_mantissa;

                        counter <= 3'b010;
                    end
                end

                3'b010: begin  
                    if (product[47]) begin
                        product <= product >> 1;
                        z_exponent <= a_exponent + b_exponent - 8'd127 + 1;
                    end else begin
                        z_exponent <= a_exponent + b_exponent - 8'd127;
                    end
                    counter <= 3'b011;
                end

                3'b011: begin  
                    guard_bit <= product[46];
                    round_bit <= product[45];
                    sticky <= |product[44:0];
                    z_mantissa <= product[47] ? product[46:24] : product[45:23];
                    counter <= 3'b100;
                end

                3'b100: begin  
                    if (guard_bit && (round_bit | sticky) || (guard_bit && !round_bit && !sticky && z_mantissa[0])) begin
                        z_mantissa <= z_mantissa + 1;
                        if (z_mantissa == 23'h7FFFFF) begin  
                            z_mantissa <= 23'b0;
                            z_exponent <= z_exponent + 1;
                        end
                    end
                    counter <= 3'b101;
                end

                3'b101: begin  
                    if (z_exponent > 8'hFE) begin  
                        z <= {z_sign, 8'hFF, 23'b0};
                    end else if (z_exponent < 8'h01) begin  
                        z <= {z_sign, 31'b0};
                    end else begin
                        z <= {z_sign, z_exponent, z_mantissa};
                    end
                    counter <= 3'b000;
                end

                default: counter <= 3'b000;
            endcase
        end
    end

endmodule

