module LIFObuffer (
    input Clk,
    input Rst,
    input EN,
    input RW,
    input [3:0] dataIn,
    output EMPTY,
    output FULL,
    output reg [3:0] dataOut
);

    reg [2:0] SP;

    reg [3:0] stack_mem [0:3];



    assign EMPTY = (SP == 3'd4);
    assign FULL = (SP == 3'd4);

    always @(posedge Clk) begin
        if (Rst) begin

            for (integer i = 0;
 i < 4;
 i = i + 1)
                stack_mem[i] <= 4'b0;
            SP <= 3'd4;
        end else if (EN) begin
            if (!RW) begin 
                if (SP != 3'd4) begin
                    stack_mem[SP] <= dataIn;

                    SP <= SP + 1;

                end
            end else begin 
                if (SP != 3'd0) begin
                    dataOut <= stack_mem[SP - 1];

                    stack_mem[SP - 1] <= 4'b0;

                    SP <= SP - 1;

                end
            end
        end
    end

endmodule

