module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

    reg [1:0] state;

    localparam IDLE  = 2'b00,
               WAIT_1 = 2'b01,
               WAIT_2 = 2'b10;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            data_out <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (data_in == 1'b0) begin
                        state <= WAIT_1;
                        data_out <= 1'b0;
                    end else begin
                        state <= IDLE;
                        data_out <= 1'b0;
                    end
                end
                WAIT_1: begin
                    if (data_in == 1'b1) begin
                        state <= WAIT_2;
                        data_out <= 1'b0;
                    end else begin
                        state <= IDLE;
                        data_out <= 1'b0;
                    end
                end
                WAIT_2: begin
                    if (data_in == 1'b0) begin
                        state <= IDLE;
                        data_out <= 1'b1;
                    end else begin
                        state <= IDLE;
                        data_out <= 1'b0;
                    end
                end
                default: begin
                    state <= IDLE;
                    data_out <= 1'b0;
                end
            endcase
        end
    end

endmodule

