    if (!rst_n) begin
        a_prev <= 1'b0;
        rise <= 1'b0;
        down <= 1'b0;
    end else begin
        rise <= (a_prev == 1'b0) && (a == 1'b1);
        down <= (a_prev == 1'b1) && (a == 1'b0);
        a_prev <= a;
    end
end

