            if (data_ready) begin
                temp_data <= {stored_data, data_in};
                output_pending <= 1'b1;
                data_ready <= 1'b0;
            end else begin
                stored_data <= data_in;
                data_ready <= 1'b1;
            end
        end

        if (output_pending) begin
            data_out <= temp_data;
            valid_out <= 1'b1;
            output_pending <= 1'b0;
        end
    end
end

