module signal_generator (
    input clk,
    input rst_n,
    output reg [4:0] wave
);

reg state;
reg [4:0] next_wave;
reg next_state;

always @(*) begin
    case (state)
        0: next_wave = wave + 1;
        1: next_wave = wave - 1;
    endcase

    if (state == 0)
        next_state = (next_wave == 31) ? 1 : 0;
    else
        next_state = (next_wave == 0) ? 0 : 1;
end

always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        state <= 1'b0;
        wave <= 5'b0;
    end else begin
        wave <= next_wave;
        state <= next_state;
    end
end

endmodule

