module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output reg negative,
    output reg overflow,
    output reg flag
);

    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;

    reg [31:0] r_temp;
    reg carry_temp, overflow_temp;
    reg flag_temp;

    assign zero = (r == 32'b0);
    assign negative = r[31];

    always @(*) begin
        case (aluc)
            ADD: begin
                {carry_temp, r_temp} = {1'b0, a} + {1'b0, b};
                overflow_temp = (a[31] == b[31]) && (r_temp[31] != a[31]);
            end
            ADDU: begin
                {carry_temp, r_temp} = {1'b0, a} + {1'b0, b};
                overflow_temp = 1'b0;
            end
            SUB: begin
                {carry_temp, r_temp} = {1'b0, a} - {1'b0, b};
                overflow_temp = (a[31] != b[31]) && (r_temp[31] != a[31]);
            end
            SUBU: begin
                {carry_temp, r_temp} = {1'b0, a} - {1'b0, b};
                overflow_temp = 1'b0;
            end
            AND: begin
                r_temp = a & b;
                carry_temp = 1'b0;
                overflow_temp = 1'b0;
            end
            OR: begin
                r_temp = a | b;
                carry_temp = 1'b0;
                overflow_temp = 1'b0;
            end
            XOR: begin
                r_temp = a ^ b;
                carry_temp = 1'b0;
                overflow_temp = 1'b0;
            end
            NOR: begin
                r_temp = ~(a | b);
                carry_temp = 1'b0;
                overflow_temp = 1'b0;
            end
            SLT: begin
                r_temp = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
                carry_temp = 1'b0;
                overflow_temp = 1'b0;
            end
            SLTU: begin
                r_temp = (a < b) ? 32'd1 : 32'd0;
                carry_temp = 1'b0;
                overflow_temp = 1'b0;
            end
            SLL: begin
                r_temp = b << a[4:0];
                carry_temp = 1'b0;
                overflow_temp = 1'b0;
            end
            SRL: begin
                r_temp = b >> a[4:0];
                carry_temp = 1'b0;
                overflow_temp = 1'b0;
            end
            SRA: begin
                r_temp = $signed(b) >>> a[4:0];
                carry_temp = 1'b0;
                overflow_temp = 1'b0;
            end
            SLLV: begin
                r_temp = b << a[4:0];
                carry_temp = 1'b0;
                overflow_temp = 1'b0;
            end
            SRLV: begin
                r_temp = b >> a[4:0];
                carry_temp = 1'b0;
                overflow_temp = 1'b0;
            end
            SRAV: begin
                r_temp = $signed(b) >>> a[4:0];
                carry_temp = 1'b0;
                overflow_temp = 1'b0;
            end
            LUI: begin
                r_temp = {a[15:0], 16'b0};
                carry_temp = 1'b0;
                overflow_temp = 1'b0;
            end
            default: begin
                r_temp = 32'bz;
                carry_temp = 1'bz;
                overflow_temp = 1'bz;
            end
        endcase

        if (aluc == SLT || aluc == SLTU)
            flag_temp = r_temp[0];
        else
            flag_temp = 1'bz;

        r = r_temp;
        carry = carry_temp;
        overflow = overflow_temp;
        flag = flag_temp;
    end

endmodule

