module div_16bit (
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

    reg [15:0] a_reg;
    reg [7:0] b_reg;

    always @* begin
        a_reg = A;
        b_reg = B;
    end

    always @* begin
        reg [7:0] remainder;
        reg [7:0] lower_part;
        reg [7:0] highest_bit_mask;
        integer i;


        if (a_reg[15:8] >= b_reg) begin
            result[15] = 1'b1;
            remainder = a_reg[15:8] - b_reg;
        end else begin
            result[15] = 1'b0;
            remainder = a_reg[15:8];
        end


        lower_part = a_reg[7:0];
        highest_bit_mask = 8'b0;
        for (i = 7;
 i >= 0;
 i = i - 1) begin
            if (lower_part[i]) begin
                highest_bit_mask = 8'b1 << i;
                break;
            end
        end


        result = 16'b0;
        result[15] = a_reg[15] & (b_reg == 8'b0) ? 1'b0 : result[15];

        result[14:0] = 15'b0;


        odd = {remainder, highest_bit_mask};
    end

endmodule

