module fixed_point_adder #(
    parameter Q = 4,
    parameter N = 8
) (
    input [N-1:0] a,
    input [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;

wire sign_a = a[N-1];
wire sign_b = b[N-1];

wire [N-2:0] mag_a = sign_a ? (~a[N-2:0] + 1) : a[N-2:0];
wire [N-2:0] mag_b = sign_b ? (~b[N-2:0] + 1) : b[N-2:0];

wire same_sign = (sign_a == sign_b);

reg [N-2:0] res_mag;
reg res_sign;

always @(*) begin
    if (same_sign) begin
        res_sign = sign_a;
        res_mag = mag_a + mag_b;
    end else begin
        if (mag_a > mag_b) begin
            res_sign = sign_a;
            res_mag = mag_a - mag_b;
        end else if (mag_b > mag_a) begin
            res_sign = sign_b;
            res_mag = mag_b - mag_a;
        end else begin
            res_sign = 1'b0;
            res_mag = {N-2{1'b0}};
        end
    end
end

always @(*) begin
    c = {res_sign, res_mag};
end

endmodule

