    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, temp_exponent;
    reg [22:0] a_mantissa, b_mantissa;
    reg [23:0] a_mantissa_full, b_mantissa_full;
    reg [47:0] product;
    reg [47:0] normalized_product;
    reg guard, round, sticky;
    reg [22:0] rounded_mantissa;
    reg [8:0] adjusted_exponent;

    wire a_is_nan = (a[30:23] == 8'hff) && (a[22:0] != 0);
    wire a_is_inf = (a[30:23] == 8'hff) && (a[22:0] == 0);
    wire a_is_zero = (a[30:23] == 8'h00) && (a[22:0] == 0);
    wire b_is_nan = (b[30:23] == 8'hff) && (b[22:0] != 0);
    wire b_is_inf = (b[30:23] == 8'hff) && (b[22:0] == 0);
    wire b_is_zero = (b[30:23] == 8'h00) && (b[22:0] == 0);

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
            a_sign <= 0;
            b_sign <= 0;
            a_exponent <= 0;
            b_exponent <= 0;
            temp_exponent <= 0;
            a_mantissa_full <= 0;
            b_mantissa_full <= 0;
            product <= 0;
            normalized_product <= 0;
            guard <= 0;
            round <= 0;
            sticky <= 0;
            rounded_mantissa <= 0;
            adjusted_exponent <= 0;
        end else begin
            case (counter)
                3'b000: begin

                    if (a_is_nan || b_is_nan) begin
                        z_sign <= a[31] ^ b[31];
                        z <= {z_sign, 8'hff, 23'h000001};
                        counter <= 3'b000;
                    end else if (a_is_inf || b_is_inf) begin
                        if ((a_is_inf && b_is_zero) || (a_is_zero && b_is_inf)) begin
                            z_sign <= a[31] ^ b[31];
                            z <= {z_sign, 8'hff, 23'h000001};
                        end else begin
                            z_sign <= a[31] ^ b[31];
                            z <= {z_sign, 8'hff, 23'b0};
                        end
                        counter <= 3'b000;
                    end else if (a_is_zero || b_is_zero) begin
                        z_sign <= a[31] ^ b[31];
                        z <= {z_sign, 8'h00, 23'b0};
                        counter <= 3'b000;
                    end else begin

                        a_sign <= a[31];
                        a_exponent <= a[30:23];
                        a_mantissa_full <= (a[30:23] == 8'd0) ? {1'b0, a[22:0]} : {1'b1, a[22:0]};
                        b_sign <= b[31];
                        b_exponent <= b[30:23];
                        b_mantissa_full <= (b[30:23] == 8'd0) ? {1'b0, b[22:0]} : {1'b1, b[22:0]};
                        temp_exponent <= a[30:23] + b[30:23] - 8'd127;
                        product <= a_mantissa_full * b_mantissa_full;
                        counter <= counter + 1;
                    end
                end
                3'b001: begin

                    integer i;
                    reg [47:0] temp_product;
                    reg [47:0] shifted_product;
                    reg [4:0] shift_count;
                    reg [47:0] normalized_product_reg;

                    temp_product = product;
                    shift_count = 0;


                    for (i = 47;
 i >= 0;
 i = i - 1) begin
                        if (temp_product[i]) begin
                            break;
                        end
                        shift_count = shift_count + 1;
                    end

                    shifted_product = temp_product << shift_count;
                    normalized_product_reg = shifted_product;
                    adjusted_exponent = temp_exponent - shift_count;


                    guard = normalized_product_reg[23];
                    round = normalized_product_reg[22];
                    sticky = |normalized_product_reg[21:0];


                    if (guard && (round || sticky || normalized_product_reg[22])) begin
                        rounded_mantissa = normalized_product_reg[47:24] + 24'd1;
                        if (rounded_mantissa[23]) begin
                            adjusted_exponent = adjusted_exponent + 1;
                            rounded_mantissa = rounded_mantissa >> 1;
                        end
                    end else begin
                        rounded_mantissa = normalized_product_reg[47:24];
                    end

                    counter <= counter + 1;
                end
                3'b010: begin

                    if (adjusted_exponent >= 9'd255) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                    end else if (adjusted_exponent <= 9'd0) begin
                        z <= {a_sign ^ b_sign, 8'h00, rounded_mantissa[22:0]};
                    end else begin
                        z <= {a_sign ^ b_sign, adjusted_exponent[7:0], rounded_mantissa[22:0]};
                    end
                    counter <= 3'b000;
                end
                default: counter <= 3'b000;
            endcase
        end
    end

endmodule

