module alu (
    input [31:0] a, b,
    input [5:0] aluc,
    output [31:0] r,
    output zero,
    output carry,
    output negative,
    output overflow,
    output flag
);

    parameter ADD  = 6'b100000;
    parameter ADDU = 6'b100001;
    parameter SUB  = 6'b100010;
    parameter SUBU = 6'b100011;
    parameter AND  = 6'b100100;
    parameter OR   = 6'b100101;
    parameter XOR  = 6'b100110;
    parameter NOR  = 6'b100111;
    parameter SLT  = 6'b101010;
    parameter SLTU = 6'b101011;
    parameter SLL  = 6'b000000;
    parameter SRL  = 6'b000010;
    parameter SRA  = 6'b000011;
    parameter SLLV = 6'b000100;
    parameter SRLV = 6'b000110;
    parameter SRAV = 6'b000111;
    parameter LUI  = 6'b001111;

    reg [32:0] res;
    wire slt_result = ($signed(a) < $signed(b)) ? 1'b1 : 1'b0;
    wire sltu_result = (a < b) ? 1'b1 : 1'b0;

    assign r = res[31:0];
    assign zero = (r == 32'b0);
    assign negative = r[31];
    assign carry = (aluc == ADD || aluc == ADDU || aluc == SUB || aluc == SUBU) ? res[32] : 1'b0;
    assign overflow = (aluc == ADD || aluc == SUB) ? (res[32] ^ res[31]) : 1'b0;
    assign flag = (aluc == SLT || aluc == SLTU) ? (aluc == SLT ? slt_result : sltu_result) : 1'bz;

    always @(*) begin
        case (aluc)
            ADD:  res = {1'b0, a} + {1'b0, b};
            ADDU: res = {1'b0, a} + {1'b0, b};
            SUB:  res = {1'b0, a} - {1'b0, b};
            SUBU: res = {1'b0, a} - {1'b0, b};
            AND:  res = {1'b0, a & b};
            OR:   res = {1'b0, a | b};
            XOR:  res = {1'b0, a ^ b};
            NOR:  res = {1'b0, ~(a | b)};
            SLT:  res = {1'b0, slt_result};
            SLTU: res = {1'b0, sltu_result};
            SLL:  res = {1'b0, a << b[4:0]};
            SRL:  res = {1'b0, a >> b[4:0]};
            SRA:  res = {1'b0, $signed(a) >>> b[4:0]};
            SLLV: res = {1'b0, a << a[4:0]};
            SRLV: res = {1'b0, a >> a[4:0]};
            SRAV: res = {1'b0, $signed(a) >>> a[4:0]};
            LUI:  res = {a[31:16], 16'b0};
            default: res = 33'bz;
        endcase
    end

endmodule

