module radix2_div (
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    output reg res_valid,
    output reg [15:0] result
);

    reg [15:0] SR;
    reg [3:0] cnt;
    reg start_cnt;
    reg [7:0] abs_dividend;
    reg [7:0] abs_divisor;
    reg dividend_sign, divisor_sign;
    reg [7:0] negated_divisor;

    always @(posedge clk) begin
        if (rst) begin
            res_valid <= 1'b0;
            SR <= 16'b0;
            cnt <= 4'b0;
            start_cnt <= 1'b0;
            abs_dividend <= 8'b0;
            abs_divisor <= 8'b0;
            dividend_sign <= 1'b0;
            divisor_sign <= 1'b0;
            negated_divisor <= 8'b0;
        end else begin
            if (opn_valid && !res_valid) begin

                if (sign) begin
                    dividend_sign <= dividend[7];
                    divisor_sign <= divisor[7];
                    abs_dividend <= dividend[7] ? -dividend : dividend;
                    abs_divisor <= divisor[7] ? -divisor : divisor;
                    negated_divisor <= -divisor;
                end else begin
                    dividend_sign <= 1'b0;
                    divisor_sign <= 1'b0;
                    abs_dividend <= dividend;
                    abs_divisor <= divisor;
                    negated_divisor <= -divisor;
                end


                SR <= {abs_dividend, 8'b0} << 1;
                cnt <= 4'b1;
                start_cnt <= 1'b1;
                res_valid <= 1'b0;
            end else if (start_cnt) begin
                if (cnt == 8) begin

                    start_cnt <= 1'b0;
                    cnt <= 4'b0;
                    reg [7:0] rem = SR[15:8];
                    reg [7:0] quo = SR[7:0];

                    if (sign) begin
                        rem = dividend_sign ? -rem : rem;
                        quo = (dividend_sign ^ divisor_sign) ? -quo : quo;
                    end
                    result <= {rem, quo};
                    res_valid <= 1'b1;
                end else begin

                    reg [7:0] rem = SR[15:8];
                    reg [7:0] quo = SR[7:0];
                    reg [7:0] temp_rem = rem + abs_divisor;
                    reg carry = (temp_rem >= rem) ? 1'b1 : 1'b0;

                    SR <= {carry ? temp_rem : rem, {quo[6:0], carry}};
                    cnt <= cnt + 1;
                end
            end else begin
                res_valid <= 1'b0;
            end
        end
    end

endmodule

