module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign;
    reg [8:0] a_exponent, b_exponent;
    reg [23:0] a_mantissa, b_mantissa;
    reg [49:0] product;
    reg guard_bit, round_bit, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'b0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= {1'b0, a[30:23]};
                    b_exponent <= {1'b0, b[30:23]};
                    a_mantissa <= {1'b1, a[22:0]};
                    b_mantissa <= {1'b1, b[22:0]};

                    if (a_exponent == 9'd0 && b_exponent == 9'd0) begin
                        z <= {a_sign ^ b_sign, 31'b0};

                        counter <= 3'b111;

                    end else if (a_exponent == 9'd0 || b_exponent == 9'd0) begin
                        z <= 32'b0;

                        counter <= 3'b111;

                    end else if (a_exponent == 9'd255 || b_exponent == 9'd255) begin

                        if ((a_exponent == 9'd255 && |a_mantissa) || (b_exponent == 9'd255 && |b_mantissa)) begin
                            z <= {a_sign ^ b_sign, 8'hff, 1'b1, 22'b0};

                        end else if (a_exponent == 9'd255) begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'b0};

                        end else begin
                            z <= {a_sign ^ b_sign, 8'hff, 23'b0};
                        end
                        counter <= 3'b111;

                    end else begin
                        counter <= counter + 1;
                    end
                end

                3'b001: begin

                    product <= a_mantissa * b_mantissa;
                    counter <= counter + 1;
                end

                3'b010: begin

                    reg [49:0] temp_product = product;
                    reg [9:0] temp_exponent = a_exponent + b_exponent - 9'd127;
                    reg [23:0] mantissa;
                    reg guard, round, sticky;


                    if (temp_product[47]) begin
                        mantissa = temp_product[47:24];

                        guard = temp_product[23];
                        round = temp_product[22];
                        sticky = |temp_product[21:0];
                        temp_exponent = temp_exponent + 1;
                    end else begin
                        mantissa = temp_product[46:23];

                        guard = temp_product[22];
                        round = temp_product[21];
                        sticky = |temp_product[20:0];
                    end


                    if (guard && (round | sticky | mantissa[0])) begin
                        mantissa = mantissa + 1;
                        if (mantissa[23]) begin 
                            mantissa = mantissa >> 1;
                            temp_exponent = temp_exponent + 1;
                        end
                    end


                    if (temp_exponent >= 9'd255) begin
                        z <= {a_sign ^ b_sign, 8'hff, 23'b0};

                    end else if (temp_exponent == 9'd0) begin
                        z <= {a_sign ^ b_sign, 8'h00, 23'b0};

                    end else begin
                        z <= {a_sign ^ b_sign, temp_exponent[7:0], mantissa[22:0]};
                    end

                    counter <= 3'b000;
                end

                default: counter <= 3'b000;
            endcase
        end
    end

endmodule

