module fsm (
    input IN,
    input CLK,
    input RST,
    output MATCH
);


    localparam S0 = 3'b000,
               S1 = 3'b001,
               S2 = 3'b010,
               S3 = 3'b011,
               S4 = 3'b100;

    reg [2:0] current_state, next_state;


    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            current_state <= S0;
        end else begin
            current_state <= next_state;
        end
    end


    always @(*) begin
        case (current_state)
            S0: next_state = IN ? S1 : S0;
            S1: next_state = (IN == 0) ? S2 : S1;
            S2: next_state = (IN == 0) ? S3 : S0;
            S3: next_state = (IN == 1) ? S4 : S0;
            S4: next_state = (IN == 1) ? S1 : S0;
            default: next_state = S0;
        endcase
    end


    assign MATCH = RST ? 1'b0 : ((current_state == S4) && (IN == 1));

endmodule

