module LIFObuffer (
    input wire [3:0] dataIn,
    input wire RW,
    input wire EN,
    input wire Rst,
    input wire Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] stack_mem [0:3];
reg [2:0] SP;


integer i;

always @(posedge Clk) begin
    reg [2:0] next_SP;
    reg [3:0] next_stack_mem [0:3];
    reg [3:0] next_dataOut;


    next_SP = SP;
    next_dataOut = dataOut;
    for (i = 0;
 i < 4;
 i = i + 1)
        next_stack_mem[i] = stack_mem[i];

    if (Rst) begin
        next_SP = 3'b100;

        next_dataOut = 4'b0;
        for (i = 0;
 i < 4;
 i = i + 1)
            next_stack_mem[i] = 4'b0;
    end
    else if (EN) begin
        if (!FULL && !RW) begin 
            next_stack_mem[SP-1] = dataIn;
            next_SP = SP - 1;
        end
        else if (!EMPTY && RW) begin 
            next_dataOut = stack_mem[SP];
            next_stack_mem[SP] = 4'b0;
            next_SP = SP + 1;
        end
    end


    SP <= next_SP;
    for (i = 0;
 i < 4;
 i = i + 1)
        stack_mem[i] <= next_stack_mem[i];
    dataOut <= next_dataOut;
    EMPTY <= (next_SP == 3'b100);
    FULL <= (next_SP == 3'b000);
end

endmodule

