module pulse_detect (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);


reg [1:0] current_state, next_state;
parameter IDLE = 2'b00,
          STATE_1 = 2'b01,
          STATE_2 = 2'b10;


always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        current_state <= IDLE;
    end else begin
        current_state <= next_state;
    end
end


always @(*) begin
    case (current_state)
        IDLE:    next_state = (data_in == 1'b0) ? STATE_1 : IDLE;
        STATE_1: next_state = (data_in == 1'b1) ? STATE_2 : IDLE;
        STATE_2: next_state = IDLE;

        default: next_state = IDLE;
    endcase
end


always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        data_out <= 1'b0;
    end else begin
        case (current_state)
            STATE_2: data_out <= (data_in == 1'b0) ? 1'b1 : 1'b0;
            default: data_out <= 1'b0;
        endcase
    end
end

endmodule

