    if (!rst_n) begin
        prev_a <= 1'b0;
        rise <= 1'b0;
        down <= 1'b0;
    end else begin
        prev_a <= a;
        rise <= (prev_a == 1'b0) && (a == 1'b1);
        down <= (prev_a == 1'b1) && (a == 1'b0);
    end
end

