                    state_next = (wave + 1 == 5'd31) ? 1'b1 : 1'b0;
                end
                1'b1: begin
                    wave_next = wave - 1;
                    state_next = (wave - 1 == 5'd0) ? 1'b0 : 1'b1;
                end
            endcase
        end
    end

