module alu (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output flag
);


parameter ADD = 6'b100000;
parameter ADDU = 6'b100001;
parameter SUB = 6'b100010;
parameter SUBU = 6'b100011;
parameter AND = 6'b100100;
parameter OR = 6'b100101;
parameter XOR = 6'b100110;
parameter NOR = 6'b100111;
parameter SLT = 6'b101010;
parameter SLTU = 6'b101011;
parameter SLL = 6'b000000;
parameter SRL = 6'b000010;
parameter SRA = 6'b000011;
parameter SLLV = 6'b000100;
parameter SRLV = 6'b000110;
parameter SRAV = 6'b000111;
parameter LUI = 6'b001111;

reg [32:0] res;
reg [31:0] slt_result;
reg [4:0] shift_amount;

assign zero = (r == 32'b0);
assign negative = r[31];
assign flag = (aluc == SLT || aluc == SLTU) ? 1'b1 : 1'b0;

always @(*) begin
    res = 33'b0;
    overflow = 1'b0;
    carry = 1'b0;

    case (aluc)
        ADD: begin
            res = {1'b0, a} + {1'b0, b};
            carry = res[32];
            overflow = (a[31] == b[31]) && (res[31] != a[31]);
        end
        ADDU: begin
            res = {1'b0, a} + {1'b0, b};
            carry = res[32];
        end
        SUB: begin
            res = {1'b0, a} - {1'b0, b};
            carry = (a >= b) ? 1'b1 : 1'b0;
            overflow = (a[31] != b[31]) && (res[31] != a[31]);
        end
        SUBU: begin
            res = {1'b0, a} - {1'b0, b};
            carry = (a >= b) ? 1'b1 : 1'b0;
        end
        AND: res = {1'b0, a & b};
        OR: res = {1'b0, a | b};
        XOR: res = {1'b0, a ^ b};
        NOR: res = {1'b0, ~(a | b)};
        SLT: begin
            slt_result = ($signed(a) < $signed(b)) ? 32'd1 : 32'd0;
            res = {32'b0, slt_result};
        end
        SLTU: begin
            slt_result = (a < b) ? 32'd1 : 32'd0;
            res = {32'b0, slt_result};
        end
        SLL: begin
            shift_amount = b[4:0];
            res = {1'b0, a << shift_amount};
        end
        SRL: begin
            shift_amount = b[4:0];
            res = {1'b0, a >> shift_amount};
        end
        SRA: begin
            shift_amount = b[4:0];
            res = {1'b0, $signed(a) >>> shift_amount};
        end
        SLLV: begin
            shift_amount = a[4:0];
            res = {1'b0, b << shift_amount};
        end
        SRLV: begin
            shift_amount = a[4:0];
            res = {1'b0, b >> shift_amount};
        end
        SRAV: begin
            shift_amount = a[4:0];
            res = {1'b0, $signed(b) >>> shift_amount};
        end
        LUI: res = {a[31:16], 16'b0};
        default: res = 33'bz;
    endcase

    r = res[31:0];
end

endmodule

