module fixed_point_adder #(
    parameter Q = 2,
    parameter N = 8
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;

wire sign_a = a[N-1];
wire sign_b = b[N-1];
wire same_sign = (sign_a == sign_b);

wire [N-2:0] a_mag = a[N-2:0];
wire [N-2:0] b_mag = b[N-2:0];

wire a_gt_b = (a_mag > b_mag);
wire b_gt_a = (b_mag > a_mag);

always @(*) begin
    if (same_sign) begin

        res = {sign_a, a_mag + b_mag};
    end else begin
        if (a_gt_b) begin
            res = {sign_a, a_mag - b_mag};
        end else if (b_gt_a) begin
            res = {sign_b, b_mag - a_mag};
        end else begin

            res = {1'b0, {(N-1){1'b0}}};
        end
    end
end

always @(*) begin
    c = res;
end

endmodule

