module fixed_point_subtractor #(
    parameter Q = 8,
    parameter N = 16
) (
    input wire [N-1:0] a,
    input wire [N-1:0] b,
    output reg [N-1:0] c
);

reg [N-1:0] res;

always @* begin
    wire a_sign = a[N-1];
    wire b_sign = b[N-1];
    reg [N-1:0] abs_a = a_sign ? (~a + 1) : a;
    reg [N-1:0] abs_b = b_sign ? (~b + 1) : b;

    if (a_sign == b_sign) begin
        res = a - b;
    end else begin
        if (abs_a > abs_b) begin
            res = abs_a - abs_b;
            res[N-1] = 1'b0;
        end else if (abs_b > abs_a) begin
            res = abs_b - abs_a;
            res[N-1] = 1'b1;
        end else begin
            res = 0;
        end
    end

    if (res == 0) begin
        res = 0;
    end
end

assign c = res;

endmodule

