module float_multi (
    input clk,
    input rst,
    input [31:0] a,
    input [31:0] b,
    output reg [31:0] z
);

    reg [2:0] counter;
    reg a_sign, b_sign, z_sign;
    reg [7:0] a_exponent, b_exponent, z_exponent;
    reg [23:0] a_mantissa, b_mantissa, z_mantissa;
    reg [47:0] product;
    reg guard_bit, round_bit, sticky;

    always @(posedge clk) begin
        if (rst) begin
            counter <= 3'b0;
            z <= 32'd0;
        end else begin
            case (counter)
                3'b000: begin

                    a_sign <= a[31];
                    b_sign <= b[31];
                    a_exponent <= a[30:23];
                    b_exponent <= b[30:23];

                    a_mantissa <= (a[30:23] != 8'd0 && a[30:23] != 8'hff) ? {1'b1, a[22:0]} : {1'b0, a[22:0]};
                    b_mantissa <= (b[30:23] != 8'd0 && b[30:23] != 8'hff) ? {1'b1, b[22:0]} : {1'b0, b[22:0]};
                    counter <= 3'b001;
                end

                3'b001: begin

                    if ((a_exponent == 8'hff && b_exponent != 8'hff) || (a_exponent != 8'hff && b_exponent == 8'hff)) begin

                        z_sign <= a_sign ^ b_sign;
                        z_exponent <= 8'hff;
                        z_mantissa <= 24'd0;
                        counter <= 3'b111;
                    end else if (a_exponent == 8'hff || b_exponent == 8'hff) begin

                        if (a_exponent == 8'hff && b_exponent == 8'hff) begin
                            z_exponent <= 8'hff;
                            z_mantissa <= 24'h400000;

                        end else begin
                            z_exponent <= 8'hff;
                            z_mantissa <= 24'd0;

                        end
                        z_sign <= a_sign ^ b_sign;
                        counter <= 3'b111;
                    end else if (a_exponent == 8'd0 && b_exponent == 8'd0) begin

                        z_exponent <= 8'd0;
                        z_mantissa <= 24'd0;
                        z_sign <= a_sign ^ b_sign;
                        counter <= 3'b111;
                    end else if (a_exponent == 8'd0) begin

                        z_exponent <= 8'd0;
                        z_mantissa <= 24'd0;
                        z_sign <= b_sign;
                        counter <= 3'b111;
                    end else if (b_exponent == 8'd0) begin

                        z_exponent <= 8'd0;
                        z_mantissa <= 24'd0;
                        z_sign <= a_sign;
                        counter <= 3'b111;
                    end else begin

                        product <= a_mantissa * b_mantissa;
                        z_exponent <= a_exponent + b_exponent - 8'd127;
                        counter <= 3'b010;
                    end
                end

                3'b010: begin

                    if (product[47]) begin

                        z_mantissa <= product[46:23];
                        guard_bit <= product[22];
                        round_bit <= product[21];
                        sticky <= |product[20:0];
                        z_exponent <= z_exponent + 8'd1;
                    end else begin

                        z_mantissa <= product[47:24];
                        guard_bit <= product[23];
                        round_bit <= product[22];
                        sticky <= |product[21:0];
                    end
                    counter <= 3'b011;
                end

                3'b011: begin

                    reg round_up = 0;
                    reg [24:0] mantissa_rounded = {1'b0, z_mantissa} + (guard_bit & (round_bit | sticky));
                    if (mantissa_rounded[23]) begin

                        mantissa_rounded = {1'b0, z_mantissa} + 1;
                        z_exponent <= z_exponent + 8'd1;
                    end else begin
                        mantissa_rounded = {1'b0, z_mantissa} + (guard_bit & (round_bit | sticky));
                    end
                    z_mantissa <= mantissa_rounded[22:0];
                    counter <= 3'b100;
                end

                3'b100: begin

                    if (z_exponent >= 8'hff) begin

                        z_exponent <= 8'hff;
                        z_mantissa <= 24'd0;
                    end else if (z_exponent <= 8'd0) begin

                        z_exponent <= 8'd0;
                        z_mantissa <= 24'd0;
                    end
                    counter <= 3'b101;
                end

                3'b101: begin

                    z <= {z_sign, z_exponent, z_mantissa[22:0]};
                    counter <= 3'b000;
                end

                default: counter <= 3'b000;
            endcase
        end
    end

endmodule

